(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.4"]={"from":96,"a":[["\u0003קסברי רבנן\u0004 \u0005[סבורים חכמים\u0006\u0005]\u0006 כי רק בת כהן \u0003נשואה\u0004 שזנתה \u0003יוצאה לשריפה ולא\u0004 כשהיתה \u0003ארוסה,\u0004 שכל ארוסה שזנתה נידונה בסקילה, \u0003ומדאפקה רחמנא\u0004 \u0005[וממה שהוציאה התורה\u0006\u0005]\u0006 את ה\u0003ארוסה\u0004 אפילו בת כהן מכלל שאר נשואות לדונה \u0003בסקילה, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003סקילה חמורה\u0004 משריפה.","וראיה כי \u0003סקילה חמורה מסייף\u0004 — \u0003שכן ניתנה למגדף\u0004 (מקלל את ה') \u0003ולעובד עבודה זרה.\u0004 ושואלים: \u0003ומאי חומרא\u0004 \u0005[ומה החומרה\u0006\u0005]\u0006 שבאלו? ומשיבים: \u0003כדאמרן\u0004 \u0005[כפי שאמרנו\u0006\u0005]\u0006 שהוא פושט ידו בעיקר.","ומקשים: \u0003אדרבה\u0004 (להיפך), נאמר ש\u0003סייף\u0004 לכאורה \u0003חמור\u0004 מסקילה, \u0003שכן ניתן לאנשי עיר הנדחת\u0004 שאף הם כופרים בעיקר, \u0003ומאי חומרא\u0004 \u0005[ומה החומרה\u0006\u0005]\u0006 שיש בהם — \u0003שכן ממונן אבד,\u0004 שמשחיתים ומאבדים את כל רכושם ואת עירם!","ומשיבים: כנגד טענה זו \u0003אמרת\u0004 \u0005[אומר אתה\u0006\u0005]:\u0006 \u0003איזה כח מרובה\u0004 יותר, כלומר, איזהו העוון החמור יותר, \u0003כח המדיח\u0004 אחרים לעבירה, \u0003או כח הנידח? הוי אומר: כח המדיח ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003מדיחי עיר הנדחת\u0004 נדונים \u0003בסקילה,\u0004 משמע שסקילה חמורה מסייף.","\u0003סקילה חמורה מחנק,\u0004 וראיה לדבר — \u0003שכן ניתן\u0004 עונש סקילה \u0003למגדף ולעובד עבודה זרה, ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 שבכך — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו\u0006\u0005]\u0006 שהוא פושט ידו בעיקר.","ומקשים: \u0003אדרבה,\u0004 נאמר ש\u0003חנק חמור שכן ניתן למכה אביו ואמו, ומאי חומרא\u0004 \u0005[ומה החומרה\u0006\u0005]\u0006 שבכך — \u0003שכן הוקש\u0004 (הושווה) \u0003כבודן\u0004 של אביו ואמו \u0003לכבוד המקום!\u0004","ודוחים, יש להסביר: \u0003מדאפקיה רחמנא\u0004 \u0005[ממה שהוציאה התורה\u0006\u0005]\u0006 את \u0003ארוסה בת ישראל מכלל נשואה בת ישראל,\u0004 שבת ישראל נשואה שזינתה דינה \u0003חנק,\u0004 והחמיר בארוסה לדונה ב\u0003סקילה\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003סקילה חמורה.\u0004","\u0003שריפה חמורה מסייף,\u0004 וראיה לדבר — \u0003שכן ניתנה לבת כהן שזינתה, ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 יש בה — \u0003שכן מחללת את אביה.\u0004","ומקשים: \u0003אדרבה,\u0004 נאמר ש\u0003סייף חמור שכן ניתן לאנשי עיר הנדחת, ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 בהם — \u0003שכן ממונן אבד!\u0004","ומשיבים: נלמד חומרת שריפה בגזירה שווה, \u0003נאמר \"אביה\" בסקילה\u0004 (\"וסקלוה אנשי עירה באבנים ומתה כי עשתה נבלה בישראל לזנות בית אביה\". דברים כב, כא). \u0003ונאמר \"אביה\" בשריפה, מה \"אביה\" האמור בסקילה\u0004 יודעים אנו ש\u0003סקילה חמורה מסייף, אף \"אביה\" האמור בשריפה\u0004 — \u0003שריפה חמורה מסייף.\u0004","\u0003שריפה חמורה מחנק,\u0004 וראיה לדבר — \u0003שכן ניתנה לבת כהן שזינתה. ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 שיש בה — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו\u0006\u0005]\u0006 שהיא מחללת את אביה.","ומקשים: \u0003אדרבה,\u0004 נאמר ש\u0003חנק חמור, שכן ניתן למכה אביו ואמו, ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 שבהם — \u0003שכן הוקש כבודן לכבוד המקום!\u0004","ומשיבים: \u0003מדאפקיה רחמנא\u0004 \u0005[ממה שהוציאה התורה\u0006\u0005]\u0006 \u0003לנשואה בת כהן מכלל נשואה בת ישראל\u0004 והחמירה בדינה \u0003מחנק\u0004 שהוא דין מיתת נשואה בת ישראל שזינתה \u0003לשריפה, שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003שריפה חמורה\u0004 מחנק.","\u0003סייף חמור מחנק שכן ניתן לאנשי עיר הנדחת, ומאי חומרא\u0004 \u0005[ומה החומרה\u0006\u0005]\u0006 בעבירותיהם — \u0003שכן ממונם אבד.\u0004","ומקשים: \u0003אדרבה,\u0004 נאמר ש\u0003חנק חמור שכן ניתן למכה אביו ואמו! ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 בעוון זה — \u0003שכן הוקש\u0004 כבודם לכבוד המקום!","ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך\u0006\u0005],\u0006 \u0003פושט ידו בעיקר עדיף\u0004 (חמור) לפי שהוא פוגע בכבוד המקום עצמו, וודאי עונשו הוא החמור שבעונשים.","שנינו במשנה ש\u0003ר' שמעון אומר\u0004 ש\u0003שריפה חמורה מסקילה.\u0004 וטעם שיטת ר' שמעון ששריפה חמורה — \u0003שכן ניתנה לבת כהן שזינתה. ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 בדבר — \u0003שכן\u0004 היא \u0003מחללת את אביה.\u0004","ומקשים: \u0003אדרבה,\u0004 נאמר ש\u0003סקילה חמורה שכן ניתנה למגדף ולעובד עבודה זרה. ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 שבהם — \u0003שכן פושט ידו בעיקר!\u0004","ומשיבים: \u0003ר' שמעון לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: אחת\u0004 בת כהן \u0003ארוסה ואחת נשואה\u0004 — \u0003יצאה\u0004 בזנותה \u0003לשריפה,\u0004 \u0003ומדאפקיה רחמנא\u0004 \u0005[ו\u0006לפיכך \u0005ממה שהוציאה התורה\u0006\u0005]\u0006 את \u0003ארוסה בת כהן מכלל ארוסה בת ישראל מסקילה לשריפה,\u0004 וודאי החמירה התורה בדינה של בת כהן מזה של בת ישראל, \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003שריפה חמורה\u0004 יותר מסקילה.","\u0003שריפה חמורה מחנק,\u0004 וראיה לדבר — \u0003שכן ניתנה לבת כהן שזינתה. ומאי\u0004 \u0003חומרא\u0004 \u0005[ומה חומרה\u0006\u0005]\u0006 יש בה — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 שהיא מחללת אף את כבוד אביה.","ומקשים: \u0003אדרבה\u0004 נאמר \u0003ש\u0004\u0003חנק חמור שכן ניתן למכה אביו ואמו, ומאי\u0004 \u0003חומרא\u0004 \u0005[ומה חומרה\u0006\u0005]\u0006 יש בענין זה — \u0003שכן הוקש כבודם לכבוד המקום!\u0004","ומשיבים כפי שהשבנו קודם: \u0003מדאפקיה רחמנא\u0004 \u0005[ממה שהוציאה התורה\u0006\u0005]\u0006 את ה\u0003נשואה בת כהן מכלל נשואה בת ישראל מ\u0004מיתת \u0003חנק לשריפה\u0004 — \u0003שמע מינה\u0004 \u0005[למד למכאן\u0006\u0005]\u0006 כי \u0003שריפה חמורה.\u0004","\u0003שריפה חמורה מסייף\u0004 וראיה לדבר — \u0003שכן ניתנה לבת כהן שזינתה\u0004 שהיא נידונת בשריפה. \u0003ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 יש בה — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו].\u0006","ומקשים: \u0003אדרבה,\u0004 נאמר \u0003ש\u0004\u0003סייף חמור שכן ניתן לאנשי עיר הנדחת. ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 שבהם — \u0003שכן ממונם אבד!\u0004","ודוחים: \u0003אמרת, וכי איזה כח מרובה\u0004 וחמור, \u0003כח המדיח או כח הנידח?\u0004"],["— \u0003הוי אומר כח המדיח. וקל וחומר\u0004 הוא זה: \u0003ומה חנק שחמור מסייף\u0004 — \u0003שריפה חמורה ממנו, סייף הקל\u0004 — \u0003לא כל שכן\u0004 ששריפה חמורה ממנו.","\u0003סקילה חמורה מחנק\u0004 וראיה לדבר — \u0003שכן ניתנה למגדף\u0004 (מקלל את ה') \u0003ולעובד עבודה זרה. ומאי חומרא\u0004 \u0005[ומה החומרה\u0006\u0005]\u0006 שבהם — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו\u0006\u0005].\u0006","ומקשים: \u0003אדרבה\u0004 נאמר \u0003ש\u0004\u0003חנק חמור, שכן ניתן למכה אביו ואמו. ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 בו — \u0003שכן הוקש\u0004 כבודם לכבוד המקום!","ומשיבים: \u0003מדאפקיה רחמנא\u0004 \u0005[ממה שהוציאה התורה\u0006\u0005]\u0006 \u0003לארוסה בת ישראל מכלל נשואה בת ישראל, מחנק לסקילה\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003סקילה חמורה.\u0004","\u0003סקילה חמורה מסייף,\u0004 וראיה לדבר — \u0003שכן ניתנה למגדף\u0004 ולעובד עבודה זרה. ואפשר להקשות: \u0003אדרבה\u0004 (להיפך), נאמר \u0003ש\u0004\u0003סייף חמור שכן ניתן לאנשי עיר הנדחת, ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 שבהם — \u0003שכן ממונם אבד.\u0004","\u0003אמרת: וכי איזה כח מרובה, כח המדיח או כח הנידח?\u0004 — \u0003הוי אומר כח המדיח, וקל וחומר\u0004 הוא זה: \u0003ומה חנק שחמור מסייף\u0004 לדעת ר' שמעון \u0003סקילה חמורה ממנו, סייף הקל לא כל שכן.\u0004","\u0003חנק חמור מסייף,\u0004 וראיה לדבר — \u0003שכן ניתן למכה אביו ואמו. ומאי חומרא\u0004 \u0005[ומה חומרה]\u0006 שבהם — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו\u0006\u0005].\u0006","ומקשים: \u0003אדרבה,\u0004 נאמר \u0003ש\u0004\u0003סייף חמור שכן ניתן לאנשי עיר הנדחת, ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 שבהם — \u0003שכן ממונם אבד!\u0004","\u0003אמרת: וכי איזה כח מרובה, כח המדיח או כח הנידח? הוי אומר: כח המדיח, ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 \u0003מדיחי עיר הנדחת\u0004 נידונים \u0003בסקילה, ר' שמעון אומר: בחנק,\u0004 הרי שחנק חמור מסייף.","\u0003מרגלא בפומיה\u0004 \u0005[רגיל היה בפיו\u0006\u0005]\u0006 של \u0003ר' יוחנן\u0004 כלל זה שקיבל מרבותיו: \u0003נערה המאורסה בת כהן שזינתה\u0004 — דינה \u0003בסקילה, ר' שמעון אומר:\u0004 דינה \u0003בשריפה.\u0004 אם \u0003זינתה\u0004 נערה מאורסה בת ישראל \u0003מאביה\u0004 — דינה \u0003בסקילה, ר' שמעון אומר: בשריפה.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006\u0005]\u0006 בכך? ומשיבים: \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים\u0006\u0005]\u0006 בא ללמדנו ש\u0003נשואה\u0004 בת כהן \u0003יצאה לשריפה, ולא ארוסה,\u0004 אלא דינה בסקילה. \u0003ל\u0004שיטת \u0003ר' שמעון\u0004 בא ללמדנו ש\u0003אחת ארוסה ואחת נשואה יצאה לשריפה. וטעמא מאי\u0004 \u0005[מה טעם]\u0006 קבעו כך — \u0003משום דלרבנן\u0004 \u0005[של\u0006 שיטת \u0005חכמים\u0006\u0005]\u0006 \u0003סקילה חמורה\u0004 משריפה, וכיון שכל ארוסה דינה בסקילה אין מקילים על בת כהן לדונה בשריפה. ו\u0003ל\u0004דעת \u0003ר' שמעון שריפה חמורה\u0004 מסקילה,","וכל אותה מחלוקת מה היא המיתה החמורה יותר \u0003נפקא מינה\u0004 \u0005[יוצא מכאן\u0006\u0005]\u0006 הבדל למעשה \u0003למי שנתחייב שתי מיתות בית דין\u0004 על שתי עבירות שעשה, ש\u0003נידון בחמורה\u0004 יותר.","בדיונים הקודמים הזכרנו שלדעת ר' שמעון בת כהן שזנתה דינה בשריפה, בין ארוסה, בין נשואה. ושואלים: \u0003מאי\u0004 \u0005[מהו\u0006\u0005]\u0006 המקור בו נזכרה שיטת \u0003ר' שמעון\u0004 בענין זה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: שני כללות\u0004 (שני דינים כוללים) \u0003נאמרו בבת כהן,\u0004 דין אחד בארוסה, ודין אחר בנשואה.","ותוהים: \u0003בבת כהן ולא בבת ישראל?!\u0004 וכי בה לא נאמרו שני דינים אלה? אלא \u0003אימא\u0004 \u0005[אמור\u0006\u0005]:\u0006 \u0003אף בבת כהן\u0004 שייכים שני כללות אלה, וארוסה שזנתה — בסקילה, ונשואה שזנתה — בחנק.","\u0003והוציא הכתוב נשואה\u0004 בת כהן \u0003מכלל נשואה\u0004 בת ישראל, \u0003וארוסה\u0004 בת כהן \u0003מכלל ארוסה\u0004 בת ישראל, שדברי הכתוב \"ובת איש כהן כי תחל לזנות\" לשני המקרים הם מתייחסים ובין שהיא ארוסה, או שהיא נשואה, דינה בשריפה.","ומכאן הוא למד: \u0003מה כשהוציא הכתוב נשואה\u0004 בת כהן \u0003מכלל נשואה\u0004 בת ישראל הרי זה \u0003להחמיר\u0004 בדינה, \u0003אף כשהוציא הכתוב ארוסה\u0004 בת כהן \u0003מכלל ארוסה\u0004 בת ישראל הרי זה \u0003להחמיר\u0004 בדינה, משמע שמיתת שריפה חמורה ממיתת סקילה.","\u0003זוממי נשואה בת כהן,\u0004 אותם עדים שזממו והעידו עליה עדות שקר שזנתה, הריהם \u0003בכלל זוממי נשואה בת ישראל, וזוממי ארוסה בת כהן בכלל זוממי ארוסה בת ישראל\u0004 ובהם לא החמיר הכתוב, וזוממי נשואה כלשהי — בחנק, וזוממי ארוסה — בסקילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005],\u0006 נאמר: \u0003\"ובת איש כהן כי תחל\u0004 לזנות את אביה היא מחללת באש תישרף\u0003\"\u0004 (ויקרא כא, ט). \"כי תחל\" \u0003יכול\u0004 משמעו \u0003אפילו חללה את השבת\u0004 יהא דינה כן — \u0003תלמוד לומר \"לזנות\"\u0004 — \u0003בחילולין שבזנות הכתוב מדבר.\u0004","\u0003יכול אפילו פנויה\u0004 שזנתה יהא דינה בשריפה — \u0003נאמר כאן \"אביה\" ונאמר להלן \"אביה\", מה להלן\u0004 מדובר ב\u0003זנות עם זיקת הבעל,\u0004 שהרי מוזכר שם באשה שהואשמה על ידי בעלה הזנות, \u0003אף כאן\u0004 מדובר ב\u0003זנות עם זיקת הבעל.\u0004","\u0003או\u0004 שמא תרצה לומר כי הכתוב \u0003אינו אומר \"אביה\" אלא להוציא את כל האדם\u0004 ורק אם זנתה עם אביה נדונה בשריפה? אך \u0003כשהוא אומר \"היא מחללת\"\u0004 משמע שהיא שחיללה, ולא אביה הוא שחילל, \u0003הוי כל אדם אמור\u0004 בכלל עבירה זו,","\u0003הא\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003מה אני מקיים\u0004 \"את \u0003אביה\u0004 היא מחללת\", כלומר, מה באה תוספת זו לומר — ללמד בגזירה שווה: \u0003נאמר כאן \"אביה\" ונאמר להלן \"אביה\", מה להלן זנות עם זיקת הבעל\u0004 — \u0003אף כאן זנות עם זיקת הבעל.\u0004","ומקשים: \u0003אי\u0004 \u0005[או]\u0006 \u0003מה להלן\u0004 מדובר על \u0003נערה\u0004 דווקא, שתקופת הנערות היא חצי שנה מהבאת סימני בגרות ראשונים ולאחר מכן קרויה כבר בוגרת, \u0003והיא ארוסה,\u0004 אם כן אפשר לומר ש\u0003אף כאן\u0004 מדובר רק ב\u0003נערה והיא ארוסה.\u0004 אבל \u0003נערה והיא נשואה,\u0004 או \u0003בוגרת והיא ארוסה,\u0004 או \u0003בוגרת והיא נשואה,\u0004 או \u0003אפילו הזקינה\u0004 ואינה קרויה סתם \"בת\", \u0003מנין\u0004 שאין מחלקים בדינה?","— \u0003תלמוד לומר \"ובת כהן\"\u0004 — \u0003מכל מקום,\u0004 שכל אשה שהיא בת כהן, חל עליה דין זה ללא הבדל.","\u0003\"בת כהן\"\u0004"],["\u0003אין לי אלא שניסת\u0004 (נישאת) \u0003לכהן,\u0004 אך אם \u0003ניסת ללוי,\u0004 או \u0003לישראל,\u0004 או \u0003לכותי,\u0004 או \u0003לחלל,\u0004 או \u0003לממזר,\u0004 או \u0003לנתין, מניין\u0004 שכל דינים אלה חלים עליה? \u0003תלמוד לומר \"ובת איש כהן\",\u0004 ללמד \u0003אף על פי שאינה כהנת\u0004 עתה לאחר שנשאה, \"באש תשרף\" —","\u0003היא בשריפה,\u0004 אבל \u0003אין בועלה\u0004 נידון \u0003בשריפה,\u0004 אלא נידון כבועל ארוסה או נשואה. \u0003היא בשריפה, ואין זוממיה\u0004 שנמצאו אשמים נידונים \u0003בשריפה.\u0004","\u0003ר' אליעזר אומר: את אביה בשריפה, ואת חמיה בסקילה,\u0004 כאשר יבואר.","לאחר שהובאה ברייתא זו, מבארים אותה ודנים בה. \u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 בברייתא: \u0003יכול אפילו חיללה שבת\u0004 תהא נידונה בשריפה. ותוהים: הלא אם \u0003חיללה שבת בת סקילה היא,\u0004 ומדוע יעלה על הדעת לומר שתידון בת הכהן בשריפה שהיא מיתה קלה יותר?","\u0003אמר רבא: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא\u0006\u0005]\u0006 — כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר שריפה חמורה\u0004 מסקילה. \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הואיל ואחמיר בהו רחמנא בכהני, דרבי בהו\u0004 \u0005[והחמירה התורה בכהנים, שריבתה בהם]\u0006 \u0003מצות יתירות,\u0004 שמא \u0003תידון בשריפה\u0004 שהיא לדעת ר' שמעון חמורה יותר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין ההלכה כן, ולענין חילול שבת דינה כשאר בנות ישראל.","ושואלים: \u0003מאי שנא מיניה דידיה\u0004 \u0005[במה שונה\u0006 הדבר \u0005ממנו,\u0006 מכהן \u0005עצמו\u0006\u0005]\u0006 שכהן שחילל שבת נידון בסקילה, וכיצד אפשר כלל לשער שבתו תחוייב בשריפה?","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר\u0006\u0005]\u0006 ולחלק בין כהן לבת כהן באופן זה: \u0003איהו דאישתריא ליה\u0004 \u0005[הוא,\u0006 הכהן \u0005שהותרה לו]\u0006 \u0003שבת לגבי עבודה\u0004 במקדש, שהרי כהן מותר לו לעשות דברים שיש בהם חילול שבת בתוך העבודה בבית המקדש — על כן אפשר היה לחשוב שאין עונשו חמור יותר מישראל אם חילל שבת באיסור. אבל \u0003היא, כיון\u0004 ש\u0003לא אשתריא\u0004 \u0005[הותרה]\u0006 \u0003שבת לגבה\u0004 כלל, שכן אינה עובדת במקדש, \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 ש\u0003תידון בשריפה\u0004 להחמיר עליה בשל החובות המיוחדות שהוטלו על הכהנים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן.","שנינו בברייתא: \u0003יכול אפילו פנויה\u0004 שזנתה יהא דינה בשריפה. ומקשים: כיצד עולה על הדעת כלל שאף בפנויה מדובר: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"לזנות\" כתיב\u0004 \u0005[נאמר\u0006\u0005],\u0006 ואין זונה אלא זו שנבעלת בעבירה גמורה, מה שאין כן בפנויה!","ומשיבים: דבר זה הוא \u0003כ\u0004שיטת \u0003ר' אלעזר\u0004 ש\u0003אמר: פנוי הבא על הפנויה שלא לשום אישות\u0004 (לשם נישואין) — \u0003עשאה\u0004 על ידי כך \u0003זונה.\u0004 שלדעתו זנות איננה בעילה שיש בה עבירה חמורה בלבד, אלא כל ביאה שאינה לשם אישות הרי היא זנות.","עוד שנינו בברייתא: \u0003או אינו אומר \"אביה\" אלא להוציא את כל אדם.\u0004 ומבררים מה היתה האפשרות האחרת שהיתה בברייתא לומר: \u0003אלא מאי ניהו\u0004 \u0005[מה הוא\u0006 הענין\u0005]\u0006 — שאפשר לפרש שמלת \"אביה\" באה לומר שמדובר \u0003שזינתה\u0004 אותה בת \u0003מאביה.\u0004 ואולם אם אמנם כן, \u0003מאי איריא\u0004 \u0005[מה שייך\u0006\u0005]\u0006 יחוד דין זה ל\u0003בת כהן? אפילו בת ישראל נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 תידון במקרה כזה בשריפה.","ש\u0003אמר רבא, אמר לי רב יצחק בר אבודימי: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה מהמילים \u0003\"הנה\" \"הנה\"\u0004 שנאמרו בבת בנו ובבת אשתו,","ו\u0003אתיא\u0004 \u0005[בא\u0006 הדבר\u0005]\u0006 בגזירה שווה \u0003\"זמה\" \"זמה\"\u0004 האמורות בעונשים שבשני המקרים, ללמד שכל הבא על בתו נידון לשריפה!","ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך\u0006 הדבר\u0005]\u0006 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי בא \u0003קרא\u0004 \u0005[הכתוב]\u0006 \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רבא\u0004 ולסתור ראיה שהביא, באופן זה: \u0003מדגלי רחמנא\u0004 \u0005[ממה שגילתה התורה]\u0006 \u0003בבת כהן ולא בבת ישראל\u0004 עונש זה, הרי שאינו קיים בבת ישראל, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאי אפשר לומר כאן שמדובר בבת שזינתה מאביה, שכן נאמר \"היא מחללת\" ואין לאביה ענין לדין זה.","עוד שנינו בברייתא: \u0003\"בת כהן\", אין לי אלא שניסת\u0004 (נישאת) \u0003לכהן,\u0004 ואולם אם \u0003ניסת ללוי,\u0004 או \u0003לישראל,\u0004 או \u0003לכותי,\u0004 או \u0003לחלל,\u0004 או \u0003לנתין,\u0004 או \u0003לממזר מניין\u0004 שדינה כמו כן? — \u0003תלמוד לומר: \"בת איש כהן\", אף על פי שאינה כהנת.\u0004","ותוהים: וכי \u0003משום דאינסבא להו להני\u0004 \u0005[שנישאה להם, לאלה]\u0006 שאינם כהנים, האם שוב \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בת כהן היא?!\u0004 ומה הסברא שבמקרים אלה יהא דינה שונה? והרי מובן שהיא נשארת לעולם בת כהן. \u0003ותו\u0004 \u0005[ועוד\u0006\u0005]\u0006 יש להקשות: \u0003מידי\u0004 \u0005[וכי\u0006\u0005]\u0006 \u0003\"כהנת לכהן\" כתיב\u0004 \u0005[נאמר\u0006\u0005]?\u0006 — והלא נאמר רק \"בת כהן\" ולא דובר כלל בבעלה!","ועונים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר\u0006\u0005]\u0006 כי \u0003\"כי תחל לזנות\" אמר רחמנא\u0004 \u0005[אמרה התורה\u0006\u0005],\u0006 ו\u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דקא מתחלא השתא\u0004 \u0005[כשהיא מתחללת עכשיו\u0006 בזנותה\u0005],\u0006 \u0003אבל הא\u0004 \u0005[זו\u0006\u0005]\u0006 שהתחתנה עם אחד מאלה \u0003כיון דקא מתחלא וקיימא מעיקרא\u0004 \u0005[שהיא מחוללת ועומדת מתחילתה,\u0006 משעת נשואיה\u0005]\u0006","שהרי \u0003אמר מר\u0004 \u0005[החכם\u0006\u0005]\u0006 על הכתוב \u0003\"ובת כהן כי תהיה לאיש זר\u0004 היא בתרומת הקדשים לא תאכל\u0003\"\u0004 (ויקרא כב, יב) \u0003כיון שנבעלה לפסול לה,\u0004 למי שאסורה להינשא לו (\"זר\") — \u0003פסלה.\u0004","ואף \u0003ללוי וישראל נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 יש בכך פסול, שנאמר בה, \u0003\"ושבה אל בית אביה כנעוריה\u0004 מלחם אביה תאכל\u0003\"\u0004 (ויקרא כב, יג), \u0003מכלל\u0004 הדברים נבין \u0003דכי איתיה גביה לא אכלה\u0004 \u0005[שכאשר מצויה\u0006 היא \u0005אצלו,\u0006 אצל בעלה, \u0005אינה אוכלת\u0006\u0005]\u0006 הרי שנישואי בת כהן לכל מי שאינו כהן יש בהם מקצת חילול, ולכאורה","\u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 ש\u0003לא תידון בשריפה\u0004 אם זנתה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 שדין זה שייך בה משום היותה בת כהן ולא מפני נישואיה.","ומעירים: \u0003ו\u0004משנה זו היא ש\u0003לא כ\u0004שיטת \u0003ר' מאיר. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בת כהן שניסת לישראל ואכלה תרומה\u0004 בשוגג \u0003משלמת את הקרן,\u0004 שכן אכלה תרומה שאין לה זכות בה, \u0003ואינה משלמת את החומש\u0004 של קנס כשאר אדם מישראל האוכל תרומה בשוגג, משום שלא נפסלה לגמרי מתורת כהונה, שהרי אם תתאלמן או תתגרש בלא ילדים תהא שוב מותרת בתרומה, \u0003ומיתתה בשריפה\u0004 אם זנתה.","אבל אם \u0003ניסת לאחד מן הפסולין\u0004 כגון חלל או ממזר או נתין, אם אכלה תרומה — \u0003משלמת קרן וחומש,\u0004 שלאחר שנבעלה לפסול נפסלה על ידי כך לעולם, \u0003ומיתתה בחנק,\u0004 כשאר בנות ישראל משום שהיא כבר מחוללת כליל מן הכהונה, אלה \u0003דברי ר' מאיר,\u0004","\u0003וחכמים אומרים זו וזו משלמות קרן ולא חומש,\u0004 שאינן זרות לגמרי, \u0003ומיתתן\u0004 של שתיהן \u0003בשריפה\u0004 כברייתא שלנו.","עוד שנינו באותה ברייתא, ש\u0003ר' אליעזר אומר: את אביה בשריפה ואת חמיה בסקילה,\u0004 ודנים בביאור משפט סתום זה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"את אביה ואת חמיה\"?\u0004","\u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 \u0003\"את אביה\",\u0004 פירושו של דבר — שזינתה \u0003מאביה, ו\"את חמיה\"\u0004 — שזינתה \u0003מחמיה, מאי איריא\u0004 \u0005[מה שייך\u0006 דין זה דווקא\u0005]\u0006 ב\u0003בת כהן, אפילו\u0004 ב\u0003בת ישראל נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 דינה כך הוא, שכן הבא על \u0003בתו\u0004 — \u0003בשריפה,\u0004 ובא על \u0003כלתו\u0004 — \u0003בסקילה!\u0004","\u0003אלא\u0004 יש לפרש: \u0003\"את אביה\"\u0004 — שהיתה עדיין \u0003ברשות אביה,\u0004 לאמור — בעודה ארוסה, \u0003ו\"את חמיה\"\u0004 — כשהיא \u0003ברשות חמיה,\u0004 כלומר, שהיא כבר נשואה.","ונברר \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 היא \u0005]\u0006 הלכה זו, \u0003אי כרבנן\u0004 \u0005[אם כ\u0006שיטת \u0005חכמים\u0006\u0005]\u0006 — \u0003האמרי\u0004 \u0005[הרי אומרים\u0006 הם\u0005]\u0006 כי רק בת כהן \u0003נשואה יצאת\u0004 (יוצאת, נידונה) \u0003לשריפה, ולא ארוסה. אי\u0004 \u0005[אם\u0006 תאמר\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 — \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 כי \u0003אחת\u0004 בת כהן \u0003ארוסה ואחת נשואה\u0004 אם זנו נידונות הן \u0003בשריפה,\u0004 ושיטה זו שלא כאחד מהם.","\u0003ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' ישמעאל\u0004 — \u0003האמר\u0004 \u0005[הרי אמר\u0006\u0005]\u0006 כי רק בת כהן \u0003ארוסה יצאת לשריפה ולא נשואה,\u0004 ו\u0003את חמיה,\u0004 אם בבית חמיה זינתה — ב\u0003חנק הוא\u0004 נידונה, כשאר אשת איש שזינתה.","\u0003שלח רבין משמיה\u0004 \u0005[משמו\u0006\u0005]\u0006 של \u0003ר' יוסי בר' חנינא: כך היא הצעה\u0004 (סדרה ודרכה) \u0003של משנה\u0004 זו: \u0003לעולם\u0004 תפרש כשיטת \u0003רבנן\u0004 \u0005[חכמים\u0006\u0005]\u0006 \u0003והכי קאמר\u0004 \u0005[וכך אמר\u0006 שונה המשנה\u0005]:\u0006 \u0003כל שהוא למטה ממיתת אביה,\u0004 כלומר, כל מיתה הקלה מן המיתה שנענשת היא על זנות מאביה שהיא שריפה, \u0003ומאי ניהו\u0004 \u0005[ומה הוא\u0006\u0005]\u0006 — דין \u0003נשואה בת ישראל,\u0004 ש\u0003אילו נשואה בת ישראל\u0004 נידונה \u0003בחנק,\u0004 הרי \u0003הכא\u0004 \u0005[כאן\u0006\u0005],\u0006 בבת כהן — היא נידונה \u0003במיתת אביה, בשריפה.\u0004","\u0003כל שהיא למעלה ממיתת אביה,\u0004 שענשה חמור מזה שנענשת אם זנתה מאביה, \u0003ומאי ניהו\u0004 \u0005[ומה הוא\u0006\u0005]\u0006 דין \u0003ארוסה בת ישראל.\u0004 ש\u0003אילו ארוסה בת ישראל בעלמא\u0004 \u0005[בכלל\u0006\u0005]\u0006 נידונה \u0003בסקילה, הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 בבת כהן — נידונה גם היא \u0003במיתת חמיה\u0004 כאילו היתה מזנה עם חמיה ו\u0003בסקילה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה\u0006\u0005],\u0006 על הסברה זו, \u0003ר' ירמיה: מידי\u0004 \u0005[וכי\u0006\u0005]\u0006 \u0003\"למעלה\" \"למטה\" קתני\u0004 \u0005[שנינו\u0006\u0005]?\u0006 ומלה זו שהיא עיקרית בפירוש זה הרי לא נאמרה כלל! \u0003אלא\u0004 יש לדחות את דברי רבין, ו\u0003אמר ר' ירמיה:\u0004"],["\u0003לעולם\u0004 דברי ר' אליעזר \u0003כר' ישמעאל,\u0004 וארוסה היא הנשרפת ולא נשואה. \u0003והכי קאמר\u0004 \u0005[וכך אמר\u0006\u0005],\u0006 כך יש להבין: \u0003\"את אביה\",\u0004 כלומר, זו שהיתה עדיין \u0003ברשות אביה\u0004 והיא הארוסה — \u0003בשריפה, ואת חמיה,\u0004 כלומר, שזנתה \u0003מחמיה\u0004 — הריהי נידונה \u0003בסקילה\u0004, ואם זנתה מ\u0003כל אדם\u0004 אחר — נידונה \u0003בחנק,\u0004 כשאר כל נשים הנשואות.","\u0003אמר רבא\u0004 יש להקשות: \u0003מאי שנא\u0004 \u0005[במה שונה\u0006\u0005]\u0006 חלק אחד של אותה משנה מחלק אחר? \u0003או\u0004 שתפרש כי \u0003אידי ואידי\u0004 \u0005[זה וזה\u0006\u0005]\u0006 \u0003ממש,\u0004 ותאמר \"את אביה\" — פירושו עם אביה ממש, \u0003או אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר שהיתה ב\u0003רשות\u0004 האב או החותן!","\u0003אלא\u0004 יש לדחות פירוש זה, ו\u0003אמר רבא: לעולם\u0004 נפרש \u0003כר' שמעון, וקסבר ר' אליעזר\u0004 ש\u0003נשואה\u0004 בת כהן דינה \u0003כארוסה, מה ארוסה חד דרגא מסקינן\u0004 \u0005[דרגה אחת מעלים,\u0006 מחמירים \u0005אנו]\u0006 בה, \u0003מ\u0004דין \u0003סקילה\u0004 (של בת ישראל) \u0003לשריפה, אף נשואה\u0004 בת כהן \u0003חד דרגא מסקינן לה\u0004 \u0005[דרגה אחת מעלים אנו אותה\u0006\u0005],\u0006 \u0003מחנק\u0004 — \u0003לסקילה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה\u0006\u0005]\u0006 \u0003ר' חנינא: הא אידי ואידי\u0004 \u0005[הלא בזו וזו\u0006\u0005]\u0006 \u0003ר' שמעון\u0004 עצמו \u0003בשריפה קאמר\u0004 \u0005[אמר\u0006\u0005],\u0006 ואין אתה יכול לפרש שיטתו שלא כדבריו.","\u0003אלא אמר רבינא: לעולם\u0004 תפרש \u0003כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 שנשואה בשריפה וארוסה בסקילה, \u0003ואיפוך\u0004 \u0005[הפוך]\u0006 את הגרסה בדברי ר' אליעזר כך: \u0003את אביה בסקילה, ואת חמיה בשריפה. והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003\"את אביה\"\u0004 — \u0003סירכא בעלמא נקט\u0004 \u0005[המשך\u0006 דברים \u0005בלבד לקח\u0006\u0005]\u0006 נקט את נוסח המקרא ולא אמר במפורש \"נשואה\" ו\"ארוסה\". שכן הברייתא גרסה את מטבעות הלשון שבמקרא, ואין הכוונה שזנתה עם אביה אלא בהיותה ברשות אביה, כלומר, ארוסה.","\u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: הלכה\u0004 בענין זה \u0003כ\u0004פי ש\u0003שלח רבין משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוסי בר' חנינא. אמר רב יוסף\u0004 בתמיהה: \u0003הלכתא למשיחא\u0004 \u0005[הלכה ל\u0006ימות \u0005המשיח\u0006\u0005]?!\u0006 הלא בזמן הזה אין מיתות בית דין נוהגות, ומה טעם לקבוע הלכה לדבר שאינו מתממש אלא לימות המשיח!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 שאין לנו לעסוק בהלכות בדברים שאינן קיימות לזמננו, \u0003שחיטת קדשים\u0004 (מסכת זבחים) \u0003לא ליתני\u0004 \u0005[נלמד\u0006\u0005],\u0006 שהרי כולה \u0003הלכתא למשיחא\u0004 \u0005[הלכה ל\u0006ימות \u0005המשיח]!\u0006 \u0003אלא\u0004 נקוט בידך אף דברים שאינם הלכה למעשה ו\u0003דרוש וקבל שכר\u0004 על הלימוד עצמו. \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 \u0003דרוש וקבל שכר.\u0004","אמר לו רב יוסף: \u0003הכי קאמרי\u0004 \u0005[כך אמרתי,\u0006 זו היתה כוונתי\u0005],\u0006 קביעת \u0003הלכתא\u0004 \u0005[הלכה]\u0006 בענין זה \u0003למה לי?\u0004 \u0003סוגיא דשמעתא\u0004 \u0005[את מהלך הסוגיה]\u0006 \u0003הלכה קאמר\u0004 \u0005[אמר\u0006], שהרי דברים שמסרו אינם אלא פירושם של דברי התנאים ואין משמעות לקביעת הלכה בהם.","בתוך הדברים הקודמים, הזכרנו את שיטת ר' ישמעאל בדין זה, ושואלים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 המקור בו אמר \u0003ר' ישמעאל\u0004 את דבריו אלה? ומשיבים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר \u0003\"ובת איש כהן כי תחל לזנות\"\u0004 (ויקרא כא, ט) — \u0003בנערה והיא ארוסה הכתוב מדבר.\u0004","\u0003אתה אומר\u0004 אינו אלא \u0003בנערה והיא ארוסה, או אינו אלא אפילו\u0004 אשה \u0003נשואה?\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003איש אשר ינאף\u0004 את אשת איש אשר ינאף \u0003את אשת רעהו מות יומת הנאף והנאפת\"\u0004 (ויקרא כא, כ, י), \u0003הכל\u0004 (כל אשת איש) \u0003היו בכלל \"הנואף והנואפת\", הוציא הכתוב\u0004 מכללם \u0003בת ישראל\u0004 שנידונה \u0003בסקילה ובת כהן\u0004 שנידונה \u0003בשריפה,\u0004 ונלמד: \u0003מה כשהוציא הכתוב את בת ישראל לסקילה\u0004 מפרש הכתוב שהיא \u0003ארוסה ולא נשואה, אף כשהוציא הכתוב בת כהן לשריפה\u0004 — \u0003ארוסה ולא נשואה.\u0004","עוד שנינו בברייתא ש\u0003זוממיה ובועלה בכלל \"ועשיתם לו כאשר זמם\u0004 לעשות לאחיו\u0003\"\u0004 (דברים יט, יט).","את מהלך הדברים בברייתא מפסיקים בתלמוד בתמיהה עניינית: \u0003בועלה מאי\u0004 \u0005[מה\u0006 מקום\u0005]\u0006 ל\u0003\"כאשר זמם\" איכא\u0004 \u0005[יש כאן\u0006\u0005]\u0006 הלא הוא בוודאי אינו נידון בשריפה. \u0003אלא\u0004 כך יש לגרוס: \u0003זוממיה\u0004 נכנסים \u0003בכלל מיתת בועלה,\u0004 ואינם נכללים במיתה שלה.","\u0003משום שנאמר \"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט) ונדייק: לאחיו דווקא \u0003ולא לאחותו,\u0004 אלו \u0003דברי ר' ישמעאל,\u0004 שבמקרה זה שיש מקום לדונם במיתה זו או בזו הולכים להקל ודורשים \"לאחיו\" דווקא.","\u0003ר' עקיבא אומר: אחת ארוסה ואחת נשואה יצאת\u0004 (יוצאת, נידונה) \u0003לשריפה. יכול אפילו פנויה\u0004 שזנתה תישרף — \u0003נאמר כאן\u0004 בענין בת כהן \u0003\"אביה\", ונאמר להלן\u0004 בענין מוציא שם רע על אשתו \u0003\"אביה\", מה להלן\u0004 במוציא שם רע \u0003זנות עם זיקת\u0004 (קשר) \u0003הבעל\u0004 שהרי באשת איש מדובר, \u0003אף כאן זנות עם זיקת הבעל.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ישמעאל: אי מה להלן\u0004 מדובר ב\u0003נערה והיא ארוסה, אף כאן\u0004 מדובר ב\u0003נערה והיא ארוסה,\u0004 ואם כן הרי זו דווקא ראיה לשיטת ר' ישמעאל שטוען כי בת כהן ארוסה שזינתה דינה בשריפה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' עקיבא: ישמעאל אחי \"בת\" \"ובת\" אני דורש,\u0004 שאני לומד מן הוא\"ו היתירה שבמלה \"ובת איש כהן\", לרבות גם נשואה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ישמעאל: \u0003וכי מפני שאתה דורש \"בת\" \"ובת\" נוציא\u0004 את \u0003זו לשריפה?\u0004 הרי דרשתך זו אינה עקבית כלל \u0003אם משמע\u0004 וא\"ו זה לרבות \u0003להביא את הנשואה\u0004 — \u0003הביא\u0004 גם \u0003את הפנויה, ואם משמע\u0004 הדברים לשיטתך \u0003להוציא את הפנויה\u0004 — \u0003הוציא\u0004 גם \u0003את הנשואה.\u0004","ושואלים: \u0003ור' עקיבא,\u0004 כיצד מסביר הוא? ומשיבים: לשיטתו, \u0003אהני\u0004 \u0005[הועילה]\u0006 \u0003גזירה שוה למעוטי\u0004 \u0005[למעט]\u0006 מעונש את ה\u0003פנויה,\u0004 \u0003ואהני\u0004 \u0005[והועיל]\u0006 הריבוי של \u0003\"בת\" \"ובת\"\u0004 \u0003לרבות את הנשואה.\u0004","ומסבירים: \u0003ור' ישמעאל סבר\u0004 \u0005[סבור]\u0006 כי \u0003מדקאמר ליה\u0004 \u0005[ממה שאמר לו\u0006\u0005]\u0006 \u0003\"בת\" \"ובת\" שמע מינה\u0004 \u0005[למד מכאן\u0006\u0005]\u0006 כי \u0003הדר ביה\u0004 \u0005[חזר בו\u0006\u0005]\u0006 \u0003מגזירה שוה\u0004 זו בכלל, וסבר שר' עקיבא מוכיח עכשיו רק מן הריבוי של \"בת\" \"ובת\" ולכן הקשה עליו מה שהקשה. אבל באמת ר' עקיבא מצרף ריבוי זה לגזירה שווה שעשה תחילה.","ושואלים: \u0003ור' ישמעאל, האי\u0004 \u0005[\u0006ריבוי \u0005זה\u0006\u0005]\u0006 של \u0003\"בת\" \"ובת\" מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו\u0006\u0005]?\u0006 ומסבירים: \u0003מיבעי ליה לכדתני אבוהי\u0004 \u0005[נחוץ\u0006 הוא \u0005לו ל\u0006אותו ענין \u0005ששנה אביו]\u0006 של \u0003שמואל בר אבין.\u0004 וכך שנינו: \u0003לפי שמצינו שחלק הכתוב בזכרים בין\u0004 כהנים \u0003תמימים\u0004 (שלמים בגופם) \u0003לבעלי מומין\u0004 לענין העבודה בבית המקדש, \u0003יכול נחלוק בבנותיהן\u0004 ונאמר שבת כהן בעל מום לא תידון בחומרה יתירה — על כן \u0003תלמוד לומר: \"בת\" \"ובת\"\u0004 —","לרבות בת של כהן בעל מום. ושואלים: \u0003ור' עקיבא,\u0004 מנין למד הוא דבר זה? ומשיבים: מן הכתוב \u0003\"\u0004קדושים יהיו לאלהיהם ולא יחללו שם אלהיהם כי את אשי ה' לחם אלהיהם \u0003הם מקריבם והיו קדש\"\u0004 (ויקרא כא, ו) \u0003נפקא\u0004 \u0005[יוצא\u0006\u0005]\u0006 דבר זה, ש\"והיו קדש\" בא ללמד שכל הכהנים אף שאינם מקריבים מכל מקום קודש הם.","ושואלים: \u0003ור' ישמעאל\u0004 מה אומר הוא כנגד ראיה זו? ועונים על כך: \u0003אי מההיא\u0004 \u0005[אם מאותו\u0006 פסוק\u0005]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי אינהו\u0004 \u0005[דברים אלה\u0006 אמורים \u0005בהם\u0006\u0005],\u0006 שלהם עצמם יש קדושה גם במומם כשאר כהנים \u0003אבל בנותיהן לא,\u0004 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו\u0006\u0005]\u0006 מריבוי \"ובת\" שדין בנותיהם של כהנים אלה כשל בנות שאר הכהנים.","ושואלים: \u0003ור' ישמעאל\u0004"],["\u0003האי\u0004 \u0005[\u0006פסוק \u0005זה\u0006\u0005]\u0006 \u0003\"\u0004את \u0003אביה היא מחללת\"\u0004 (ויקרא כא, ט) \u0003מאי דריש ביה\u0004 \u0005[מה לומד\u0006 הוא \u0005ממנו\u0006\u0005]\u0006 אם אינו נזקק למלה \"אביה\" לגזירה שווה, כר' עקיבא?","ומשיבים: \u0003מבעי ליה לכדתניא\u0004 \u0005[נחוץ\u0006 הוא \u0005לו לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: מה תלמוד לומר\u0004 ומה בא ללמדנו \u0003\"את אביה היא מחללת\"\u0004 — ללמד \u0003שאם היו נוהגין בו\u0004 תחילה מנהג \u0003קודש, נוהגין בו\u0004 מעכשיו מנהג \u0003חול.\u0004 היו נוהגים בו \u0003כבוד,\u0004 מעתה \u0003נוהגין בו בזיון, אומרין: \"ארור שזו,\u0004 בת כזו, \u0003ילד, ארור שזו גידל, ארור שיצא זו מחלציו\".\u0004","\u0003אמר רב אשי: כמאן קרינן\u0004 \u0005[לפי\u0006 שיטת \u0005מי\u0006 \u0005קוראים אנו]\u0006 \u0003\"רשיעא בר רשיעא\"\u0004 \u0005[רשע בן רשע\u0006\u0005]\u0006 \u0003ואפילו לרשיעא בר צדיקא\u0004 \u0005[לרשע בן צדיק],\u0006 \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003כהאי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה\u0006\u0005],\u0006 ר' מאיר, האומר שהבת שחטאה מחללת את אביה, ונוהגים גם בו מנהג בזיון.","שנינו במשנה: \u0003זו מצות הנסקלין.\u0004 ותוהים: \u0003מאי תנא דקתני\u0004 \u0005[מה שנה\u0006 תחילה, \u0005ששנה]\u0006 עכשיו: \u0003\"זו מצות הנסקלין\"?\u0004 כלומר, מה מקום למשפט זה הנראה כסיכום, והרי במשנתנו זו לא פורט דין הסקילה?","ומשיבים: \u0003משום דתנא\u0004 \u0005[ששנה]\u0006 במשנה הקודמת \u0003\"נגמר הדין מוציאין אותו לסקלו\",\u0004 וכן \u0003\"בית הסקילה היה גבוה שתי קומות\", ואיידי דקא בעי למיתנא\u0004 \u0005[ומתוך שבא לשנות\u0006 במשנה \u0005]\u0006 הקרובה \u0003\"מצות הנשרפין\", תנא נמי\u0004 \u0005[שנה גם כן\u0006\u0005]\u0006 \u0003\"זו מצות הנסקלין\"\u0004 כדי לסכם את מה ששנינו עד כה.","\u0003מצות הנשרפין\u0004 כיצד היו עושים? — \u0003היו משקעין אותו בזבל עד ארכובותיו\u0004 (ברכיו) שלא יזוז, \u0003ונותנין סודר קשה לתוך הרכה\u0004 שלא יפגע ויחבל גרונו, \u0003וכורך\u0004 את הסודרים הללו \u0003על צוארו. זה,\u0004 אחד העדים, \u0003מושך\u0004 את הסודר \u0003אצלו\u0004 (לצידו) \u0003וזה מושך אצלו, עד שפותח\u0004 אותו אדם \u0003את פיו\u0004 בעל כורחו מפני שקרוב להיחנק, \u0003ומדליק\u0004 אחר \u0003את הפתילה\u0004 (יבואר להלן): \u0003וזורקה לתוך פיו, ויורדת לתוך מעיו וחומרת\u0004 (שורפת) \u0003את בני מעיו\u0004 ומת.","\u0003ר' יהודה אומר: אף הוא, אם מת בידם\u0004 על ידי הסודרים בחנק \u0003לא היו מקיימין בו מצות שריפה, אלא\u0004 כך עושים: \u0003פותח את פיו\u0004 של הנידון \u0003בצבת שלא בטובתו\u0004 (בכוח, באונס) \u0003ומדליק את הפתילה וזורקה לתוך פיו, ויורדת לתוך מעיו וחומרת את בני מעיו.\u0004","\u0003אמר ר' אלעזר בן צדוק: מעשה בבת כהן אחת שזינתה, והקיפוה חבילי זמורות ושרפוה\u0004 ולא כפי שתואר הדין במשנה! \u0003אמרו לו\u0004 חכמים: \u0003מפני שלא היה בית דין של אותה שעה בקי\u0004 ולא נהג כדין הראוי.","שואלים: \u0003מאי\u0004 \u0005[מה\u0006\u0005]\u0006 היא \u0003פתילה\u0004 זו שאמרנו? \u0003אמר רב מתנה: פתילה\u0004 (חתיכה) \u0003של אבר\u0004 (עופרת) מתיכים ושופכים לתוך בני מעיו.","ושואלים לגופו של ענין: \u0003מנא לן\u0004 \u0005[מניין לנו\u0006\u0005]\u0006 שמיתה כעין זו קרוייה שריפה? ומסבירים: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 מגזירה שווה מהמילים \u0003\"שריפה\" \"שריפה\"\u0004 שנאמרו ב\u0003עדת קרח\u0004 כשהקריבו אש זרה. \u0003מה להלן\u0004 בעדת קורח ב\u0003שריפת נשמה\u0004 בתוך הגוף אבל ה\u0003גוף\u0004 עצמו \u0003קיים, אף כאן שריפת נשמה וגוף קיים,\u0004 ולא בשריפת הגוף בעצים שבה כלה הגוף.","\u0003ר' אלעזר אמר\u0004 ראיה אחרת: \u0003אתיא\u0004 \u0005[באה\u0006 נלמדה ההלכה\u0005]\u0006 בגזירה שווה מן המילים \u0003\"שריפה\" \"שריפה\"\u0004 האמורה כאן ובמיתת \u0003בני אהרן. מה להלן\u0004 בנדב ואביהוא בני אהרן היתה זו \u0003שריפת נשמה וגוף קיים, אף כאן שריפת נשמה וגוף קיים.\u0004","ושואלים: \u0003מאן דיליף\u0004 \u0005[זה שלמד\u0006\u0005]\u0006 \u0003מעדת קרח מנא ליה\u0004 \u0005[מנין לו]\u0006 שגופם לא נשרף? ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006\u0005]:\u0006 \u0003\"את מחתות החטאים האלה בנפשתם\"\u0004 (במדבר יז, ג), ללמד: שרק \u0003נשמתן נשרפת, וגוף קיים.\u0004","\u0003ואידך\u0004 \u0005[האחר]\u0006 שאינו לומד מכאן סבור כי \u0003ההיא\u0004 שנאמרה בעדת קורח \u0003שריפה ממש היא, ומאי\u0004 \u0005[ומה\u0006 שנאמר\u0005]:\u0006 \u0003\"בנפשתם\",\u0004 כוונתו: \u0003שנתחייבו שריפה על עסקי\u0004 (בגלל) \u0003נפשותם\u0004 שעשו רצון והנאת עצמם על ידי קורח, והוא שגרם להם.","וביאור זה הוא \u0003כ\u0004שיטת \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש מאי דכתיב\u0004 \u0005[מהו שנאמר\u0006\u0005]:\u0006 \u0003\"בחנפי לעגי מעוג חרק עלי שנימו\"\u0004 (תהלים לה, טז) — \u0003בשביל חנופה שהחניפו\u0004 אותם אנשים \u0003לקרח על עסקי לגימה\u0004 (ודורש \"מעוג\" לשון עוגה) בשל אכילה ושתיה שהיה מאכילם ומשקם, \u0003חרק עליהן שר של גיהנם שניו,\u0004 שבסופו של דבר לחלקו נפלו בשל עוונותיהם.","ושואלים: \u0003ומאן דיליף\u0004 \u0005[ומי שלמד\u0006\u0005]\u0006 דבר זה \u0003מבני אהרן מנא ליה\u0004 \u0005[מנין לו\u0006\u0005]\u0006 שלא נשרף גופם? ומשיבים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר\u0006\u0005]:\u0006 \u0003\"\u0004ותצא אש מלפני ה' ותאכל אותם \u0003וימתו לפני ה' \"\u0004(ויקרא י, ב), ולשון \"וימותו\" משמעה \u0003כעין מיתה\u0004 שאדם מת כרגיל, שגופו נשאר קיים.","\u0003ואידך\u0004 \u0005[והאחר\u0006\u0005]\u0006 שאינו לומד מכאן סבור ש\u0003ההוא שריפה ממש הואי\u0004 \u0005[היתה]\u0006 \u0003ומאי דכתיב\u0004 \u0005[ומה שנאמר\u0006\u0005]\u0006 \u0003\"וימתו\",\u0004 הכוונה: \u0003דאתחיל בהו מגואי\u0004 \u0005[שהתחילה בהם\u0006 האש \u0005מתוכם]\u0006 ולכן היתה זו \u0003כעין מיתה\u0004 רגילה שאין בה גורם חיצוני. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אבא יוסי בן דוסתאי אומר: שני חוטין של אש יצאו מבית קודש הקדשים ונחלקו לארבע, ונכנסו שנים בחוטמו של זה ושנים בחוטמו של זה ושרפום.\u0004","ומקשים: \u0003והכתיב\u0004 \u0005[והרי נאמר\u0006\u0005]\u0006 \u0003\"\u0004ותצא אש מלפני ה' \u0003ותאכל אותם\"\u0004 (ויקרא י, ב), ומשמעות \"אותם\" למעט, והאומר שהם נשרפו ממש מה ממעט? ומשיבים: ממעט \u0003\"אותם\"\u0004 — \u0003ולא\u0004 את \u0003בגדיהם,\u0004 שאף לשיטה זו הם נשרפו ממש אך בגדיהם לא נשרפו.","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד\u0006\u0005]\u0006 דין שריפת הנידונים \u0003מ\u0004דין \u0003פרים הנשרפים, מה להלן\u0004 בפרים אלה הכוונה היא ב\u0003שריפה ממש\u0004 — \u0003אף כאן שריפה ממש!\u0004","ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר\u0006\u0005]\u0006 כי \u0003מ\u0004מיתת \u0003אדם הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006 \u0003שכן\u0004 הצדדים השווים: בשני המקרים מדובר ב\u0003אדם,\u0004 ומדובר ב\u0003חוטא,\u0004 ובשני המקרים מתוארת נטילת \u0003נשמה\u0004 שיש בשריפה זו. ועוד, שבשני אלה אין שייך \u0003פיגול\u0004 ואילו בפרים הנשרפים דין פיגול קיים כבשאר קרבנות.","ומקשים: \u0003אדרבה\u0004 (להיפך) \u0003מפרים הנשרפים הוה ליה למילף\u0004 \u0005[היה לו ללמוד\u0006\u0005],\u0006 \u0003שכן\u0004 שני הדברים הם \u0003מכשיר\u0004 שנעשים בידי אדם לצורך מצוות, והרי גם בני קורח וגם בני אהרן אינם מצוה. ועוד, שני הדברים הם \u0003לדורות,\u0004 שהיא הלכה קבועה, מה שאין כן בבני קורח ובני אהרן שהיו לשעתם!","ומשיבים: \u0003הנך\u0004 \u0005[אלו]\u0006 צדדי הדמיון לעדת קרח ובני אהרן \u0003נפישין\u0004 \u0005[מרובים\u0006\u0005]\u0006 יותר מן הצדדים הדומים בפרים הנשרפים. ולכן למדים אנו מהם.","ושואלים: \u0003מאן דיליף\u0004 \u0005[מי שלמד\u0006\u0005]\u0006 את הדבר \u0003מעדת קרח, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא יליף\u0004 \u0005[למד\u0006\u0005]\u0006 \u0003מבני אהרן?\u0004 ומשיבים: לדעתו \u0003ההוא שריפה ממש הואי\u0004 \u0005[היתה\u0006\u0005].\u0006 ושואלים: אם כן לשיטתו זו, \u0003ונילף מינה\u0004 \u0005[שילמד ממנה,\u0006 מבני אהרן \u0005]\u0006 שכך אמנם צריך לנהוג לדורות, ודין שריפה הוא שריפה של ממש, ומדוע לומד הוא מעדת קרח?","\u0003אמר רב נחמן אמר רבה בר אבוה, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח), ללמדנו שגם בזמן מיתה \u0003ברור לו מיתה יפה,\u0004 ובודאי שמיתת שריפה האמורה במשנה היא קלה ומהירה יותר משריפת הגוף כולו.","ומקשים: \u0003וכי מאחר דאיכא\u0004 \u0005[שיש\u0006\u0005]\u0006 הלכה זו שקבע \u0003רב נחמן,\u0004 אם כן \u0003גזירה שוה למה לי?\u0004 גם ללא ראיה זו היינו צריכים להמית בשריפה על ידי פתילה, משום שהיא מיתה יפה יותר!","ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא\u0006\u0005]\u0006 \u0003גזירה שוה הוה אמינא\u0004 \u0005[הייתי אומר\u0006\u0005]\u0006 כי ב\u0003שריפת נשמה וגוף קיים לאו\u0004 \u0005[לא]\u0006 \u0003שריפה היא כלל,\u0004 שאינה נכנסת בגדר מצוות התורה לשרוף את החוטא. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 הנימוק של \u0003\"ואהבת לרעך כמוך\"\u0004 היינו מקיימים אותו כמיטב יכולתנו \u0003לפיש ליה חבילי\u0004 \u0005[ירבו לו חבילות]\u0006 \u0003זמורות\u0004 של עצים \u0003כי היכי דלישרוף לעגל\u0004 \u0005[כדי שישרף במהרה\u0006\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 מן הגזירה השווה שאף שריפה פנימית שריפה היא, וכיון שיש בידינו ראיה לכך הרי אפשר לצרף לכך את השיקול שצריכים להקל על הנידון ככל האפשר.","כיון שהוזכרו בני אהרן ומיתתם מביאים מדרש אגדה בענין זה: \u0003וכבר היו משה ואהרן מהלכין בדרך, ונדב ואביהוא מהלכים אחריהן וכל ישראל\u0004 מהלכים \u0003אחריהן, אמר לו נדב לאביהוא: אימתי ימותו שני זקנים הללו ואני ואתה ננהיג את הדור,\u0004 שהרי אנו יורשיהם! \u0003אמר להן הקדוש ברוך הוא: הנראה,\u0004 כלומר, הבה נראה, \u0003מי קובר את מי. אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים בני אדם,\u0006 בפתגם מקובל\u0005]\u0006 \u0003\"נפישי גמלי סבי דטעיני משכי דהוגני\"\u0004 \u0005[מרובים הגמלים הזקנים הטעונים בעורות הבכרים,\u0006 הגמלים הצעירים \u0005].\u0006","\u0003אמר ר' אליעזר:\u0004"],["\u0003למה תלמיד חכם דומה לפני עם הארץ, בתחלה\u0004 שאינו מכירו \u0003דומה\u0004 לפניו \u0003לקיתון\u0004 (כעין כוס) \u0003של זהב. סיפר הימנו\u0004 (שוחח עמו) \u0003דומה לקיתון של כסף, נהנה ממנו\u0004 תלמיד חכם מעם הארץ, \u0003דומה לקיתון של חרש, כיון שנשבר שוב אין לו תקנה\u0004 מה שאין כן בכלים היקרים שגם אם אירע להם דבר מה ניתנים הם לתיקון.","מסופר: אשה ששמה \u0003אימרתא בת טלי, בת כהן שזינתה הואי\u0004 \u0005[היתה\u0006\u0005]\u0006 \u0003אקפה\u0004 \u0005[\u0006צוה \u0005להקיפה]\u0006 \u0003רב חמא בר טוביה חבילי\u0004 \u0005[חבילות]\u0006 \u0003זמורות\u0004 של עצים, \u0003ושרפה.\u0004","\u0003אמר רב יוסף: טעה\u0004 רב חמא בר טוביה \u0003בתרתי\u0004 \u0005[בשתיים];\u0006 \u0003טעה ב\u0004הלכה שקבע \u0003רב מתנה\u0004 שדינה בפתילה של אבר. \u0003וטעה בדתניא\u0004 \u0005[ב\u0006מה \u0005ששנינו\u0006 בברייתא \u0005],\u0006 ששנינו, נאמר: \u0003\"ובאת אל הכהנים הלוים ואל השפט אשר יהיה בימים ההם\"\u0004 (דברים יז, ט), ומן הפסוק למדים: \u0003בזמן שיש כהן\u0004 המשמש בבית המקדש \u0003יש משפט\u0004 בדיני נפשות, \u0003בזמן שאין כהן\u0004 — \u0003אין משפט.\u0004","שנינו במשנה ש\u0003אמר ר' אלעזר בר' צדוק: מעשה בבת כהן שזינתה\u0004 ונידונה בשריפה ממש, ואמרו לו חכמים שלא היה בית הדין של אז בקי. \u0003אמר רב יוסף: בית דין של צדוקים הוה\u0004 \u0005[היה\u0006\u0005],\u0006 והם פירשו את הפסוק כמשמעו.","ושואלים: האם \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר להו\u0004 \u0005[להם,\u0006 לחכמים\u0005]\u0006 ר' אלעזר בר' צדוק \u0003והכי אהדרו ליה\u0004 \u0005[וכך השיבו לו\u0006 החכמים\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]\u0006 בנוסח אחר, \u0003אמר ר' אלעזר בר' צדוק: זכורני כשהייתי תינוק, ומורכב על כתיפו של אבא, והביאו בת כהן שזינתה והקיפוה חבילי\u0004 \u0005[חבילות]\u0006 \u0003זמורות\u0004 של עצים, \u0003ושרפוה. אמרו לו\u0004 חכמים: \u0003קטן היית\u0004 אז, \u0003ואין מביאין ראיה מן הקטן,\u0004 כי שמא לא הבנת כראוי את הענין. והרי זו סתירה בולטת בין הגרסות! ומשיבים: \u0003שני מעשים\u0004 נפרדים \u0003הוו\u0004 \u0005[היו\u0006\u0005]\u0006 ובשניהם העיד ר' אלעזר בר' צדוק.","ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 מהם \u0003אמר להו ברישא\u0004 \u0005[להם\u0006 לחכמים \u0005בתחילה\u0006\u0005]?\u0006 \u0003אילימא הא קמייתא\u0004 \u0005[אם תאמר\u0006 את \u0005זו הראשונה]\u0006 הכתובה במשנה \u0003אמר להו ברישא\u0004 \u0005[להם תחילה\u0006\u0005]\u0006 — דבר זה לא יתכן, כי אם \u0003אמר\u0004 להם על דבר שאירע \u0003כשהוא גדול ולא אשגחו ביה\u0004 \u0005[השגיחו בו\u0006\u0005],\u0006 ודחוהו באומרם שבית הדין לא היה מוסמך, \u0003אמר להו\u0004 \u0005[להם]\u0006 אחר כך מעשה שאירע \u0003כשהוא קטן ואשגחו ביה\u0004 \u0005[והשגיחו בו?!]\u0006","\u0003אלא, הא\u0004 \u0005[זו]\u0006 השנויה בתוספתא \u0003אמר להו ברישא\u0004 \u0005[להם בתחילה\u0006\u0005],\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003קטן היית\u0004 ואין מביאים ראיה מן הקטן, \u0003ואמר\u0004 להם מעשה שאירע \u0003כשהוא גדול, ואמרו ליה\u0004 \u0005[לו]:\u0006 טעם הדבר \u0003מפני שלא היה בית דין של אותה שעה בקי\u0004 בהלכה.","\u0003מצות הנהרגין\u0004 כיצד היו עושים? — \u0003היו מתיזין\u0004 (קוצצים) \u0003את ראשו בסייף, כדרך שהמלכות עושה. ר' יהודה אומר:\u0004 אין עושים כן, שכן \u0003ניוול הוא לו\u0004 במיתה זו. \u0003אלא מניחין את ראשו\u0004 של הנידון \u0003על הסדן וקוצץ בקופיץ\u0004 (סכין גדולה). \u0003אמרו לו\u0004 החכמים: אם חושש אתה לניוול הרי \u0003אין מיתה מנוולת מזו\u0004 וטוב לו שימיתוהו כדרך שאמרנו אנו.","\u0003תניא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]\u0006 בהמשך לדברים שבמשנה: \u0003אמר להן ר' יהודה לחכמים: אף אני יודע שמיתה מנוולת היא, אבל מה אעשה שהרי אמרה תורה \"ובחקתיהם לא תלכו\"\u0004 (ויקרא יח, ג) ואין לנהוג כמנהגי הגויים!","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005]\u0006 מה משיבים הם כנגד טענה זו? ומשיבים: \u0003כיון דכתיב\u0004 \u0005[שנאמר\u0006 \u0005ה]\u0006 מיתת \u0003סייף באורייתא\u0004 \u0005[בתורה\u0006\u0005],\u0006 \u0003לא מינייהו קא גמרינן\u0004 \u0005[מהם אנו לומדים\u0006\u0005],\u0006 ואנו עושים כדיננו ואיננו מתחשבים בהם כלל, הגם שיש בדין הגויים משום דמיון והקבלה.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך\u0006\u0005]\u0006 שדבר שהוא ממנהג ישראל אין אוסרים אותו אף שגם הגויים נוהגים כן, אם כן \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]\u0006 \u0003שורפין על המלכים\u0004 כלים ובגדים כביטוי של אבל \u0003ו\u0004דבר זה הוא \u0003לא מדרכי האמורי,\u0004 ומותר, \u0003היכי שרפינן\u0004 \u0005[איך שורפים אנו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ובחקתיהם לא תלכו\"! אלא, כיון דכתיב\u0004 \u0005[שנאמרה]\u0006 \u0003שריפה\u0004 על מלכים \u0003באורייתא\u0004 \u0005[בתורה]\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ובמשרפות אבותיך\u0004 המלכים הראשונים אשר היו לפניך כן ישרפו לך\u0003\"\u0004 (ירמיה לד, ה), \u0003לאו\u0004 \u0003מינייהו קא גמרינן\u0004 \u0005[לא מהם אנו לומדים\u0006\u0005]\u0006 אלא מנהגנו שלנו בידינו אף שגם הגוים נוהגים כך. \u0003והכא נמי\u0004 \u0005[כאן גם כן\u0006\u0005]\u0006 \u0003כיון\u0004 שנאמר \u0003סייף באורייתא\u0004 \u0005[בתורה]\u0006 — \u0003לאו מינייהו קא גמרינן\u0004 \u0005[לא מהם אנו לומדים\u0006\u0005].\u0006","\u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה\u0005]\u0006 \u0003באידך פירקין\u0004 \u0005[בפרקנו האחר\u0006\u0005]\u0006 במסכת זו, \u0003אלו הן הנהרגין: הרוצח, ואנשי עיר הנדחת. בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 לגבי \u0003עיר הנדחת כתיב בהו\u0004 \u0005[נאמר בהם\u0006\u0005]\u0006 במפורש: \u0003\"\u0004הכה תכה את יושבי העיר ההיא \u0003לפי חרב\"\u0004 (דברים יג, טז). \u0003אלא רוצח מנלן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 שדינו בחרב?","ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"\u0004וכי יכה איש את עבדו או את אמתו בשבט ומת תחת ידו \u0003נקם ינקם\"\u0004 (שמות כא, כ), ו\u0003\"נקימה\" זו איני יודע מה הוא. כשהוא אומר \"והבאתי עליכם חרב נקמת נקם ברית\"\u0004 (ויקרא כו, כה), \u0003הוי אומר: \"נקימה\" זו\u0004 מיתה ב\u0003סייף.\u0004 ושואלים: ומנין שקוצצים ראשו בחרב?","\u0003ואימא דבריז ליה מיברז\u0004 \u0005[ואמור שדוקר הוא אותו\u0006\u0005]\u0006 בחרב! ומשיבים: \u0003\"לפי חרב\" כתיב\u0004 \u0005[נאמר\u0006\u0005],\u0006 משמע שבלהב החרב מכים ולא בחודה.","ושואלים: \u0003ואימא דעביד ליה גיסטרא\u0004 \u0005[ואמור שעושה אותו מחצית\u0006\u0005],\u0006 שחותכים אותו באמצע גופו! ומשיבים, \u0003אמר רב נחמן אמר רבה בר אבוה: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 — \u0003ברור לו מיתה יפה,\u0004 ואילו בהריגתו על ידי חציית גופו בחרב אין משום מיתה יפה.","ועדיין מקשים: \u0003אשכחן דקטל עבדא\u0004 \u0005[מצאנו\u0006 ראיה למי \u0005שהרג עבד\u0006\u0005]\u0006 שנידון בסייף, ואולם ההורג \u0003בר\u0004 \u0005[בן]\u0006 \u0003חורין מנא לן\u0004 \u0005[מנין לנו\u0006\u0005]?\u0006","ומשיבים: \u0003ולאו\u0004 \u0005[וכי לא\u0006\u0005]\u0006 \u0003קל וחומר הוא?\u0004 אם \u0003קטל עבדא\u0004 \u0005[הרג עבד\u0006\u0005]\u0006 דינו \u0003בסייף,\u0004 ההורג \u0003בר חורין\u0004 יהא דינו \u0003בחנק\u0004 בלבד?","ראיה זו דוחים: \u0003הניחא\u0004 \u0005[זה נוח\u0006\u0005]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006\u0005]\u0006 ש\u0003חנק קל\u0004 מסייף. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006\u0005]\u0006 ש\u0003חנק חמור\u0004 מסייף, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר\u0006\u0005]?\u0006 והרי יתכן באמת כי בן־חורין, החמור יותר, מיתתו בחנק דווקא!","ומשיבים: \u0003נפקא ליה מדתניא\u0004 \u0005[יוצא לו,\u0006 נלמד הדבר מן הברייתא\u0005]\u0006 השנויה על האמור בדיני עגלה ערופה: \u0003\"ואתה תבער הדם הנקי מקרבך\"\u0004 (דברים כא, ט) \u0003הוקשו\u0004 \u0005[הושוו\u0006\u0005]\u0006 בכתוב זה \u0003כל שופכי דמים לעגלה ערופה; מה להלן\u0004 בעגלה ערופה עצמה חותכים את ראשה \u0003בסייף ומן הצואר, אף כאן\u0004 בעונש הרוצח \u0003בסייף ומן הצואר.\u0004","ומקשים: \u0003אי מה להלן\u0004 \u0005[או מה שם\u0006\u0005]\u0006 בעגלה ערופה חותכים את הצוואר \u0003בקופיץ, וממול\u0004 (בהמשך) ה\u0003עורף, אף כאן\u0004 ברוצח ידון \u0003בקופיץ וממול עורף!\u0004 \u0003אמר רב נחמן אמר רבה בר אבוה: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 — \u0003ברור לו מיתה יפה.\u0004 ואם כי לומדים את עיקר הדין מעגלה ערופה, הרי בוררים לנידון את העונש הקל במידת האפשר על פי דין תורה.","\u0003מצות הנחנקין\u0004 כיצד היו עושים? — \u0003היו משקעין אותו\u0004 את הנידון \u0003בזבל עד ארכובותיו\u0004 שלא יזוז, \u0003ונותן סודר קשה לתוך הרכה וכורך על צוארו, זה\u0004 עד אחד \u0003מושך אצלו וזה\u0004 העד האחר \u0003מושך אצלו, עד ש\u0004נחנק ו\u0003נפשו יוצאת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 את הכתוב \"ואיש אשר ינאף את אשת איש אשר ינאף את אשת רעהו מות יומת הנואף והנואפת\" (ויקרא כ, י) דורשים: \u0003\"איש\"\u0004 פירושו: אדם מבוגר — \u0003פרט לקטן\u0004 שלא התבגר שנאף, \u0003\"אשר ינאף את אשת איש\"\u0004 — \u0003פרט לאשת קטן\u0004 שאין נשואין לקטן קרויים נשואין. \u0003\"אשת רעהו\"\u0004 — \u0003פרט לאשת אחרים\u0004 כלומר, גוים, שאינם קרויים \"רעהו\".","\u0003\"מות יומת\"\u0004 משמעו: \u0003בחנק.\u0004 ודנים: \u0003אתה אומר\u0004 שמיתתו \u0003בחנק, או אינו אלא באחת מכל מיתות\u0004 אחרות \u0003האמורות בתורה? אמרת\u0004 \u0005[אומר אתה]:\u0006 \u0003כל מקום שנאמר\u0004 לשון \u0003\"מיתה\" בתורה סתם, אין אתה רשאי למושכה להחמיר עליה, אלא להקל עליה,\u0004 אלו \u0003דברי ר' יאשיה,\u0004 כלומר, כיון שאין לימוד מיוחד להחמיר, מקבלים את דברי התורה כמתכוונים למיתה הקלה ביותר — מיתת חנק.","\u0003ר' יונתן אומר: לא מפני שהיא,\u0004 החנק, \u0003קלה\u0004 שבמיתות \u0003אלא\u0004 לדעתו \u0003כל מיתה האמורה בתורה סתם אינה אלא חנק\u0004 ושאר מיתות צריך שיפורשו במיוחד בכתוב.","\u0003רבי\u0004 (יהודה הנשיא) \u0003אומר\u0004 בשיטת ר' יונתן: \u0003נאמר\u0004 בכמה מקומות \u0003מיתה בידי שמים, ונאמר מיתה בידי אדם. מה מיתה האמורה בידי שמים\u0004 הריהי \u0003מיתה שאין בה רושם\u0004 חיצוני, \u0003אף מיתה האמורה בידי אדם\u0004 — \u0003מיתה שאין בה רושם.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שתהא זו מיתת \u0003שריפה\u0004 שאף היא אינה עושה רושם מבחוץ! ומשיבים: \u0003מדאמר רחמנא\u0004 \u0005[כיון שאמרה התורה]\u0006 ופירשה כי \u0003בת כהן\u0004 נידונה \u0003בשריפה, מכלל\u0004 הדברים אנו לומדים \u0003דהא\u0004 \u0005[שזו],\u0006 כל אחרת שזנתה, \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בת שריפה היא\u0004 אלא נידונה במיתה אחרת שאינה עושה רושם, והיא חנק."],["\u0003בשלמא\u0004 \u0005[נניח\u0006\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' יונתן\u0004 — \u0003כדקא מפרש\u0004 \u0005[כפי שמפרש]\u0006 \u0003רבי טעמא\u0004 \u0005[\u0006את \u0005הטעם\u0006\u0005]\u0006 לשיטתו. \u0003אלא לר' יאשיה ממאי דאיכא\u0004 \u0005[ממה\u0006 למד הוא \u0005שיש\u0006\u0005]\u0006 מיתת \u0003חנק בעולם?\u0004 הרי לא נתפרשה בתורה מיתה זו שיוכל לומר שמיתת סייף קלה ממנה, \u0003אימא\u0004 \u0005[אמור\u0006\u0005]\u0006 שקלה שבמיתות היא מיתת \u0003סייף\u0004 שנתפרשה בתורה!","\u0003אמר רבא: ארבע מיתות גמרא גמירי להו\u0004 \u0005[במסורת למודים\u0006 היו \u0005אותן]\u0006 ולא דנו בסוגי המיתות אלא בשאלה באלו מן המיתות מענישים על עבירות מסויימות.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לא מפני שהיא קלה\"\u0004 בדברי ר' יונתן? ומשיבים: כי \u0003קמיפלגי בפלוגתא\u0004 \u0005[חלוקים במחלוקתם\u0006\u0005]\u0006 של \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006 האם המיתה הקלה היא חנק או סייף, ולכן לא השתמש ר' יונתן בהנחה זו שחנק היא הקלה שבמיתות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לאביי: שאר הנסקלין\u0004 ש\u0003לא כתיב בהו\u0004 \u0005[נאמר בהם\u0006\u0005]\u0006 במפורש \u0003סקילה,\u0004 ידוע \u0003דגמרי\u0004 \u0005[ש\u0006הם \u0005למדים\u0006\u0005]\u0006 זאת בגזירה שווה \u0003מאוב וידעוני\u0004 שכתוב בהם \"מות יומתו באבן ירגמו אותם דמיהם בם\u0003\"\u0004 (ויקרא כ, כז), ואולם \u0003במאי גמרי\u0004 \u0005[במה\u0006 בדיוק \u0005למדים\u0006\u0005],\u0006 מאילו מילים למדים שדינם כך הוא? האם ממה שנאמר אף באלה \u0003ב\"מות יומתו\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005],\u0006 \u0003או ב\"דמיהם בם\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ב\"דמיהם\" \"דמיהם בם\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005].\u0006 וראיה לדבר, \u0003דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 \u0003ב\"מות יומתו\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005],\u0006 \u0003\"דמיהם\" \"דמיהם\"\u0004 הכתוב בדינים שונים \u0003למה לי?\u0004","ומקשים: \u0003אלא מאי\u0004 \u0005[מה\u0006\u0005]\u0006 רוצה אתה לומר, כי \u0003ב\"דמיהם\" \"דמיהם\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005],\u0006 אם כן קיימת אותה שאלה: \u0003\"מות יומתו\" למה לי?\u0004","ומשיבים: ביטוי זה נצרך לענין אחר, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 ממה שנאמר \u0003\"מות יומת המכה רצח הוא\"\u0004 (במדבר לה, כא), \u0003אין לי אלא\u0004 שיומת \u0003במיתה הכתובה בו, מניין שאם אי\u0004 (אין) \u0003אתה יכול להמיתו במיתה הכתובה בו, שאתה ממיתו בכל מיתה\u0004 אחרת \u0003שאתה יכול להמיתו\u0004 — \u0003תלמוד לומר: \"מות יומת המכה\"\u0004 — \u0003מכל מקום,\u0004 וכן היא משמעות \"מות יומתו\" בכל מקום.","על שאלה ותשובה זו דנו אחר כך אמוראים מאוחרים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: ואי\u0004 \u0005[ואם\u0006\u0005]\u0006 גם נאמר כי \u0003ב\"מות יומתו\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005],\u0006 \u0003מאי קא קשיא ליה\u0004 \u0005[מה היה קשה לו]\u0006 בהלכות אלה שבשל כך הוצרך לברר מהו מקור הגזירה השווה?","\u0003אילימא\u0004 \u0005[אם תאמר\u0006\u0005]\u0006 כי \u0003אשת איש קא קשיא ליה\u0004 \u0005[היה קשה לו]\u0006 שנאמר בה \"מות יומת הנואף והנואפת\", ושמא תאמר \u0003למיתי ולמיגמר\u0004 \u0005[לבוא וללמוד\u0006\u0005]\u0006 בגזירה שווה \u0003\"מות יומת\" מאוב וידעוני, מה להלן\u0004 נידונים הם \u0003בסקילה\u0004 כמפורש בהם, \u0003אף כאן\u0004 באשת איש הריהי נידונה \u0003בסקילה.\u0004","ואולם \u0003מדאמר רחמנא\u0004 \u0005[מ\u0006כיון \u0005שאמרה התורה]\u0006 ש\u0003ארוסה\u0004 שזנתה נידונה \u0003בסקילה, מכלל\u0004 הדברים מובן ש\u0003נשואה לאו\u0004 \u0005[לא]\u0006 נידונה \u0003בסקילה\u0004 אלא במיתה קלה יותר, ולא יכולים היינו לסבור כך בטעות.","\u0003ואלא\u0004 תאמר כי \u0003מכה אביו ואמו קא קשיא ליה\u0004 \u0005[היה קשה לו\u0006\u0005],\u0006 שנאמר: \"ומכה אביו ואמו מות יומת\" (שמות כא, טו), שאפשר לומר כי \u0003למיתי ולמיגמר\u0004 \u0005[יבוא וילמד\u0006\u0005]\u0006 הדבר \u0003מאוב וידעוני\u0004 והיינו הורגים את מכה אביו ואמו בסקילה.","ואולם גם כאן יש נימוק לדחות אפשרות של השוואה שכזו, שכן \u0003עד דגמרי\u0004 \u0005[שלומדים\u0006 הם\u0005]\u0006 את עונשם \u0003מאוב וידעוני,\u0004 יבואו ו\u0003ליגמרו\u0004 \u0005[ילמדו]\u0006 \u0003מאשת איש,\u0004 שהרי כשיש לך ספק באיזה מיתה ידון, ש\u0003אי אתה רשאי למושכה להחמיר עליה אלא להקל עליה\u0004 ככל דבר שיש בו ספק נפשות. ואם כן שני מקראות אלה למדים מעניינם שאינם באים לסקילה, ובמה התקשה ר' זירא והוצרך לברר את מקור הלימוד?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 לא בענין זה התקשה, כי אם \u0003שאר הנסקלין גופייהו\u0004 \u0005[עצמם\u0006\u0005]\u0006 \u0003קא קשיא ליה\u0004 \u0005[היה קשה לו\u0006\u0005],\u0006 \u0003דאי\u0004 \u0005[שאם\u0006\u0005]\u0006 \u0003ב\"מות יומת\" גמרי\u0004 \u0005[למדים\u0006 הם\u0005],\u0006 \u0003עד דגמרי\u0004 \u0005[שילמדו\u0006\u0005]\u0006 \u0003מאוב וידעוני,\u0004 שכתב בהם \"מות יומת\" \u0003ליגמרו\u0004 \u0005[שילמדו\u0006\u0005]\u0006 \u0003מאשת איש\u0004 שאף בה נאמר \"מות יומת\" וידונו במיתת חנק הקלה ביותר, ולא בחמורה. ולכן הודגש כי הלימוד הוא ממה שנאמר בנסקלים \"דמיהם בם\".","\u0003אלו הן הנסקלין: הבא על האם, ועל אשת האב\u0004 אף שאינה אמו, \u0003ועל הכלה\u0004 (אשת בנו), \u0003ועל הזכור\u0004 (זכר), \u0003ועל הבהמה, והאשה המביאה את הבהמה\u0004 עליה. \u0003והמגדף\u0004 (מקלל את ה'), \u0003והעובד עבודה זרה, והנותן מזרעו למולך, ובעל אוב וידעוני, והמחלל את השבת, והמקלל\u0004 את \u0003אביו ואמו, והבא על נערה המאורסה. והמסית\u0004 יחידים לעבודה זרה, \u0003והמדיח\u0004 קהל שלם לעבודה זרה, \u0003והמכשף, ובן סורר ומורה.\u0004","ומפרטים: \u0003הבא על האם\u0004 שהיא גם אשת אביו \u0003חייב עליה משום אם ומשום אשת אב. ר' יהודה אומר: אינו חייב אלא משום האם בלבד.\u0004","\u0003הבא על אשת אב חייב משום אשת אב ומשום אשת איש\u0004 (שהרי היא גם אשה נשואה, לאביו). וחייב משום אשת אב \u0003בין בחיי אביו, בין לאחר מיתת אביו, בין\u0004 שהיתה אשת אביו מן \u0003האירוסין, בין מן הנישואין.\u0004","וכן \u0003הבא על כלתו\u0004 בחיי בנו \u0003חייב עליה משום כלתו ומשום אשת איש.\u0004 ומשום איסור כלתו חייב \u0003בין בחיי בנו, בין לאחר מיתת בנו, בין\u0004 שהיא אשת בנו \u0003מן האירוסין, בין מן הנישואין.\u0004","ועוד בענין הבא על האם \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: אם לא היתה אמו ראויה לאביו,\u0004 שהיה איסור בנישואיהם, אם בא עליה \u0003אינו חייב אלא משום האם בלבד,\u0004 אבל אינו חייב משום אשת אב.","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינה ראויה לו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהיו האם והאב זה לזה \u0003חייבי כריתות\u0004 או \u0003חייבי מיתות בית דין,\u0004 האם \u0003מכלל\u0004 הדברים תלמד \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 שהדין כן \u0003אף על גב\u0004 \u0005[אף על פי\u0006\u0005]\u0006 ש\u0003אינה ראויה לו?\u0004 בחייבי כריתות ומיתות בית דין לדעת הכל \u0003הא לית ליה\u0004 \u0005[הרי אין לו]\u0006 \u0003קידושין בגווה\u0004 \u0005[בה\u0006\u0005],\u0006 שאדם המקדש אשה האסורה עליו באיסור שעונשו כרת או מיתת בית דין אין הקידושין תופסים בה, וגם אם יחיה עמה אינה נחשבת לעולם כאשתו.","\u0003אלא\u0004 צריכים לומר שמשמעות \"אינה ראוייה\" — שהם \u0003חייבי לאוין\u0004 (מצוות \"לא תעשה\") על ביאתם. \u0003ור' יהודה סבר לה\u0004 \u0005[סבור הוא]\u0006 בענין זה \u0003כ\u0004שיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר: אין קידושין תופסין בחייבי לאוין\u0004 כמו בחייבי מיתות בית דין, ולכן אשה זו שהיא אמו אינה נחשבת כלל אשת אביו, ועל כך חלקו חכמים, ולשיטתם קידושין תופסים באלו אף שיש בהם איסור, ולכן אשת אביו היא, וחייב אף משום אשת אב.","\u0003מתיב\u0004 \u0005[מקשה\u0006\u0005]\u0006 \u0003רב אושעיא\u0004 ממה ששנינו בדיני יבמות: אם היתה היבמה ליבם בגדר \u0003איסור מצוה,\u0004 כלומר, קרובה בדרגת קירבה האסורה רק מדברי חכמים, \u0003ואיסור קדושה,\u0004 כגון גרושה לכהן — יבמות כאלה \u0003חולצות ולא מתייבמות,\u0004 שלשיטה זו קיים בכגון זו יחס מן התורה בין היבם ויבמתו (מה שאין כן באיסורי כרת ומיתה) אבל כיון שאסור לשאת אשה כזו — יחלוץ לה היבם, ויצא ידי כל החובות."],["ומסבירה המשנה: \u0003איסור מצוה\u0004 אלה הן ה\u0003שניות מדברי סופרים\u0004 שהוסיפו חכמים לאסור עוד כמה נשים קרובות כדי לעשות סייג. ומסבירים בגמרא: \u0003ואמאי קרו להו\u0004 \u0005[ומדוע קוראים להן\u0006\u0005]\u0006 \u0003\"איסור מצוה\"\u0004 — משום \u0003שמצוה לשמוע דברי חכמים.\u0004","ו\u0003\"איסור קדושה\"\u0004 — כגון איסור \u0003אלמנה לכהן גדול,\u0004 או \u0003גרושה וחלוצה לכהן הדיוט.\u0004 ומסבירים \u0003ואמאי קרו להו\u0004 \u0005[ומדוע קוראים להן\u0006\u0005]\u0006 \u0003\"איסור קדושה\"\u0004 — שנאמר בכהנים: \u0003\"קדשים יהיו לאלהיהם\"\u0004 (ויקרא כא, ו).","\u0003ותניא עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה\u0006\u0005]\u0006 על משנה זו: \u0003ר' יהודה מחליף,\u0004 שהוא קורא \"איסור מצוה\" לגרושה וחלוצה לכהן, ו\"איסור קדושה\" לשניות האסורות מדברי סופרים.","ולעיקר הדין יש מקום לדקדק: \u0003חלופי\u0004 \u0005[להחליף]\u0006 \u0003הוא\u0004 ש\u0003מחליף\u0004 הוא את השמות, אך אינו חולק על ההלכה, \u0003הא\u0004 \u0005[הרי]\u0006 שלהלכה \u0003חליצה בעיא\u0004 \u0005[צריכה\u0006\u0005]\u0006 היא, אף לדעת ר' יהודה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006\u0005]\u0006 לומר ש\u0003ר' יהודה\u0004 סבור \u0003כ\u0004שיטת \u0003ר' עקיבא סבירא ליה, מכדי\u0004 \u0005[הרי]\u0006 \u0003חייבי לאוין ל\u0004שיטת \u0003ר' עקיבא כחייבי כריתות דמי\u0004 \u0005[\u0006הם \u0005נחשבים\u0006\u0005]\u0006 \u0003וחייבי כריתות לאו\u0004 \u0005[לא]\u0006 \u0003בני חליצה ויבום נינהו\u0004 \u0005[הם\u0006\u0005],\u0006 שאין מצוות יבום חלה כלל על קרובות אלה! והמצריך חליצה בלא ספק סבור שקידושין תופסים בנשים אלה, שלא כר' עקיבא!","ודוחים: לא, להלכה סובר ר' יהודה כר' עקיבא, ומה שהעיר ביחס לאיסורי מצוה וקדושה, \u0003לדבריו,\u0004 כלומר, לשיטתו של ה\u0003תנא קמא קאמר\u0004 \u0005[הראשון אמר]\u0006 \u0003וליה לא סבירא ליה\u0004 \u0005[והוא עצמו אינו סבור]\u0006 אלא העיר לו שאף לשיטתו יש להחליף את השמות, אבל בעצם חולק הוא על כל אותו דין.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל לבבל \u0003תני כדתנן\u0004 \u0005[שנה\u0006 ברייתא \u0005כפי ששנינו\u0006 במשנתנו\u0005]:\u0006 \u0003ר' יהודה אומר: אינו חייב אלא משום האם בלבד,\u0004 גם בשעה שהיתה ראויה לאביו.","ושואלים: \u0003וטעמא מאי\u0004 \u0005[וטעם\u0006 הדבר \u0005מהו\u0006\u0005]\u0006 שאינו חייב? \u0003אמר אביי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ערות אביך וערות אמך לא תגלה \u0003אמך הוא\u0004 לא תגלה ערותה\" (ויקרא יח, ז), ולדעתו ההדגשה היא זו: \u0003משום אמו אתה מחייבו, ואי\u0004 (אין) \u0003אתה מחייבו משום אשת אב.\u0004","ומקשים: \u0003אלא מעתה\u0004 (אם כך) אנו מדייקים \u0003\"ערות אשת אביך לא תגלה ערות אביך הוא\"\u0004 (ויקרא יח, ח) האם נאמר כי \u0003משום אשת אב אתה מחייבו, ואי אתה מחייבו משום אמו?\u0004","\u0003אלא אמו שהיא אשת אביו.\u0004 נמצא כי \u0003קאי הכא\u0004 \u0005[עומד כאן],\u0006 בפסוק על אמו \u0003וממעט לה\u0004 משום אשת אביו, \u0003קאי הכא\u0004 \u0005[עומד כאן]\u0006 בענין אשת אביו \u0003וממעט לה\u0004 משום אמו, \u0003השתא\u0004 \u0005[עכשיו\u0006\u0005]\u0006 יוצא ש\u0003אמו שאינה אשת אביו\u0004 — \u0003מיחייב\u0004 \u0005[חייב\u0006\u0005],\u0006 \u0003אשת אביו שאינה אמו\u0004 — \u0003מיחייב\u0004 \u0005[חייב\u0006\u0005],\u0006 אבל \u0003אמו שהיא אשת אביו לא מיחייב\u0004 \u0005[אינו מתחייב\u0006\u0005]\u0006 \u0003כלל,\u0004 וכי אפשר לומר דבר כזה?!","\u0003ותו, לרבנן נמי\u0004 \u0005[ועוד, ל\u0006דעת \u0005חכמים גם כן\u0006\u0005]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר\u0006\u0005]\u0006 \u0003\"אמך הוא\",\u0004 וכיצד מפרשים הם, שהרי הם מחייבים במקרה שכזה גם משום האם וגם משום האב? \u0003אלא, ההוא\u0004 (אותה הדגשה) \u0003מיבעי ליה\u0004 \u0005[נחוצה להם\u0006\u0005]\u0006 \u0003ל\u0004כמו שפירשה \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי\u0004 (בסוף סוגיה זו), אם כן \u0003לר' יהודה נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 הכתוב \u0003ההוא מיבעי ליה\u0004 \u0005[צריך אותו\u0006\u0005]\u0006 \u0003ל\u0004כמו שפירשה \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי,\u0004 ואין כאן מקום ללימוד שאמר אביי.","\u0003אלא אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא,\u0004 כך לומד זאת ר' יהודה: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 הזה, בהדגשה: \u0003\"ערותה\",\u0004 לאמור: \u0003משום ערוה אחת אתה מחייבו, ואי\u0004 (אין) \u0003אתה מחייבו משום שתי ערות,\u0004 שגזירת הכתוב היא שאין מחייבים אותו כאן משום שני איסורי ערוה.","ומקשים: אם כן כשנאמר \u0003\"ערות כלתך לא תגלה אשת בנך היא לא תגלה ערותה\"\u0004 (ויקרא יח, טו) \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006\u0005]\u0006 תאמר \u0003משום ערוה אחת אתה מחייבו ואי אתה מחייבו משום שתי ערות?!\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006\u0005]\u0006 במפורש במשנתנו: \u0003הבא על כלתו חייב עליה משום כלתו ומשום אשת איש, בין בחיי בנו בין לאחר מיתת בנו, ולא פליג\u0004 \u0005[חלק\u0006\u0005]\u0006 \u0003ר' יהודה\u0004 על דין זה!","\u0003אלא\u0004 חייב אתה לפרש את הכתוב בלשון יחיד \"ערותה\", כך: \u0003כיון דחד גופא\u0004 \u0005[שגוף אחד\u0006\u0005]\u0006 \u0003הוא\u0004 שבו נעשות העבירות, \u0003אף על גב דתרי איסורי נינהו\u0004 \u0005[אף על פי ששני איסורים הם\u0006\u0005]\u0006 לכן \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 \u0003\"ערותה\"\u0004 בלשון יחיד. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0005באשת אביו,\u0006 \u0003כיון דחד גופא\u0004 \u0005[שגוף אחד]\u0006 \u0003הוא, אף על גב דתרי איסורי נינהו\u0004 \u0005[אף על פי ששני איסורים הם\u0006\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 \u0003\"ערותה\"\u0004 בלשון יחיד, אין ללמוד מכאן שחייב הכתוב רק באיסור אחד במקרה שכזה.","\u0003אלא אמר רבא:\u0004 זהו פירוש דעתו של ר' יהודה, \u0003קסבר\u0004 \u0005[סבר\u0006\u0005]\u0006 \u0003ר' יהודה\u0004 לפרש: \u0003\"ערות אביך\"\u0004 — \u0003זו אשת אביך, ומייתי לה\u0004 \u0005[ומביא,\u0006 לומד, \u0005אותה,\u0006 את הדבר\u0005]\u0006 \u0003בגזירה שוה,\u0004 ממה שנאמר בכתוב אחר \"ואיש אשר ישכב את אשת אביו ערות אביו גילה","\u0003\"\u0004(ויקרא כ, יא), \u0003ומשמע\u0004 הכתוב \u0003בין אשת אביו שהיא אמו, בין אשת אביו שאינה אמו,\u0004 ואולם הבא על \u0003אמו שאינה אשת אביו\u0004 (כגון אנוסת אביו) \u0003מניין\u0004 לו שחייב — \u0003תלמוד לומר: \"ערות אמך לא תגלה אמך הוא\",\u0004 ללמד שיש מקרה שבו \u0003משום אמו אתה מחייבו, ואי אתה מחייבו משום אשת אביו,\u0004 ואין זה משנה אם היתה נשואה לאביו אם לא."],["\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו\u0006\u0005]\u0006 של \u0003רבא,\u0004 נאמר: \"ואיש אשר ישכב את אשת אביו ערות אביו גלה מות יומתו שניהם דמיהם בם\" (ויקרא כ, יא), \u0003\"איש\"\u0004 משמעו — \u0003פרט לקטן.\u0004","\u0003\"אשר ישכב את אשת אביו\"\u0004 — \u0003משמע בין אשת אביו שהיא אמו, ובין אשת אביו שלא אמו. אמו שאינה אשת אביו מניין\u0004 שאף היא בכלל זה? — \u0003תלמוד לומר: \"ערות אביו גלה\"\u0004 (ויקרא כ, יא), ו\u0003מופנה\u0004 ביטוי זה, שאין ממנו לימוד לעניינו, וזאת כדי \u0003להקיש\u0004 (להשוות) \u0003ולדון ממנו גזרה שוה\u0004 לדינים אחרים.","ועוד נאמר \u0003\"מות יומתו\"\u0004 (ויקרא כ, יא), וכוונתו שדינם \u0003בסקילה. אתה אומר\u0004 שדינם \u0003בסקילה, או\u0004 אולי \u0003אינו אלא באחת מכל\u0004 שאר \u0003מיתות האמורות בתורה?\u0004 ומביאים ראיה: \u0003נאמר כאן \"דמיהם בם\"\u0004 (ויקרא כ, יא) \u0003ונאמר באוב וידעוני \"דמיהם בם\"\u0004 (ויקרא כ, כז), \u0003מה להלן\u0004 באוב וידעוני דינם \u0003בסקילה\u0004 כמפורש בהם, \u0003אף כאן\u0004 דינם \u0003בסקילה.\u0004","\u0003עונש\u0004 למגלה ערוות אשת אביו \u0003שמענו,\u0004 ואולם \u0003אזהרה\u0004 (איסור) \u0003מניין,\u0004 היכן נאמר שיש איסור בדבר? — \u0003תלמוד לומר: \"ערות אביך\u0004 וערות אמך \u0003לא תגלה\"\u0004 (ויקרא כ, יח, ז), \u0003\"ערות אביך\"\u0004 — \u0003זו אשת אביך.\u0004","\u0003אתה אומר\u0004 שערוה זו היא \u0003אשת אביך, או אינו אלא ערות אביך ממש\u0004 במשכב זכור? — \u0003נאמר כאן: \"ערות אביך... לא תגלה\"\u0004 (ויקרא כ, יח, ז), \u0003ונאמר להלן: \"\u0004ואיש אשר ישכב את אשת אביו \u0003ערות אביו גלה\"\u0004 (ויקרא כ, כ, יא) \u0003מה להלן באישות\u0004 (בנישואין) \u0003הכתוב מדבר, אף כאן באישות הכתוב מדבר.\u0004","\u0003ומשמע\u0004 מכתוב זה לאיסור \u0003בין אשת אביו שהיא אמו בין אשת אביו שאינה אמו,\u0004 ואולם \u0003אמו שאינה אשת אביו מניין\u0004 שאף היא בכלל זה? \u0003תלמוד לומר: \"וערות אמך לא תגלה\"\u0004 (ויקרא כ, יח, ז).","\u0003אין לי אלא באזהרה\u0004 (איסור) \u0003שעשה\u0004 (השווה) \u0003הכתוב\u0004 דין \u0003אמו שאינה אשת אביו כאמו שהיא אשת אביו,\u0004 ואולם לענין \u0003עונש מניין\u0004 שדין אחד להן?","\u0003—\u0004 \u0003נאמר כאן: \"ערות אביך... לא תגלה\"\u0004 (ויקרא כ, יח, ז), \u0003ונאמר להלן: \"ערות אביו גלה\"\u0004 (ויקרא כ, כ, יא), \u0003מה באזהרה עשה הכתוב\u0004 את \u0003אמו שאינה אשת אביו\u0004 להיות לענין זה \u0003כאמו שהיא אשת אביו, אף\u0004 לגבי \u0003עונש עשה הכתוב\u0004 את \u0003אמו שאינה אשת אביו כאמו שהיא אשת אביו.\u0004","\u0003\"אמך הוא\"\u0004 (ויקרא כ, יח, ז), ללמד: \u0003משום אמו אתה מחייבו ואי\u0004 (אין) \u0003אתה מחייבו משום אשת אב,\u0004 עד כאן דברי הברייתא מתורת כהנים שהם לשיטת ר' יהודה.","ושואלים: \u0003ורבנן\u0004 החולקים על ר' יהודה, שאינם למדים \"ערות אביו גלה\" כמקור לגזירה שווה זו, כיצד מפרשים הם? ומשיבים: לדעתם \u0003\"ערות אביך\"\u0004 משמעו \u0003ממש\u0004 במשכב זכור.","ותוהים: \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 הלא ממה שנאמר \u0003\"ואת זכר\u0004 לא תשכב משכבי אשה תועבה היא\u0003\"\u0004 (ויקרא כ, כב) \u0003נפקא\u0004 \u0005[יוצא\u0006 לו \u0005]\u0006 האיסור! ומשיבים: \u0003לחייב עליו שתים\u0004 (בשני איסורים)","\u0003וכד\u0004ברי\u0003 רב יהודה.\u0004 ש\u0003אמר רב יהודה: גוי הבא על אביו\u0004 — \u0003חייב שתים,\u0004 וכן \u0003הבא על אחי אביו\u0004 — \u0003חייב שתים.\u0004","\u0003אמר רבא: מסתברא מילתא\u0004 \u0005[מסתברים הדברים\u0006\u0005]\u0006 של \u0003רב יהודה\u0004 שהיתה כוונתו \u0003בישראל,\u0004 שעשה דבר זה \u0003בשוגג. ו\u0004מה שאמר חייב שתים הריהו \u0003ב\u0004ענין \u0003קרבן\u0004 שמביא שני קרבנות חטאת. \u0003והאי דקאמר\u0004 \u0005[וזה שאמר]\u0006 \u0003גוי\u0004 — \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקיה\u0005]\u0006 \u0003הוא,\u0004 שלא רצה לתלות חטא כזה בישראל. \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר כי המדובר ב\u0003גוי\u0004 \u0003ממש,\u0004 הלא \u0003דינו\u0004 של גוי העובר על כך \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 — \u0003קטלא\u0004 \u0005[מיתה],\u0006 וכי \u0003בתרי קטלי קטלת ליה\u0004 \u0005[בשתי מיתות הורג אתה אותו]?!\u0006 אלא ודאי בישראל ובשוגג.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הבא על אביו\u0004 — \u0003חייב שתים, הבא על אחי אביו\u0004 — \u0003חייב שתים,\u0004 שנאמר \"ערות אחי אביך לא תגלה","\u0003\"\u0004(ויקרא כ, יד). \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שדבר זה הוא ש\u0003לא כ\u0004שיטת \u0003ר' יהודה,\u0004 שלדעתו אין איסור מיוחד למשכב זכור עם אביו, שהרי \"ערות אביך\" הוא מפרש באשת אביו, והאיסור במקרה מעין זה יהיה איסור משכב זכור בלבד.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שברייתא זו היא גם \u0003כ\u0004שיטת \u0003ר' יהודה.\u0004 ואולם \u0003מייתי לה\u0004 \u0005[מביא,\u0006 לומד הוא, \u0005אותה]\u0006 ב\u0003קל וחומר מאחי אביו. ומה אחי אביו דקורבה\u0004 \u0005[ש\u0006רק \u0005קירבה]\u0006 של \u0003אביו הוא\u0004 ואם בא עליו \u0003חייב שתים,\u0004 אם בא על \u0003אביו לא כל שכן? ו\u0004לענין זה","\u0003קמיפלגי בפלוגתא\u0004 \u0005[ונחלקו במחלוקת]\u0006 של \u0003אביי ורבא. מר סבר\u0004 \u0005[חכם זה,\u0006 בעל שיטה ראשונה בשם ר' יהודה, \u0005סבר]:\u0006 \u0003עונשין מן הדין,\u0004 אפשר ללמוד עונש על עבירה במידת קל וחומר, \u0003ומר סבר\u0004 \u0005[חכם זה,\u0006 שיטה שניה בשם ר' יהודה, \u0005סבור]\u0006 \u0003אין עונשין מן הדין.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003אזהרה\u0004 (איסור) \u0003לאשת אביו מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא להם]\u0006 הדבר \u0003מ\u0004הכתוב \u0003\"ערות אשת אביך לא תגלה\"\u0004 (ויקרא יח, ח).","ושואלים: \u0003ור' יהודה\u0004 מה למד הוא מפסוק זה, אחר שלמד כבר את הדין מכתוב אחר? ומשיבים: הפסוק \u0003ההוא מיבעי ליה\u0004 \u0005[נחוץ לו]\u0006 \u0003לאזהרה לאשת אביו לאחר\u0004 \u0003מיתה\u0004 של אביו, שאף שאביו מת מכל מקום אשתו עומדת באיסורה כלפיו, ושואלים:","\u0003ורבנן\u0004 \u0005[וחכמים\u0006\u0005],\u0006 מנין למדים הם הלכה זו? \u0003ההוא מסיפא דקרא נפקא\u0004 \u0005[זה מסופו של הכתוב יוצא\u0006\u0005,\u0006 נלמד\u0005],\u0006 שנאמר: \u0003\"ערות אביך היא\".\u0004","\u0003ור' יהודה\u0004 לדעתו \u0003ההוא\u0004 (אותה תוספת) \u0003מיבעי ליה\u0004 \u0005[נחוצה לו]\u0006 ללמד: \u0003משום\u0004 איסור \u0003אשת אב אתה מחייבו, ואי\u0004 (ואין) \u0003אתה מחייבו משום\u0004 איסור \u0003אשת איש.\u0004","ומקשים, \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו \u0005]:\u0006 \u0003הבא על אשת אב\u0004 — \u0003חייב עליה משום אשת אב ומשום אשת איש, בין בחיי אביו בין לאחר מיתת אביו, ולא פליג\u0004 \u0005[חלק\u0006\u0005]\u0006 \u0003ר' יהודה\u0004 על כך, וכיצד רוצה אתה לומר שבמקרה כזה יהיה חייב באיסור אשת אב בלבד?!","\u0003אמר אביי:\u0004 הוא \u0003פליג\u0004 \u0005[חולק]\u0006 \u0003בברייתא,\u0004 שאמנם במשנה לא הוזכר שר' יהודה חולק על כך, אבל במקור אחר מוצאים אנו שחלק.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003עונש ל\u0004בא על \u0003אשת אביו לאחר מיתה\u0004 של אביו \u0003מנא להו\u0004 \u0005[מנין להם\u0006\u0005]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' יהודה,\u0004 הוא \u0003מייתי לה\u0004 \u0005[מביא,\u0006 לומד, \u0005אותה\u0006 הלכה\u0005]\u0006 הנכללת \u0003בגזרה שוה. אלא רבנן מנא להו\u0004 \u0005[חכמים מנין להם\u0006\u0005]?\u0006","ומשיבים: \u0003אמרי\u0004 \u0005[\u0006יכולים הם \u0005לומר]\u0006 \u0003לך\u0004 כי הביטוי \u0003ההוא \"ערות אביו גלה\" דמפיק לה\u0004 \u0005[שמוציא אותו,\u0006 משתמש בו\u0005]\u0006 \u0003ר' יהודה\u0004 \u0003ל\u0004צורך \u0003גזירה שוה, מפקי ליה אינהו\u0004 \u0005[מוציאים הם אותו\u0006\u0005]\u0006 \u0003ל\u0004ענין \u0003עונש\u0004 לבא על \u0003אשת אביו לאחר מיתה\u0004 של אביו.","ושואלים: \u0003ורבנן, עונש ל\u0004בא על \u0003אמו שאינה אשת אביו מנא להו\u0004 \u0005[מנין להם\u0006\u0005]?\u0006 \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"אמך הוא\"\u0004 (ויקרא כ, ז), \u0003עשאה הכתוב לאמו שאינה אשת אביו כאמו שהיא אשת אביו.\u0004","שנינו במשנה לענין \u0003הבא על כלתו\u0004 שחייב משום כלתו ומשום אשת איש. ושואלים: \u0003ולחייב נמי\u0004 \u0005[שיהיה חייב גם\u0006\u0005]\u0006 \u0003משום אשת בנו,\u0004 שהרי נאמר \"ערות כלתך לא תגלה אשת בנך היא לא תגלה ערותה\u0003\"\u0004 (ויקרא כ, טו)! \u0003אמר אביי: פתח הכתוב בכלתו וסיים באשת בנו, לומר לך\u0004 שאין אלה שני עניינים נפרדים, אלא: \u0003זו היא כלתו זו היא אשת בנו,\u0004 ששתיהן אחת הן.","\u0003הבא על הזכור\u0004 (זכר), או \u0003על הבהמה,\u0004 או \u0003אשה המביאה את הבהמה\u0004 עליה — כל אלו דינם \u0003בסקילה.\u0004 וכן גם הבהמה בסקילה. ויש לשאול: \u0003אם אדם חטא\u0004 בכך, \u0003בהמה מה חטאה? אלא, לפי שבאה לאדם תקלה\u0004 (מכשול) \u0003על ידה, לפיכך אמר הכתוב תסקל,\u0004 שלא תגרום תקלה לאדם אחר באופן דומה. \u0003דבר אחר\u0004 טעם אחר בדבר: \u0003שלא תהא בהמה\u0004 זו \u0003עוברת בשוק\u0004 \u0003ויאמרו\u0004 הרואים אותה: \u0003זו היא\u0004 הבהמה \u0003שנסקל פלוני על ידה\u0004 ונמצא קיומה קלון לזכרו.","ובענין הבא על הזכר, מבררים: \u0003זכר מנא לן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 איסורו ועונשו — \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר: \"ואיש אשר ישכב את זכר משכבי אשה תועבה עשו שניהם מות יומתו דמיהם בם\" (ויקרא כ, יג), \u0003\"איש\"\u0004 משמע גדול, \u0003פרט לקטן, \"אשר ישכב את זכר\"\u0004 — \u0003בין\u0004 שהזכר \u0003גדול בין\u0004 שהזכר \u0003קטן, \"משכבי אשה\"\u0004 בלשון רבים, משמע שניים, מכאן למדנו בדרך אגב \u0003מגיד לך הכתוב ששני משכבות\u0004 יש \u0003באשה\u0004 כדרכה ושלא כדרכה, והבא עליה באיסור באחד מהם — נענש.","\u0003אמר ר' ישמעאל: הרי זה\u0004 מאותם המקראות אשר \u0003בא\u0004 לכאורה \u0003ללמד\u0004 לנושא אחר \u0003ונמצא למד\u0004 לעניינו.","\u0003\"מות יומתו\"\u0004 הכוונה היא \u0003בסקילה. אתה אומר\u0004 שמיתתם \u0003בסקילה, או\u0004 אולי \u0003אינו אלא באחת מכל מיתות\u0004 אחרות \u0003האמורות בתורה? נאמר כאן \"דמיהם בם\" ונאמר באוב וידעוני \"דמיהם בם\"\u0004 (ויקרא כ, כז), \u0003מה להלן\u0004 מפורש שענשם \u0003בסקילה אף כאן בסקילה.\u0004"],["\u0003עונש\u0004 לעבירה זו \u0003שמענו,\u0004 ואולם \u0003אזהרה\u0004 (איסור) \u0003מניין?\u0004 — \u0003תלמוד לומר: \"ואת זכר לא תשכב משכבי אשה תועבה הוא\"\u0004 (ויקרא יח, כג),","\u0003למדנו\u0004 מכאן \u0003אזהרה לשוכב. אזהרה לנשכב מניין?\u0004 — \u0003תלמוד לומר: \"\u0004ו\u0003לא יהיה קדש מבני ישראל\"\u0004 (דברים כג, יח) \u0003ואומר\u0004 כדי לבאר מהו עניינו של קדש: \u0003\"וגם קדש היה בארץ עשו ככל התועבת הגוים אשר הוריש ה'\u0004 מפני בני ישראל\u0003\"\u0004 (מלכים א' יד, כד), אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 ללמוד מהכתוב \"לא יהיה קדש\" אלא \u0003הרי הוא אומר \"ואת זכר לא תשכב משכבי אשה\" קרי ביה\u0004 \u0005[קרא בו,\u0006 בכתוב\u0005]\u0006 גם \u0003\"לא תשכב\"\u0004 (בבנין נפעל).","ועוד מבררים, משכב \u0003בהמה מנא לן\u0004 \u0005[מנין לנו\u0006\u0005]\u0006 האיסור והעונש בו? \u0003דתנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]\u0006 \"ואיש אשר יתן שכבתו בבהמה מות יומת ואת הבהמה תהרגו\" (ויקרא כ, טו), \u0003\"איש\"\u0004 — \u0003פרט לקטן, \"אשר יתן שכבתו בבהמה\"\u0004 לא פירט הכתוב, ומשמע \u0003בין גדולה בין קטנה,\u0004","\u0003\"מות יומת\"\u0004 — \u0003בסקילה. אתה אומר\u0004 שמיתתו \u0003בסקילה או\u0004 אולי \u0003אינו אלא באחת מכל מיתות האמורות בתורה? נאמר כאן\u0004 בבהמה: \u0003\"תהרגו\", ונאמר להלן\u0004 במסית: \u0003\"כי הרג תהרגנו...\u0004 וסקלתו באבנים ומת\u0003\"\u0004 (דברים יג י–יא), \u0003מה להלן\u0004 עונשו \u0003בסקילה, אף כאן\u0004 עונשו \u0003בסקילה.\u0004","\u0003למדנו עונש לשוכב,\u0004 ואולם \u0003עונש לנשכב\u0004 על ידי בהמה \u0003מנלן\u0004 \u0005[מנין לנו\u0006\u0005]?\u0006 — \u0003תלמוד לומר: \"כל שכב עם בהמה מות יומת\"\u0004 (שמות כב, יח), ו\u0003אם אינו ענין לשוכב,\u0004 שנאמר דינו במפורש בכתוב אחר, \u0003תניהו ענין לנשכב\u0004 לומר ש\"שוכב\" לאו דווקא, אלא כל משכב עם בהמה בכל אופן עונשו מיתה.","\u0003למדנו\u0004 איפוא \u0003עונש בין לשוכב בין לנשכב,\u0004 אך \u0003אזהרה מניין?\u0004 — \u0003תלמוד לומר: \"ובכל בהמה לא תתן שכבתך לטמאה בה\"\u0004 (ויקרא יח, כג).","\u0003למדנו\u0004 מכאן \u0003אזהרה לשוכב\u0004 עם בהמה, אזהרה \u0003לנשכב מניין?\u0004 — \u0003תלמוד לומר: \"לא יהיה קדש מבני ישראל\"\u0004 (דברים כג, יח), \u0003ואומר: \"וגם קדש היה בארץ\"\u0004 (מלכים א' יד, כד), שכל הנבעל בעילות מגונות כתועבות הגויים הוא הקרוי \"קדש\", ואסרה התורה במפורש לעשות כן, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: אינו צריך\u0004 להוכחה זו, אלא \u0003הרי הוא אומר \"לא תתן שכבתך\"\u0004 ואפשר להבין כך: \u0003\"לא תתן שכיבתך\".\u0004","בהמשך למדרשי ההלכה הללו מעלים את השאלה: מי ש\u0003בא על הזכור והביא עליו זכר\u0004 באותה שעה מה דינו?","\u0003אמר ר' אבהו: לדברי ר' ישמעאל חייב שתים, חדא\u0004 \u0005[אחת\u0006\u0005]\u0006 \u0003מ\"לא תשכב\" וחדא\u0004 \u0005[ואחת\u0006\u0005]\u0006 \u0003מ\"לא יהיה קדש\"\u0004 על היותו נבעל. ו\u0003לדברי ר' עקיבא אינו חייב אלא אחת,\u0004 כי \u0003\"לא תשכב\" \"לא תשכב\"\u0004 (בלשון נפעל) — \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003היא\u0004 ואין מענישים אדם על שני פרטי עבירה שעשה בהעלם אחת.","וכן \u0003הבא על הבהמה והביא בהמה עליו\u0004 בבת אחת, מהו? \u0003אמר ר' אבהו: לדברי ר' ישמעאל חייב שתים: חדא\u0004 \u0005[אחת\u0006\u0005]\u0006 \u0003מ\"לא תתן שכבתך\" וחדא\u0004 \u0005[אחת\u0006\u0005]\u0006 מ\u0003\"לא יהיה קדש\". לדברי ר' עקיבא אינו חייב אלא אחת, \"שכבתך\" ו\"שכיבתך\" חדא\u0004 \u0005[אחת\u0006\u0005]\u0006 \u0003היא.\u0004","ואילו \u0003אביי אמר: אפילו לדברי ר' ישמעאל נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003אינו חייב אלא אחת, דכי כתיב\u0004 \u0005[שכאשר נאמר\u0006\u0005]\u0006 \u0003\"לא יהיה קדש\"\u0004 — \u0003בגברי כתיב\u0004 \u0005[בגברים,\u0006 במשכב זכור, \u0005נאמר\u0006\u0005]\u0006 אבל לא במשכב בהמה.","ושואלים: \u0003אלא\u0004 לפי דעת אביי \u0003לר' ישמעאל אזהרה לנשכב\u0004 לבהמה \u0003מנא ליה\u0004 \u0005[מנין לו\u0006\u0005]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצאת לו\u0006\u0005]\u0006 אזהרה זו ממה שנאמר \u0003\"כל שכב עם בהמה מות יומת\"\u0004 (שמות כב, יח), \u0003אם אינו ענין לשוכב תניהו ענין לנשכב.\u0004","\u0003ואפקיה רחמנא\u0004 \u0005[והוציאה,\u0006 ביטאה \u0005התורה\u0006\u0005]\u0006 דין זה \u0003לנשכב בלשון שוכב,\u0004 ללמדנו: \u0003מה שוכב ענש והזהיר, אף נשכב ענש והזהיר.\u0004","\u0003הנרבע לזכר והנרבע לבהמה\u0004 בבת אחת מהו? \u0003אמר ר' אבהו: לדברי ר' עקיבא חייב שתים, חדא\u0004 \u0005[אחת\u0006\u0005]\u0006 \u0003מ\"לא תשכב\" וחדא\u0004 \u0005[ואחת\u0006\u0005]\u0006 \u0003מ\"לא תתן שכבתך\",\u0004 שבכל אחד יש איסור מיוחד. \u0003לדברי ר' ישמעאל אינו חייב אלא אחת,\u0004 כי \u0003אידי ואידי\u0004 \u0005[זו וזו\u0006\u0005]\u0006 שני האיסורים נובעים ממה שנאמר \u0003\"לא יהיה קדש\" הוא.\u0004","\u0003אביי אמר: אפילו לדברי ר' ישמעאל נמי\u0004 \u0005[גם כן\u0006\u0005]\u0006 \u0003חייב שתים,\u0004 שנאמר \u0003\"כל שכב עם בהמה מות יומת\", אם אינו ענין לשוכב,\u0004 שכן איסור זה כבר נלמד מ\"ובכל בהמה לא תתן שכבתך\u0003\"\u0004 (ויקרא יח, כג), \u0003תניהו ענין לנשכב. ואפקיה רחמנא\u0004 \u0005[והוציאה,\u0006 ביטאה, \u0005התורה\u0006\u0005]\u0006 את הדין \u0003לנשכב בלשון שוכב\u0004 ללמדנו: \u0003מה שוכב ענש והזהיר\u0004 — \u0003אף נשכב ענש והזהיר.\u0004","\u0003אבל הבא על הזכור והביא זכר עליו\u0004 וכן \u0003הבא על הבהמה והביא בהמה עליו\u0004 כולם יחד, \u0003בין לר' אבהו בין לאביי\u0004 הרי \u0003ל\u0004שיטת \u0003ר' ישמעאל\u0004 \u0003חייב שלש,\u0004 שיש גם איסור \"לא יהיה קדש\", \u0003ל\u0004שיטת \u0003ר' עקיבא חייב\u0004 רק \u0003שתים.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006\u0005]:\u0006 \u0003זכור לא עשו בו קטן כגדול, בהמה עשו בה קטנה כגדולה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ש\u0003לא עשו בו קטן כגדול? אמר רב:\u0004 כוונתו, ש\u0003לא עשו ביאת פחות מבן תשע שנים כ\u0004ביאתו על ילד שהוא \u0003בן תשע שנים\u0004 ומעלה, שמתשע שנים ומעלה ביאתו ביאה. \u0003ושמואל אמר: לא עשו ביאת\u0004 ילד \u0003פחות מבן שלש שנים כבן שלש שנים.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה, באיזה\u0006 עקרון, \u0005נחלקו\u0006\u0005],\u0006 ומה יסוד המחלוקת? ומסבירים, \u0003רב סבר: כל דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003בשוכב\u0004 — \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003בנשכב,\u0004 \u0003וכל דליתיה\u0004 \u0005[שאינו]\u0006 \u0003בשוכב ליתיה\u0004 \u0005[אינו]\u0006 \u0003בנשכב,\u0004 וכיון שבשוכב אין חיוב בפחות מבן תשע, שביאת ילד פחות מבן תשע אינה נחשבת ביאה לכל דבר, הרי אף אם נשכב ילד פחות מבן תשע אין מתחייב בו בועלו.","\u0003ושמואל סבר: \"משכבי אשה\" כתיב\u0004 \u0005[נאמר\u0006\u0005]\u0006 לומר שדינו של זכר הנבעל, כאשה, מה אשה נחשבת ראויה לביאה מגיל שלש שנים — אף בזכר כן, ולכן לדעתו הבא על הזכר שהוא למעלה מבן שלש שנים — חייב.","\u0003תניא כוותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב: זכר בן תשע שנים ויום אחד,\u0004 ומברייתא זו למדים אנו שרק מבן תשע שנים ומעלה הוא \"זכר\" ובדרך אגב מתברר שעל שכזה מתחייבים במשכב זכר."],["\u0003הבא על הבהמה, בין\u0004 שבא עליה \u0003כדרכה בין שלא כדרכה, ו\u0004כן \u0003האשה המביאה את הבהמה עליה בין כדרכה בין שלא כדרכה\u0004 — \u0003חייב.\u0004","\u0003דרש רב נחמן בר רב חסדא: באשה\u0004 יש \u0003שני משכבות,\u0004 כדרכה ושלא כדרכה, וחייב על שניהם אם נרבעה לבהמה, ואילו \u0003בבהמה משכב אחד,\u0004 שחייב כדרכה בלבד.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה\u0006 על דעה זו\u0005]\u0006 \u0003רב פפא: אדרבה, אשה דאורחה\u0004 \u0005[שדרכה]\u0006 \u0003היא\u0004 ששוכבים עמה, סברה היא כי על \u0003משכב\u0004 כדרכה \u0003מיחייב\u0004 \u0005[תתחייב\u0006\u0005],\u0006 \u0003אמידעם אחרינא\u0004 \u0005[על דבר אחר]\u0006 \u0003לא מחייב\u0004 \u0005[תתחייב]\u0006 האשה, ואילו \u0003בהמה דלאו אורחא\u0004 \u0005[שלא דרכה]\u0006 \u0003היא\u0004 להשכב לאדם, וכל עצם בעילתה הריהי שלא כדרכה \u0003לחייב עלה\u0004 \u0005[תתחייב עליה]\u0006 אם כן \u0003על כל נקב ונקב,\u0004 בין כדרכה בין שלא כדרכה!","ומעירים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003לא כתרוייהו\u0004 \u0005[כ\u0006שיטת \u0005שניהם\u0006\u0005]:\u0006 \u0003זכר בן תשע שנים ויום אחד הבא על הבהמה, בין כדרכה בין שלא כדרכה, והאשה המביאה את הבהמה עליה, בין כדרכה בין שלא כדרכה\u0004 — \u0003חייב.\u0004 משמע שאין לחלק בין אשה ובהמה, ובין כדרכה בין שלא כדרכה חייבים בשניהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: המערה\u0004 (שאינו בועל בעילה גמורה אלא רק מתחיל בה) \u0003בזכור מהו\u0004 הדין?","האם לענין זה גם כן דין העראה כדין ביאה ממש? אמר לו: \u0003המערה בזכור\u0004 — מה שאלה היא?! הלא \u0003\"משכבי אשה\"\u0004 (ויקרא יח, כב) \u0003כתיב ביה\u0004 \u0005[נאמר בו\u0006\u0005],\u0006 שכדיני אשה כן דין השוכב עם זכר, ובאשה העראה נידונה כביאה ממש. \u0003אלא המערה בבהמה מהו?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם\u0004 העראה שנאמרה בכתוב \u0003אינו ענין להעראה דכתיבא גבי\u0004 \u0005[שנאמרה אצל\u0006\u0005]\u0006 \u0003אחות אביו ואחות אמו\u0004 (שנאמר בהן \"כי את שארו הערה\". ויקרא כ, יט) \u0003דלא צריכא\u0004 \u0005[שאינה נצרכת\u0006\u0005]\u0006 ללמדנו לאותו ענין מאומה, \u0003דהא איתקש\u0004 \u0005[שהרי הושוותה]\u0006 בכתוב \u0003ל\u0004דין \u0003העראה\u0004 האמור ב\u0003נדה,\u0004 וכל עריות האמורות שם הושוו זו לזו, אם כן \u0003תניהו ענין להעראה\u0004 ב\u0003בהמה.\u0004 ונלמד כי גם בהעראה בבהמה מתקיים האיסור.","ושואלים: \u0003מכדי\u0004 \u0005[הרי\u0006\u0005]\u0006 \u0003בהמה מחייבי מיתות בית דין היא, למה לי\u0004 (מדוע) \u0003דכתיב\u0004 \u0005[שתיאמר]\u0006 \u0003להעראה דידה\u0004 \u0005[שלה\u0006\u0005]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003חייבי כריתות?!\u0004 שהרי כפי שביררנו למדים דבר זה מאחות אביו שדינה רק בכרת, \u0003לכתביה\u0004 \u0005[שיכתוב אותה\u0006\u0005]\u0006 את ההלכה לענין העראה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003חייבי מיתות בית דין, וליגמור\u0004 \u0005[וילמד\u0006\u0005]\u0006 \u0003חייבי מיתות בית דין מחייבי מיתות בית דין\u0004 ולא מדבר רחוק כל כך כאחות אביו שדינה בכרת בלבד!","ומשיבים: \u0003הואיל וכוליה קרא לדרשא הוא דאתי\u0004 \u0005[וכל המקרא\u0006 כולו \u0005לדרשה הוא שבא],\u0006 שעיקר הדין נכתב במקום אחר בפרשה אחרת, \u0003כתיבא נמי מילתא דדרשא\u0004 \u0005[כתוב גם כן דבר של דרשה\u0006\u0005]\u0006 אף שלא נכתב במקום הראוי והשייך לו.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו\u0006\u0005]\u0006 \u0003רב אחדבוי בר אמי מרב ששת: המערה בעצמו מהו\u0004 האם חייב הוא משום משכב זכר בזה? \u0003אמר ליה: קבסתן\u0004 \u0005[אתה מגעיל אותי\u0006\u0005]\u0006 (גאונים) בשאלתך, שהרי דבר זה לא יתכן.","\u0003אמר רב אשי: מאי תיבעי\u0004 \u0005[מה נשאלת]\u0006 \u0003לך\u0004 פה השאלה? שבעצם אין זו שאלה עצמאית כלל אלא תלויה בבעיה אחרת: אם היה זה \u0003בקושי,\u0004 כלומר, שהיה אברו מוקשה \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה\u0006 אפשרות מעשית\u0005],\u0006 אי אפשר לעשות כן. \u0003כי משכחת לה\u0004 \u0005[כאשר אתה מוצא אותה\u0006\u0005]\u0006 אפשרות מעשית הרי זה \u0003במשמש\u0004 בשעה שאברו \u0003מת\u0004 ואינו מוקשה. והרי זה תלוי במחלוקת, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006\u0005]\u0006 שה\u0003משמש מת בעריות פטור\u0004 לפי שאין זו ביאה כלל, \u0003הכא\u0004 \u0005[כאן\u0006\u0005]\u0006 גם כן \u0003פטור, ולמאן דאמר\u0004 \u0005[ול\u0006 דעת \u0005מי שאומר\u0006\u0005]\u0006 ש\u0003חייב, הכא מיחייב תרתי\u0004 \u0005[כאן חייב שתים\u0006\u0005]\u0006 לר' ישמעאל, \u0003מיחייב\u0004 \u0005[חייב]\u0006 משום \u0003שוכב\u0004 עם זכר \u0003ומיחייב\u0004 \u0005[וחייב]\u0006 משום \u0003נשכב\u0004 לזכר\u0005.\u0006","\u0003בעו מיניה\u0004 \u0005[שאלו אותו\u0006\u0005]\u0006 את \u0003רב ששת: גוי הבא על הבהמה מהו,\u0004 כלומר, האם הורגים בהמה זו? וצדדי השאלה: האם את שני הנימוקים, \u0003תקלה וקלון\u0004 יחד \u0003בעינן\u0004 \u0005[צריכים אנו\u0006\u0005]\u0006 שיהיו בבהמה זו, \u0003והכא\u0004 \u0005[וכאן\u0006\u0005]\u0006 אמנם \u0003תקלה איכא\u0004 \u0005[יש\u0006\u0005]\u0006 שגרמה שנהרג אדם בגללה, אבל \u0003קלון ליכא\u0004 \u0005[אין כאן\u0006\u0005],\u0006 שכן איננו אחראים לקלונו של אותו גוי. \u0003או דילמא\u0004 \u0005[שמא]\u0006 אומרים אנו שיש לעשות כן מפני ה\u0003תקלה אף על פי שאין קלון?\u0004","\u0003אמר רב ששת:\u0004 כבר \u0003תניתוה\u0004 \u0005[למדתם אותה\u0006\u0005]\u0006 את תשובת שאלה זו, שכן שנינו: \u0003מה אילנות שאין אוכלין ואין שותין ואין מריחין,\u0004 בכל זאת, אם נעבדה בהם עבודה זרה, \u0003אמרה תורה\u0004 ביחס אליהם: \u0003השחת שרוף וכלה\u0004 אותה (ראה דברים פרק ז' ופרק יב), וטעם הדבר: \u0003הואיל ובא לאדם תקלה על ידן,\u0004 אדם \u0003המתעה את חבירו מדרכי חיים לדרכי מיתה על אחת כמה וכמה\u0004 שיהא חייב כליה, ולענייננו נלמד שכל דבר ששימש לעבירה והיתה בו תקלת מיתה מכלים אותו.","והקשו על רב ששת: \u0003אלא מעתה, גוי המשתחוה לבהמתו תיתסר, ומקטלא\u0004 \u0005[שתיאסר, ו\u0006גם יצטרכו \u0005להרוג\u0006 אותה\u0005]\u0006 לפי עקרון זה! והשיב: \u0003מי איכא מידי\u0004 \u0005[האם\u0006 יש דבר] ש\u0003לישראל לא אסר\u0004 \u0005[נאסר\u0006 הדבר\u0005]\u0006 \u0003ולגוי אסר\u0004 \u0005[נאסר\u0006\u0005]?\u0006 והרי הלכה היא שהמשתחוה לבהמה לא אסרה!","על עצם הלכה זו מקשים: אם כן ש\u0003ישראל גופיה ליתסר\u0004 \u0005[עצמו\u0006 באמת \u0005תיאסר\u0006\u0005]\u0006 בהמתו אם עובד אותה, \u0003מידי דהוה\u0004 \u0005[כפי שהוא]\u0006 ב\u0003רביעה\u0004 שהבהמה נהרגת! \u0003אמר אביי:\u0004 יש להבחין בין המקרים: \u0003זה\u0004 שרבע את הבהמה — \u0003קלונו מרובה,\u0004 כי דבר מבוזה מאד עשה, \u0003וזה\u0004 שעבד לעבודה זרה — \u0003קלונו מועט,\u0004 ואם תשאר הבהמה בחיים לא יבוזה כל כך.","ומקשים: \u0003והרי אילנות\u0004 של עבודה זרה ש\u0003אין קלונן מרובה, ואמרה תורה\u0004 ביחס אליהם: \u0003השחת שרוף וכלה!\u0004 ומשיבים: \u0003בבעלי חיים קאמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003דחס רחמנא עלייהו\u0004 \u0005[שחסה התורה עליהם\u0006\u0005].\u0006 ולכן אם אין בכך קלון מרובה לאדם, אין משמידים אותם.","\u0003רבא אמר\u0004 טעם אחר: יש להבדיל בין עובד בהמתו לרובעה, שכן \u0003אמרה תורה: בהמה נהנית מעבירה\u0004 על כן \u0003תיהרג.\u0004","ומקשים: \u0003והרי אילנות,\u0004 ש\u0003אין\u0004 הם \u0003נהנין מעבירה, ו\u0004בכל זאת \u0003אמרה תורה\u0004 ביחס אליהם: \u0003השחת שרוף וכלה!\u0004 ומשיבים: \u0003בבעלי חיים קאמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003דחס רחמנא עלייהו\u0004 \u0005[שחסה התורה עליהם\u0006\u0005],\u0006 ולכן יש להוסיף טעם יתר אם באים להרגם. השאלה ביחס לבהמה שנרבעה לגוי לא נפתרה איפוא ולכן מנסים להביא ראיה לדבר ממה ששנינו במקור אחר.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003דבר אחר, שלא תהא בהמה עוברת בשוק ויאמרו: זו היא שנסקל פלוני על ידה. מאי לאו\u0004 \u0005[האם לא\u0006\u0005]\u0006"],["\u0003מדסיפא\u0004 \u0005[מ\u0006תוך \u0005שסופה\u0006\u0005]\u0006 של משנתנו יש בו שני טעמים — \u0003תקלה וקלון, רישא\u0004 \u0005[התחלתה\u0006\u0005],\u0006 הטעם הראשון שבשלו סוקלים הוא בוודאי \u0003תקלה בלא קלון, והיכי דמי\u0004 \u0005[וכיצד הוא\u0006\u0005]\u0006 תקלה בלא קלון — כאשר \u0003גוי בא על הבהמה\u0004 שכן תקלה יש במקרה כזה, אך קלונו אינו מענייננו כנזכר, והרי תשובה לשאלתנו.","ודוחים: \u0003לא, סיפא\u0004 \u0005[בסוף\u0006 מדובר\u0005]\u0006 ב\u0003תקלה וקלון, רישא\u0004 \u0005[בתחילה\u0006\u0005]\u0006 \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו\u0006\u0005]:\u0006 ש\u0003אפילו\u0004 תקלת \u0003קלון\u0004 בלבד \u0003בלא תקלה\u0004 של מיתה \u0003נמי מחייבי\u0004 \u0005[גם כן חייבים\u0006\u0005]\u0006 להורגם. \u0003והיכי דמי\u0004 \u0005[וכיצד הוא\u0006\u0005]\u0006 קלון בלא תקלה — \u0003ישראל הבא על הבהמה בשוגג, וכדבעי\u0004 \u0005[וכפי ששאל\u0006\u0005]\u0006 \u0003רב המנונא\u0004 באותו ענין.","\u0003דבעי\u0004 \u0005[ששאל\u0006\u0005]\u0006 \u0003רב המנונא: ישראל הבא על הבהמה בשוגג מהו,\u0004 האם סוקלים את הבהמה או לא? האם \u0003תקלה וקלון בעינן\u0004 \u0005[צריכים אנו\u0006\u0005],\u0006 \u0003והכא\u0004 \u0005[וכאן\u0006\u0005]\u0006 \u0003קלון איכא\u0004 \u0005[יש]\u0006 אך \u0003תקלה\u0004 של מיתה \u0003ליכא\u0004 \u0005[אין\u0006\u0005],\u0006 \u0003או דילמא\u0004 \u0005[שמא\u0006\u0005]\u0006 די ב\u0003קלון\u0004 — \u0003אף על פי שאין תקלה?\u0004","\u0003אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו: \u0003בת שלש שנים ויום אחד מתקדשת בביאה,\u0004 כי ביאתה נחשבת לביאה גמורה. וכן \u0003אם בא עליה יבם\u0004 — \u0003קנאה\u0004 להיות אשתו, \u0003וחייבין עליה\u0004 (אם היתה מקודשת לאחר) \u0003משום אשת איש,\u0004","\u0003ומטמאה את בועלה\u0004 אם היתה נדה \u0003לטמא משכב תחתון כעליון,\u0004 שתינוקת קטנה פחות מבת שלוש מטמאה את הבועל אותה בנדתה רק בטומאת מגע נדה ואילו זו מטמאה את בועלה להיות כמוה. \u0003ניסת\u0004 (נישאת) \u0003לכהן\u0004 — \u0003אוכלת בתרומה\u0004 כאשתו ממש, \u0003בא עליה אחד מן הפסולים\u0004 (גוי, חלל, נתין, או ממזר) — \u0003פסלה מן הכהונה,\u0004","\u0003ואם בא עליה אחד\u0004 \u0003מכל העריות האמורות בתורה\u0004 — \u0003מומתין על ידה, והיא פטורה.\u0004","ונדייק לענייננו: \u0003אחד מכל עריות\u0004 — \u0003ואפילו בהמה, והא הכא\u0004 \u0005[והרי כאן],\u0006 ש\u0003קלון איכא\u0004 \u0005[יש],\u0006 \u0003תקלה ליכא\u0004 \u0005[אין],\u0006 שהרי אותה קטנה היא כשוגגת ואין ממיתים אותה, \u0003וקתני\u0004 \u0005[ושנינו]:\u0006 \u0003מומתין על ידה!\u0004","ודוחים: \u0003כיון\u0004 שהילדה \u0003מזידה היא\u0004 בעבירה זו, הרי \u0003תקלה נמי איכא\u0004 \u0005[גם כן יש],\u0006 לפי הדין שהילדה עצמה אינה נענשת, \u0003ורחמנא הוא דחס עלה\u0004 \u0005[והתורה היא שחסה עליה]\u0006 מפני קטנותה, שאין בה דעת שלימה. ואולם, \u0003עלה דידה\u0004 \u0005[עליה עצמה]\u0006 \u0003חס\u0004 הכתוב, אבל על ה\u0003בהמה לא חס.\u0004 ומכל מקום אין מכאן תשובה לשאלה.","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו: \u0003בן תשע שנים ויום אחד הבא על יבמתו\u0004 — \u0003קנאה, ואינו נותן גט\u0004 אם רוצה הוא לגרשה \u0003עד שיגדיל,\u0004 שקטן אינו יכול לתת גט. \u0003ומטמא כנדה\u0004 אם בא על נדה \u0003לטמא משכב תחתון כעליון.\u0004","ואם בא על בת כהן \u0003פוסל\u0004 אותה מלאכול תרומה. אבל אם היה הוא כהן ובעל אשה לשם קידושין \u0003אינו מאכיל\u0004 אותה בתרומה. \u0003ופוסל את הבהמה מעל גבי המזבח\u0004 אם בא עליה, שהנרבע פסול לקרבנות, \u0003ונסקלת על ידו. ואם בא על אחת מכל העריות האמורות בתורה\u0004 — \u0003מומתים על ידו.\u0004","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 שבא זה על הבהמה, \u0003קלון איכא\u0004 \u0005[יש],\u0006 \u0003תקלה ליכא\u0004 \u0005[אין],\u0006 \u0003וקתני\u0004 \u0005[והרי שנינו]:\u0006 \u0003נסקלת על ידו,\u0004 משמע שדי בקלון על מנת להרוג את הבהמה!","ודוחים: גם מכאן אין להביא ראיה, \u0003כיון\u0004 ש\u0003מזיד הוא, תקלה נמי איכא\u0004 \u0005[גם כן יש].\u0006 אלא \u0003רחמנא הוא דחס עילויה\u0004 \u0005[התורה היא שחסה עליו]\u0006 שלא לחייבו, לפי שאינו בר דעת גמור, ואולם \u0003עליה דידיה\u0004 \u0005[עליו עצמו]\u0006 \u0003חס רחמנא\u0004 \u0005[חסה התורה],\u0006 אבל על ה\u0003בהמה לא חס רחמנא\u0004 \u0005[חסה התורה].\u0006 אך לגבי מקרה שבוודאי אין בו משום תקלה לא נוכל ללמוד מהלכה זו.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003דבר אחר\u0004 ששנינו במשנתנו: \u0003שלא תהא בהמה עוברת בשוק ויאמרו: זו היא שנסקל פלוני על ידה. מאי לאו\u0004 \u0005[האם לא]\u0006 תאמר \u0003מדסיפא\u0004 \u0005[מכיון שבסופה]\u0006 של המשנה מדובר ב\u0003תקלה\u0004 של מיתה \u0003וקלון,\u0004 ו\"תקלה\" האמורה במשנה היא בושתו של האיש שמתבזה בגלל עבירה זו, מכאן ודאי שב\u0003רישא\u0004 \u0005[בתחילתה]\u0006 מדובר ב\u0003קלון בלא תקלה. והיכי דמי\u0004 \u0005[וכיצד\u0006 יכול הדבר \u0005להיות]?\u0006 — \u0003ישראל הבא על הבהמה בשוגג,\u0004 ומכאן שדי בקלון על מנת להרוג את הבהמה.","ודוחים: \u0003לא, סיפא\u0004 \u0005[סופה]\u0006 מדובר ב\u0003תקלה וקלון, רישא\u0004 \u0005[תחילתה]\u0006 מדובר ב\u0003תקלה בלא קלון. והיכי דמי\u0004 \u0005[וכיצד\u0006 יכול הדבר \u0005להיות]?\u0006 — כגון \u0003גוי הבא על הבהמה, וכדבעו מיניה\u0004 \u0005[וכפי ששאלו אותו]\u0006 את \u0003רב ששת,\u0004 ואין איפוא פתרון לשאלה. ואין למצוא תשובה גמורה וסופית מן המשנה אף לא לאחת מן השאלות.","\u0003המגדף\u0004 (מקלל את ה') \u0003אינו חייב עד שיפרש השם\u0004 עצמו ויקללנו. \u0003אמר ר' יהושע בן קרחה:\u0004"],["\u0003בכל יום\u0004 שעוסקים בדין זה \u0003דנין את העדים,\u0004 כלומר, שואלים ומתדיינים עם העדים \u0003בכינוי,\u0004 כדי שלא תשמע קללת השם אלא בכינוי דברים, בלשון \u0003\"יכה יוסי את יוסי\",\u0004 שיוסי יש בו ארבע אותיות כמו שם ה'.","\u0003נגמר הדין\u0004 והסכימו שדברי העדות אמת הם, והסכימו לחייבם מיתה — \u0003לא הורגין בכינוי,\u0004 כלומר, על ידי עדות זו, שמעולם לא שמעו מפיהם כיצד בדיוק אמר, \u0003אלא מוציאין כל אדם\u0004 שאינו חייב להיות שם \u0003לחוץ,\u0004 שלא תשמע הקללה ברבים, ו\u0003שואלין\u0004 הדיינים \u0003את הגדול שביניהן,\u0004 בין העדים, \u0003ואומר לו: \"אמור מה ששמעת בפירוש\"\u0004 (בדיוק), \u0003והוא אומר\u0004 להם כפי ששמע בדיוק. \u0003והדיינין עומדין על רגליהן וקורעין\u0004 קרע (כעין אבילות על חילול כבוד ה'), והוא קרע ש\u0003לא מאחין\u0004 אותו איחוי גמור לעולם.","\u0003וה\u0004עד ה\u0003שני אומר: אף אני\u0004 שמעתי \u0003כמוהו\u0004 ואינו חוזר על הקללה במפורש, \u0003והשלישי אומר: אף אני כמוהו,\u0004 שעל ידי כך מצמצמים את החזרה על דברי הנאצה עד להכרחי בלבד.","ועוד בענין המגדף \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]\u0006 שהמגדף אינו חייב \u0003עד שיברך\u0004 (בלשון סגי נהור, כלומר, יקלל) \u0003שם\u0004 אחד של ה' \u0003בשם\u0004 שני, כגון \"יכה שם פלוני את שם פלוני\".","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלו]\u0006 בענין המקלל? \u0003אמר שמואל:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונוקב שם\u0004 ה' מות יומת רגום ירגמו בו כל העדה כגר כאזרח \u0003בנקבו שם יומת\"\u0004 (ויקרא כד, טז), ומן החזרה \"ונקב שם\" \"בנקבו שם\" למדים שהוא מקלל שם בשם.","ומסבירים: \u0003ממאי דהאי נוקב לישנא דברוכי\u0004 \u0005[מנין שנוקב זה לשון ברכה]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבלעם שנשלח על ידי בלק לקלל: \u0003\"מה אקב לא קבה אל\"\u0004 (במדבר כג, ח). \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו,\u0006 הצווי שלא לעשות כן, \u0005מכאן],\u0006 שנאמר \u0003\"אלהים לא תקלל\"\u0004 (שמות כב, כז).","ומקשים: \u0003ואימא\u0004 \u0005[ושמא תאמר]\u0006 אין פירוש \"נוקב\" מקלל אלא \u0003מיברז\u0004 \u0005[לעשות נקב]\u0006 \u0003הוא\u0004 משמעות לשון זו, \u0003דכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"ויקב חר בדלתו\"\u0004 (מלכים ב' יב, י), ויהא פירושו שאסור לעשות נקב והשחתה במקום שכתוב עליו שם. \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו,\u0006 והציווי על איסורו, \u0005מכאן],\u0006 ממה שנאמר: \u0003\"ואבדתם את שמם\u0004 מן המקום ההוא. \u0003לא תעשון כן לה' אלהיכם\"\u0004 (דברים יב, ג–ד)?","ודוחים: \u0003בעינא\u0004 \u0005[צריכים אנו]\u0006 \u0003שם בשם, וליכא\u0004 \u0005[ואין]\u0006 אפשרות לעשות זאת על ידי נקיבה.","ומקשים: ומדוע לא, \u0003ואימא דמנח\u0004 \u0005[ואמור שמניח]\u0006 \u0003שני שמות אהדדי\u0004 \u0005[זה על זה],\u0006 \u0003ובזע להו\u0004 \u0005[וקורע אותם]!\u0006 ודוחים: \u0003ההוא נוקב וחוזר ונוקב הוא,\u0004 אבל אין זה שם שנוקב את השם האחד על ידי רעהו. ומקשים: \u0003ואימא דחייק\u0004 \u0005[ואמור ש\u0006הוא \u0005חוקק]\u0006 \u0003שם\u0004 אחד \u0003אפומא דסכינא\u0004 \u0005[על פי הסכין]\u0006 \u0003ובזע\u0004 \u0005[ו\u0006הוא \u0005חותך]\u0006 \u0003בה,\u0004 בסכין זו, שם אחר! ודוחים: גם במקרה שכזה לא השם הוא העושה זאת, אלא \u0003ההוא חורפא דסכינא\u0004 \u0005[חוד הסכין]\u0006 \u0003הוא דקא בזע\u0004 \u0005[שחותך],\u0006 ולא השם עצמו.","ושואלים עוד: מנין ש\"נוקב\" לשון קללה הוא, \u0003אימא\u0004 \u0005[אמור]\u0006 שמשמעו: \u0003פרושי שמיה\u0004 \u0005[פירוש השם],\u0006 כלומר, אמירת השם במפורש ככתבו \u0003הוא,\u0004 והיכן מצאנו שימוש לשון זה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקח משה ואהרן את האנשים האלה אשר נקבו בשמות\"\u0004 (במדבר א, יז). הרי של\"נקוב\" משמעו לפרש בשם, \u0003ואזהרתיה מהכא\u0004 \u0005[ואזהרתו\u0006 תהיה \u0005מכאן],\u0006 ממה שנאמר: \u0003\"את ה' אלהיך תירא\u0004 ואותו תעבוד ובשמו תשבע","\u0003\"\u0004(דברים ו, יג), והרי זו אזהרה שאסור לפרש בשמו שלא לצורך! ודוחים: \u0003חדא, דבעינא\u0004 \u0005[\u0006טעם \u0005אחד, שאנו צריכים]\u0006 שיהיה \u0003שם בשם, וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 \u0003ועוד: הויא ליה\u0004 \u0005[הרי הוא]\u0006 למד מכאן רק \u0003אזהרת עשה\u0004 מהפסוק \"את ה' אלהיך תירא\", שאין אזהרה אלא למצות עשה של יראה, \u0003ואזהרה\u0004 על מצוות \u0003עשה לא שמה אזהרה\u0004 שיש עליה עונש בידי אדם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לשתי השאלות ששאלנו, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויקב\u0004 בן אשה הישראלית את השם \u0003ויקלל\"\u0004 (ויקרא כד, יא), \u0003למימרא\u0004 \u0005[לומר לנו]\u0006 ש\u0003נוקב קללה הוא.\u0004","ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 אינו חייב אלא \u0003עד דעבד תרוייהו\u0004 \u0005[שיעשה\u0006 את \u0005שניהם],\u0006 גם יקוב (יהא פירושו מה שיהיה) וגם יקלל? ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול \u0005לעלות על דעתך],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 \u0003\"הוצא את המקלל...\u0004 ורגמו אותו\u0003\"\u0004 (ויקרא כד, יד), \u0003ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"הוצא את הנקב והמקלל\", שמע מינה חדא\u0004 \u0005[למד מכאן\u0006 שעבירה \u0005אחת]\u0006 \u0003היא.\u0004","בביאורן של הלכות אלה מביאים מדרש הלכה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הכתוב \"איש איש כי יקלל אלהיו ונשא חטאו\u0003\"\u0004 (ויקרא כד טו), נאמר \u0003\"איש\", מה תלמוד לומר: \"איש איש\"\u0004 — \u0003לרבות את הגוים, שמוזהרין על ברכת\u0004 (קללת) \u0003השם כישראל, ואינן נהרגין\u0004 על עבירה זו \u0003אלא בסייף,\u0004 לפי \u0003שכל מיתה האמורה בבני נח אינה אלא בסייף.\u0004","ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006הלכה \u0005זו מכאן\u0006 היא \u0005יוצאת,\u0006 נלמדת\u0005]?\u0006 והרי \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 ממקור זה היא \u0005יוצאת,\u0006 נלמדת\u0005],\u0006 ששנינו במדרש שיובא להלן בהרחבה \u0003\"ה' \"\u0004— \u0003זו ברכת השם!\u0004","ומשיבים, \u0003אמר ר' יצחק נפחא: לא נצרכא\u0004 (נצרכה) תוספת כתוב זה \u0003אלא לרבותא\u0004 \u0005[לרבות]\u0006 את \u0003הכינויין,\u0004 שחייבים לא רק על קללת השם המפורש אלא גם על כל אחד מן השמות האחרים שהם כינויים לו. \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' מאיר.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 זה שנאמר \u0003\"איש איש כי יקלל אלהיו ונשא חטאו\", מה תלמוד לומר? והלא כבר נאמר \"ונקב שם ה' מות יומת\u0004 רגום ירגמו בו כל העדה כגר כאזרח בנקבו שם יומת\u0003\"\u0004 (ויקרא כד טז), אלא \u0003לפי שנאמר \"ונקב שם\u0004 ה' \u0003מות יומת\", יכול לא יהא חייב אלא על\u0004 קללת ה\u0003שם המיוחד\u0004 (ה') \u0003בלבד, מניין לרבות כל הכינויין\u0004 שהמקלל חייב עליהם? — \u0003תלמוד לומר: \"איש כי יקלל אלהיו\"\u0004 — \u0003מכל מקום,\u0004 בכל כינוי חייב. אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים:\u0004 אינו כן, אלא \u0003על\u0004 קללתו את ה\u0003שם המיוחד\u0004 דינו \u0003במיתה, ועל הכינויין\u0004 שהוא מקלל, הריהו \u0003באזהרה\u0004 בלבד, ולוקה.","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו שאין חיוב בכינויים לגוים על \u0003ר' מיישא.\u0004 ש\u0003אמר ר' מיישא: בן נח שבירך\u0004 (קלל) \u0003את השם בכינויים,\u0004 אף \u0003ל\u0004דעת \u0003רבנן חייב\u0004 מיתה.","\u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כגר כאזרח\",\u0004 ומשם למדים: כי רק \u0003גר ואזרח\u0004 שהם בעם ישראל \u0003הוא דבעינן\u0004 \u0005[שצריכים אנו]\u0006 כדי לעונשם מיתה \u0003בנקבו שם,\u0004 שיהא משום \"ונוקב שם ה' \" המיוחד, \u0003אבל גוי\u0004 — דינו במיתה \u0003אפילו\u0004 אם קילל רק \u0003בכינוי.\u0004","ושואלים: \u0003ו\u0004לשיטה זו של \u0003ר' מאיר, האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"כגר כאזרח\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומסבירים, לדעתו כך פירושו: \u0003גר ואזרח\u0004 בישראל נידונים על עבירה זו \u0003בסקילה, אבל גוי\u0004 העושה זאת דינו \u0003בסייף.\u0004 והצורך במיעוט זה של \"כגר כאזרח\" כי \u0003סלקא דעתך אמינא\u0004 \u0005[עולה על דעתך לומר]:\u0006 \u0003הואיל ואיתרבו איתרבו\u0004 \u0005[והתרבו מפסוק זה\u0006 שיהא דינם כישראל, \u0005התרבו\u0006 לכל\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","ושואלים: \u0003ו\u0004לשיטת \u0003ר' יצחק נפחא, אליבא דרבנן\u0004 \u0005[על פי שיטת חכמים]\u0006 שאינם מחייבים, לדעתו, בקללת כינוי לא את הישראלים ולא את הגוים, \u0003האי\u0004 \u0005[אותו]\u0006 כתוב \u0003\"כגר כאזרח\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים, לדעה זו כך הפירוש: \u0003גר ואזרח הוא דבעינן\u0004 \u0005[שצריכים אנו]\u0006 הגבלה זו שקילל \u0003שם בשם, אבל גוי לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיקלל \u0003שם בשם.\u0004","ושואלים: ולאותן שיטות שלמדו זאת ממקורות אחרים, לשון הריבוי \u0003\"איש איש\" למה לי?\u0004 ומשיבים: לדעתם אין ללמוד מכאן, כי \u0003דיברה תורה כלשון בני אדם,\u0004 וחזרה זו שייכת לסגנון המקרא הרגיל ואין ללמוד ממנה.","כיון שנזכרו דיני בני נח נכנסים כאן לסוגיה שלימה על פרטי דיניהם ומצוותיהם של בני נח. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003שבע מצות נצטוו בני נח,\u0004 ואלו הן: \u0003דינין,\u0004 כלומר, לעשות להם בתי דין שידונו בין הבריות, \u0003ו\u0004על האיסור של \u0003ברכת\u0004 (קללת) \u0003השם,\u0004 על איסור \u0003עבודה זרה,\u0004 על איסור \u0003גילוי עריות, ושפיכות דמים, ו\u0004על איסור \u0003גזל, ו\u0004על איסור אכילת \u0003אבר מן החי.\u0004"],["\u0003ר' חנניה בן גמלא אומר: אף על הדם מן החי\u0004 נצטוו בני נח שאסור לאוכלו. \u0003ר' חידקא אומר: אף על הסירוס\u0004 נצטוו, שאסור להם לסרס כל חי. \u0003ר' שמעון אומר: אף על הכישוף.\u0004","\u0003ר' יוסי אומר: כל האמור בפרשת כישוף\u0004 — \u0003בן נח מוזהר עליו\u0004 שלא יעשה כן. והוא שנאמר: \u0003\"לא ימצא בך מעביר בנו ובתו באש קסם קסמים מעונן ומנחש ומכשף. וחבר חבר ושאל אוב וידעני ודרש אל המתים.\u0004 כי תועבת ה' כל עושה אלה \u0003ובגלל התועבת האלה ה' אלהיך מוריש אותם מפניך\"\u0004 (דברים יח, י–יב), \u0003ולא ענש\u0004 הכתוב \u0003אלא אם כן הזהיר,\u0004 ומאחר והענישם ה' וגרשם מן הארץ בשל חטאים אלה משמע שדברים אלה אסורים להם.","\u0003ר' אלעזר אומר: אף על הכלאים\u0004 נצטוו בני נח. כיצד, ואלו הן הכלאים שנאסרו בהם? — \u0003מותרין בני נח ללבוש כלאים\u0004 (שעטנז), \u0003ולזרוע כלאים\u0004 (שני מיני זרעים יחד), \u0003ואין אסורין\u0004 משום כלאים \u0003אלא בהרבעת בהמה ובהרכבת האילן.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה],\u0006 מהיכן למדים אנו שבע מצוות אלה? \u0003אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ורמז לכך בכתוב: \u0003\"ויצו ה' אלהים על האדם לאמר מכל עץ הגן אכל תאכל.\u0004 ומעץ הדעת טוב ורע לא תאכל ממנו כי ביום אכלך ממנו מות תמות\u0003\"\u0004 (בראשית ב, טז–יז), וכך הוא נדרש:","\u0003\"ויצו\"\u0004 — \u0003אלו הדינין, וכן הוא אומר: \"כי ידעתיו למען אשר יצוה את בניו\u0004 ואת ביתו אחריו ושמרו דרך ה' לעשות צדקה ומשפט\u0003\"\u0004 (בראשית ב, יח, יט).","\u0003\"ה' \"\u0004— \u0003זו ברכת\u0004 (קללת) \u0003השם, וכן הוא אומר: \"ונקב שם ה' מות יומת\"\u0004 (ויקרא טז, כד). \u0003\"אלהים\"\u0004 — \u0003זו\u0004 רמז לאיסור \u0003עבודה זרה, וכן הוא אומר \"לא יהיה לך אלהים אחרים\u0004 על פני\u0003\"\u0004 (שמות כ, ג). \u0003\"על האדם\"\u0004 — \u0003זו שפיכות דמים, וכן הוא אומר: \"שפך דם האדם\u0004 באדם דמו ישפך\u0003\"\u0004 (בראשית ט, ו).","\u0003\"לאמר\"\u0004 — \u0003זו גילוי עריות, וכן הוא אומר: \"לאמר הן ישלח איש את אשתו והלכה מאתו והיתה לאיש אחר...\u0004 הלוא חנוף תחנף הארץ ההיא ואת זנית רעים רבים\u0003\"\u0004 (ירמיה ג, א). \u0003\"מכל עץ הגן\"\u0004 כוונתו — העצים המותרים לך, שמשלך הם \u0003ולא גזל. \"אכל תאכל\"\u0004 — את אלה בלבד שמותרים לאכילה \u0003ולא אבר מן החי.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל לבבל \u0003תני איפכא\u0004 \u0005[שנה להיפך]\u0006 דרשות אלה, בשינוי הכתובים: \u0003\"ויצו\"\u0004 — \u0003זו עבודה זרה. \"אלהים\"\u0004 — \u0003זו דינין.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שאומר אתה כי \u0003\"אלהים\" זו דינין\u0004 — יש ראיה לדבר \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ונקרב בעל הבית אל האלהים\"\u0004 (שמות כב, ז), משמע שהדיינים קרויים \"אלהים\". \u0003אלא \"ויצו\"\u0004 — \u0003זו עבודה זרה, מאי\u0004 \u0005[מה]\u0006 \u0003משמע,\u0004 כיצד שומעים דבר זה מן הכתוב?","ומשיבים, \u0003רב חסדא ורב יצחק בר אבדימי\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הראיה ממה שנאמר \u0003\"סרו מהר מן הדרך אשר צויתם עשו להם\u0004 עגל מסכה\u0003\"\u0004 (שמות לב, ח), ומכאן הקשר בין לשון \"צו\" (\"צויתים\") לעבודה זרה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הראיה ממה שנאמר \u0003\"עשוק אפרים רצוץ משפט כי הואיל הלך אחרי צו\"\u0004 (הושע ה, יא), שמן הענין שם מובן שהוא תוכחה על עבודה זרה.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005],\u0006 מאיזה פסוק למדים דבר זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 לענין \u0003גוי שעשה עבודה זרה ולא השתחוה לה,\u0004 שלא עבדה עדיין. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי הראיה מן הכתוב \u0003\"עשו\u0004 להם עגל \u0003\",\u0004 הרי מכאן למדים ש\u0003משעת עשייה מיחייב\u0004 \u0005[מתחייב],\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאמר]\u0006 כי הראיה מהכתוב \u0003\"כי הואיל הלך\"\u0004 — \u0003עד דאזיל בתרה ופלח\u0004 \u0005[שהולך אחריה ועובד]\u0006 \u0003לה,\u0004 ולא משעת עשייה.","\u0003אמר רבא: ומי איכא למאן דאמר\u0004 \u0005[וכי יש מי שאומר]\u0006 כי \u0003גוי שעשאה עבודה זרה ולא השתחוה לה חייב? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ב\u0004ענין \u0003עבודה זרה, דברים,\u0004 כלומר, עבירות \u0003שבית דין של ישראל ממיתין עליהן\u0004 אם עשה כן אדם מישראל — \u0003בן נח מוזהר עליהן,\u0004 עבירה ש\u0003אין בית דין של ישראל ממיתין עליהן\u0004 — \u0003אין בן נח מוזהר עליהן. למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה],\u0006 אלו פרטי עבירה פטורים עליהם הגויים? \u0003לאו למעוטי\u0004 \u0005[האם לא\u0006 בא הדבר \u0005למעט]\u0006 \u0003גוי שעשה עבודה זרה ולא השתחוה לה?\u0004 שכיון שאין ישראל נהרג על כך, אף הגוי אינו נענש!","\u0003אמר\u0004 \u0003רב פפא: לא,\u0004 אפשר לומר כי בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003גיפוף\u0004 (חיבוק) \u0003ונישוק\u0004 הפסל, שהמגפף או מנשק פסל גם אם גוי הוא אינו חייב משום עבודה זרה. אבל לענין פטור של פסל שנעשה על ידי הגוי ולא נעבד על ידו, אין מכאן ראיה.","ושואלים: \u0003גיפוף ונישוק דמאי\u0004 \u0005[של מה]\u0006 באיזה מקרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שעושה זאת \u0003כדרכה,\u0004 שגיפוף זה הוא דרך עבודתה הרגילה? ודאי \u0003בר קטלא\u0004 \u0005[בן מות]\u0006 \u0003הוא! אלא למעוטי\u0004 \u0005[למעט]\u0006 עבודה זרה שגיפוף ונישוק היא \u0003שלא כדרכה\u0004 — אין הגוי חייב על גיפוף ונישוק.","על רשימת מצוות בני נח שואלים: וכי \u0003דינין בני נח איפקוד\u0004 \u0005[נצטוו]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003עשר מצות נצטוו ישראל\u0004 בהיותם \u0003במרה, שבע שקיבלו עליהן בני נח, והוסיפו עליהן\u0004 עוד: \u0003דינין, ושבת, וכיבוד אב ואם.\u0004","וראיה לדבר, \u0003דינין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בעת היות ישראל במרה: \u0003\"שם שם לו חק ומשפט\"\u0004 (שמות טו, כה), \u0003שבת וכיבוד אב ואם\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בעשרת הדברות: \"שמור את יום השבת לקדשו כאשר צוך ה' אלהיך\u0003\"\u0004 (דברים ה, יב), וכן: \u0003\"\u0004כבד את אביך ואת אמך \u0003כאשר צוך ה' אלהיך\"\u0004 (דברים ה, טז), ומהלשון \"כאשר צוך\" משמע שנצטוו בשבת ובכיבוד אב ואם כבר קודם לכן. \u0003ואמר רב יהודה: \"כאשר צוך\"\u0004 — \u0003במרה,\u0004 ומכאן שמצות דינים אינה כלולה בשבע מצוות בני נח!","\u0003אמר רב נחמן אמר רבה בר אבוה: לא נצרכה,\u0004 הכוונה אינה לעצם המצוה של הדיון בדינים, \u0003אלא\u0004 לפרטי המצוה כיצד דנים בדינים; \u0003לעדה\u0004 (בסנהדרין) \u0003ועדים, והתראה\u0004 קודם לעונש, שאין כל אלו מחדשים מצוה שלא נזכרה בין שבע מצות בני נח.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 המובן, \u0003מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 בלשון \u0003\"והוסיפו עליהן דינין\"?\u0004 הלא אין כאן תוספת מצות דינים אלא פירוט מצות דיינים!","\u0003אלא אמר רבא: לא נצרכה אלא לדיני קנסות\u0004 שאינם דינים של משפט עשיית הצדק בלבד, אלא גם תוספת קנס לחוטא, ואלה לא ניתנו לבני נח. ומקשים: \u0003אכתי\u0004 \u0005[עדיין]\u0006 הלשון אינה מתאימה כי \u0003\"והוסיפו בדינין\",\u0004 כלומר, הוסיפו בפרטי דינים על מה שהיה בתחילה, \u0003מיבעי ליה\u0004 \u0005[היה צורך לו]\u0006 לומר!","\u0003אלא אמר רב אחא בר יעקב: לא נצרכה אלא\u0004 למצוה היתירה \u0003להושיב בית דין בכל פלך\u0004 (מחוז) \u0003ופלך, ובכל עיר ועיר.\u0004 ושואלים: \u0003והא\u0004 \u0005[ו\u0006כי דבר \u0005זה]\u0006 \u0003בני נח לא איפקוד\u0004 \u0005[נצטוו]\u0006 עליו? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003כשם שנצטוו ישראל להושיב בתי דינין בכל פלך ופלך ובכל עיר ועיר, כך נצטוו בני נח להושיב בתי דינין בכל פלך ופלך ובכל עיר ועיר!\u0004","\u0003אלא אמר רבא: האי תנא\u0004 \u0005[תנא זה]\u0006 הסבור שרק ישראל נצטוו על הדינים ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה הוא, דמפיק\u0004 \u0005[שמוציא]\u0006 שתי מצוות שסימנן \u0003ד\"ך\u0004 (\u0003ד\u0004ינים, בר \u0003כ\u0004ת), \u0003ועייל\u0004 \u0005[ומכניס]\u0006 במקומן \u0003ס\"ך\u0004 (\u0003ס\u0004 ירוס, \u0003כ\u0004לאים),","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה: שבע מצות נצטוו בני נח: עבודה זרה, וגילוי עריות, ושפיכות דמים, גזל, ואבר מן החי, סירוס, וכלאים.\u0004 ולא מנה דינים וברכת ה', הואיל והכניס סירוס וכלאים.","\u0003ר' יהודה אומר: אדם הראשון לא נצטווה אלא על עבודה זרה בלבד, שנאמר \"ויצו ה' אלהים על האדם\"\u0004 (בראשית ב, טז). \u0003ר' יהודה בן בתירה אומר: אף על ברכת השם\u0004 נצטווה. \u0003ויש אומרים\u0004 ש\u0003אף על הדינים\u0004 נצטווה.","ושואלים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 דעה \u0005זו]\u0006 ש\u0003אמר רב יהודה אמר רב: \"אלהים אני\",\u0004 כוונתו — \u0003לא תקללוני, \"אלהים אני\"\u0004 כוונתו — \u0003לא תמירוני\u0004 באחר, \u0003\"אלהים אני\"\u0004 כוונתו — \u0003יהא מוראי עליכם. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 — \u0003כיש אומרים,\u0004 שבכלל \"ויצו ה' אלהים על האדם\" הם מבינים גם איסור עבודה זרה (\"לא תמירוני\"), ברכת השם (\"לא תקללוני\"), וגם שמירת חוק ומשפט בעולם (\"יהא מוראי עליכם\").","ושואלים: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה, אי דריש\u0004 \u0005[אם\u0006 הוא \u0005דורש]\u0006 את הפסוק \u0003\"ויצו\"\u0004 — \u0003אפילו הנך נמי\u0004 \u0005[אלה גם כן]\u0006 ברכת ה' ודינים בכלל, \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003לא דריש\u0004 \u0005[דורש]\u0006 \u0003\"ויצו\"\u0004 — \u0003הני מנא ליה\u0004 \u0005[אלו\u0006 השבע \u0005מנין לו]?\u0006","ומשיבים: \u0003לעולם\u0004 תפרש שהוא \u0003לא דריש\u0004 \u0005[דורש]\u0006 \u0003\"ויצו\",\u0004 ואולם \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003כל חדא וחדא באפי נפשיה כתיבא\u0004 \u0005[אחת ואחת\u0006 מהן \u0005בפני עצמה כתובה]\u0006 במקרא; \u0003עבודה זרה וגילוי עריות\u0004 —"],["\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותשחת הארץ לפני האלהים\u0004 ותמלא הארץ חמס\u0003\"\u0004 (בראשית ו, יא), משמע שיש עבירה בהשחתה זו, ומה טיבה? — \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בכל מקום שנאמר\u0004 במקרא לשון \u0003\"השחתה\" אינו אלא דבר ערוה ועבודה זרה,\u0004 וראיה לדבר: \u0003דבר ערוה\u0004 — \u0003שנאמר \"כי השחית כל בשר את דרכו\u0004 על הארץ\u0003\"\u0004 (בראשית ו, יב), ו\"דרכו\" הוא רמז לביאה, משמע שהשחתה זו עניינה שחטאו בעריות. \u0003עבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פן תשחתון ועשיתם\u0004 לכם פסל תמונת כל סמל","\u0003\"\u0004(דברים ד, טז). ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאיננו למד מכאן את איסורי עבודה זרה וגילוי עריות לבני נח, כיצד מבין הוא את הכתוב? ומסבירים: לדעתו את \u0003אורחייהו דקא מגלי\u0004 \u0005[דרכם הוא מגלה],\u0006 שפסוקים אלה נועדו רק כדי להסביר מה היו מעשיהם המקולקלים של בני המבול.","\u0003שפיכות דמים,\u0004 מנין שבני נח נצטוו עליה? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שפך דם האדם\u0004 באדם דמו ישפך\u0003\"\u0004 (בראשית ט, ו). ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאיננו לומד מכאן את מקור איסור שפיכות דמים לבני נח, מה מבין הוא מפסוק זה? ומשיבים: לדעתו דרך \u0003קטלייהו\u0004 \u0005[מיתתם]\u0006 \u0003הוא דקמגלי\u0004 \u0005[שמגלה],\u0006 ללמדנו מה עונשם כשחטאו, אבל לא זה הוא המקור לאיסור שפיכת דם.","\u0003גזל\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004כל רמש אשר הוא חי לכם יהיה לאכלה \u0003כירק עשב נתתי לכם את כל\"\u0004 (בראשית ט, ג), \u0003ואמר ר' לוי: כירק עשב\u0004 הצומח בכל מקום מאליו והוא הפקר, \u0003ולא כירק גנה\u0004 השייך לבעליו בלבד, ומכאן שיש איסור בגזל. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 כיצד דורש הוא כתוב זה? ומשיבים: הכתוב \u0003ההוא\u0004 \u0003למישרי\u0004 \u0005[להתיר]\u0006 אכילת \u0003בשר הוא דאתא\u0004 \u0005[שבא],\u0006 ולא עוד.","\u0003אבר מן החי\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך בשר בנפשו דמו לא תאכלו\"\u0004 (בראשית ט, ד), שלא יאכלוהו בעוד נפשו בו. \u0003ואידך\u0004 \u0005[ו\u0006לדעת \u0005האחר]\u0006 שאיננו לומד מכאן, סבור שהכתוב \u0003ההוא\u0004 \u0003למישרי\u0004 \u0005[להתיר]\u0006 אכילת \u0003שרצים הוא דאתא\u0004 \u0005[שבא],\u0006 שאין איסור אבר מן החי חל לגבי שרצים, שאין בהם חילוק בין בשרם ודמם. ובכגון אלו אין איסור אבר מן החי (ראה לקמן סנהדרין נט,ב).","\u0003סירוס,\u0004 מנין שאסור לבני נח? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ואתם פרו ורבו \u0003שרצו בארץ ורבו בה\"\u0004 (בראשית ט, ז), משמע שאסור לעשות דבר המונע מפריה ורביה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאיננו לומד מכאן, כיצד מסביר הוא את הכתוב? ומשיבים: פסוק זה בא \u0003לברכה בעלמא\u0004 \u0005[בלבד]\u0006 ואיננו כלל למצוה.","\u0003כלאים\u0004 מנין? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מהעוף למינהו\u0004 ומן הבהמה למינה מכל רמש האדמה למינהו\u0003\"\u0004 (בראשית ט, ו, כ), משמע שכל מין צריך להיות בפני עצמו לחוד, ואסור להכליא מינים שונים. \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאיננו לומד מכאן, סבור כי הכתוב \u0003ההוא\u0004 לא למצוה בא אלא \u0003לצותא בעלמא\u0004 \u0005[לחברה בלבד],\u0006 וכעצה שמוטב שיושיב כל מין בפני עצמו, שנוח לו לכל מין בחברת בני מינו.","\u0003אמר רב יוסף, אמרי בי\u0004 \u0005[אמרו\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: על שלש מצות בן נח נהרג (גשר סימן): על גילוי עריות, ועל שפיכות דמים, ועל ברכת\u0004 (קללת) \u0003השם.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על דעה זו \u0003רב ששת: בשלמא\u0004 \u0005[נניח]\u0006 \u0003שפיכות דמים\u0004 יש לה מקור מיוחד, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 במפורש: \u0003\"שפך דם האדם\u0004 באדם דמו ישפך\u0003\"\u0004 (בראשית ט, ו). \u0003אלא הנך מנא להו\u0004 \u0005[האחרות מנין להם]\u0006 שנענשים עליהם במיתה?","\u0003אי גמר\u0004 \u0005[אם למד]\u0006 בהיקש או בגזירה שווה \u0003מ\u0004דין \u0003שפיכות דמים\u0004 — \u0003אפילו כולהו נמי\u0004 \u0005[כולן,\u0006 אף שאר המצוות של בני נח, \u0005גם כן]\u0006 יהיו חייבים עליהן מיתה! \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דאיתרבאי\u0004 \u0005[שהתרבו,\u0006 נלמדו מהריבוי\u0005]\u0006 \u0003מ\u0004הלשון שנאמרה במצוות אלה של \u0003\"איש איש\",\u0004 שנאמר בעריות: \"איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה\u0003\"\u0004 (ויקרא יח, ו), ונאמר בברכת השם: \"איש איש כי יקלל אלהיו ונשא חטאו\u0003\"\u0004 (ויקרא כד, טו), אם כן \u0003עבודה זרה נמי\u0004 \u0005[גם כן]\u0006 \u0003איתרבי\u0004 \u0005[תתרבה,\u0006 תילמד בדרך הריבוי\u0005]\u0006 של \u0003\"איש איש\"\u0004 (ויקרא כ, ב), וייהרג בן נח אף עליה!","\u0003אלא\u0004 יש לדחות גרסה זו שנגרסה בשם בית רב, ו\u0003אמר רב ששת, אמרי בי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב\u0004 כך: \u0003על ארבע מצות בן נח נהרג,\u0004 שלוש אלה שמנינו, ועל עבודה זרה.","ושואלים: \u0003ועל עבודה זרה בן נח נהרג? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בעבודה זרה דברים שבית דין של ישראל ממיתין עליהן\u0004 את העבריין — \u0003בן נח מוזהר\u0004 (אסור) \u0003עליהן.\u0004 ונדייק: \u0003אזהרה,\u0004 כלומר, איסור שלא לעשות — \u0003אין\u0004 \u0005[כן],\u0006 ואולם עונש \u0003מיתה\u0004 — \u0003לא! אמר רב נחמן בר יצחק\u0004 תשובה לכך: \u0003אזהרה שלהן זו היא מיתתן,\u0004 שכיון שלא נתייחד לבני נח עונש מיוחד לעובר על מצוות \"לא תעשה\", הרי מי שהוזהר ועבר — חייב מיתה. זו היתה שיטה אחת.","ואילו \u0003רב הונא ורב יהודה וכולהו תלמידי\u0004 \u0005[וכל\u0006 שאר \u0005תלמידיו]\u0006 של \u0003רב אמרי\u0004 \u0005[אמרו]:\u0006 \u0003על שבע מצות בן נח נהרג,\u0004 כי \u0003גלי רחמנא בחדא\u0004 \u0005[גילתה התורה\u0006 את הדין \u0005באחת,\u0006 בשפיכות דמים\u0005],\u0006 \u0003והוא הדין לכולהו\u0004 \u0005[לכולן],\u0006 שעל כולן חייב מיתה.","ומקשים: \u0003ועל הגזל בן נח נהרג? והתניא\u0004 \u0005[והרי שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003על הגזל\u0004 שבן נח נענש, בכלל זה \u0003גנב וגזל, וכן\u0004 אשה \u0003יפת תואר\u0004 שלוקח אשה שבויה במלחמה, \u0003וכן\u0004 כל \u0003כיוצא בהן,\u0004 אם עשה \u0003גוי בגוי וגוי בישראל\u0004 — \u0003אסור, ו\u0004אם \u0003ישראל בגוי\u0004 — \u0003מותר. ואי איתא\u0004 \u0005[ואם יש]\u0006 ענין שהגוי חייב בגזל, \u0003ניתני\u0004 \u0005[שישנה]\u0006 בלשון \u0003\"חייב\"\u0004 שגוי שעשה כן חייב מיתה, ולא בלשון \"אסור\", שכן לשון \"אסור\" משמעה לאו \u0005בלבד! ומשיבים:\u0006","\u0003משום דקבעי למיתני סיפא\u0004 \u0005[שרצה לשנות בסוף]\u0006 \u0003\"ישראל בגוי מותר\"\u0004 — \u0003תנא רישא\u0004 \u0005[שנה בתחילה]\u0006 לשון \u0003\"אסור\",\u0004 ש\"אסור\" היא הפוכו של \"מותר\" שאילו היה אומר בתחילה \"חייב\" היה צריך לשנות בסוף \"פטור\", ו\"פטור\" משמעו רק פטור מעונש אך לא מותר לכתחילה וזו הסיבה ללשון \"אסור\" שנגרסה כאן. אך אין זו ראיה שהגוי פטור מעונש מיתה.","ושואלים: \u0003והא כל היכא דאית ליה חיובא\u0004 \u0005[מקום שיש לו]\u0006 חיוב מיתה במפורש, \u0003מיתנא קתני,\u0004 \u0003דקתני רישא\u0004 \u0005[\u0006ו\u0005הריהו שונה, ש\u0006כן \u0005שנינו בתחילה]:\u0006 \u0003על שפיכות דמים, גוי בגוי וגוי בישראל\u0004 — \u0003חייב, ישראל בגוי\u0004 — \u0003פטור.\u0004 הרי שהוא משתמש בלשון חיוב!","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 באותו מקרה \u0003היכי ליתני\u0004 \u0005[כיצד ישנה]?\u0006 אין לו אפשרות לשנות בלשון אחרת. שכן אם \u0003ליתני\u0004 \u0005[ישנה]\u0006 בלשון \u0003\"אסור\" ו\"מותר\"\u0004 — הרי נבין מכאן שלישראל מותר להרוג את הגוי לכתחילה, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 ברייתא\u0005]:\u0006 \u0003גוי,\u0004 וכן \u0003רועי בהמה דקה\u0004 ישראלים שכרגיל הם גזלנים — \u0003לא מעלין ולא מורידין.\u0004 כלומר, אין מעלין אותם מן הבור שנפלו בו, או מצילים משאר סכנה שהיו בה. אך גם אין מורידים אותם לשם, ואין ממיתים אותם לכתחילה. ולכן היה צריך לשנות לשון \"פטור\" מעונש ולא \"מותר\" לכתחילה. אך בתוספתא שהסברנו יכול היה לשנות בלשון \"חייב\".","ושבים לביאורה של התוספתא: נאמרו שם דיני גזל בגוי, והוסיפו גניבה גזילה ו\u0003כיוצא בו\u0004 ושואלים: \u0003בגזל מאי היא\u0004 \u0005[מה הם]\u0006 אותם דברים שהם כענין גזל? \u0003אמר רב אחא בר יעקב: לא נצרכה אלא לפועל בכרם\u0004 האוכל מן הפירות, שהוא כעין גזל, וגוי אסור בו.","ושואלים: \u0003פועל בכרם אימת\u0004 \u0005[אימתי]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשעת גמר מלאכה,\u0004 כגון שבוצר את הפירות, הלא \u0003התירא\u0004 \u0005[היתר]\u0006 גמור \u0003הוא,\u0004 שאף לישראל מותר בכרמו של ישראל אחר! \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003בשעת גמר מלאכה\u0004 — \u0003גזל מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא,\u0004 ואין בכך חידוש!","\u0003אלא אמר רב פפא: לא נצרכה\u0004 תוספת זו \u0003אלא ל\u0004גוזל \u0003פחות משוה פרוטה.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 כיצד \u0005שנינו שם\u0006 \u0003ש\u0004\u0003גוי בישראל אסור? הא בר\u0004 \u0005[הרי בן],\u0006 כלומר, ראוי \u0003ל\u0004\u0003מחילה הוא,\u0004 שכל דבר שהוא פחות משווה פרוטה מוחלים עליו, ואינו נחשב. ומדוע נחשב זה כגזל? ומשיבים: \u0003נהי דבתר הכי מחיל ליה, צערא בשעתיה מי לית ליה\u0004 \u0005[אמנם אחר כך מוחל הוא\u0006 על הגזילה אבל \u0005צער בשעתו האם אין לו]?\u0006 ועובר משום גזל בשעתו, ונענש על כך.","ומקשים: אם מדובר בפחות משווה פרוטה, מדוע אם כן שנינו כי \u0003גוי בגוי כיוצא בהן,\u0004 הלא \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003בני מחילה נינהו\u0004 \u0005[הם],\u0006 לגביהם \u0003גזל מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006","הוא, ואין זה רק \"כיוצא בהם\"! \u0003אלא\u0004 יש לדחות פירוש זה, ו\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: לא נצרכה אלא לכובש שכר שכיר,\u0004 שאינו משלם לו שכרו, \u0003גוי בגוי, וגוי בישראל\u0004 — \u0003אסור, ישראל בגוי\u0004 — \u0003מותר,\u0004 שדבר זה אינו כשאר גזל שלוקח מן הנגזל, אלא כאן הוא מונע ממנו דבר המגיע לו.","ועוד מבררים \u0003\"כיוצא\u0004 בו \u0003\"\u0004לגבי \u0003יפת תואר מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 מה איסור הדומה לזה? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' אלעזר\u0004 ש\u0003אמר\u0004 בשם \u0003ר' חנינא: בן נח שייחד שפחה לעבדו\u0004 שתהא לו בת זוג, ואחר כך \u0003בא עליה\u0004 הוא עצמו — \u0003נהרג עליה,\u0004 שאף שהשפחה קניינו היא ואינה אשה גמורה לעבד, מכל מקום כיון שייחדה לו — הרי היא כאשתו.","ומעירים: לשון \u0003\"כיוצא בו\"\u0004 לגבי עבירות של \u0003שפיכות דמים לא תניא\u0004 \u0005[אינה שנויה].\u0006 \u0003אמר אביי: אי משכחת דתניא\u0004 \u0005[אם תמצא ששנויה\u0006 בריתא\u0005]\u0006 באיזה מקום על שפיכות דמים \"וכיוצא בה בן נח נענש\" — דע לך כי שיטת \u0003ר' יונתן בן שאול היא.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יונתן בן שאול אומר:\u0004 מי שהיה \u0003רודף אחר חבירו להורגו ויכול\u0004 הנרדף \u0003להצילו,\u0004 כלומר, להציל את עצמו, \u0003באחד מאבריו\u0004 של הרודף, שיכול לכוון לפגוע באחד מאברי המתכוון לרצוח וינצל, \u0003ולא הציל\u0004 בדרך זו אלא הרג את הרודף,"],["\u0003נהרג עליו\u0004 אף שעשה זאת מתוך הגנה עצמית, וגם בן נח נהרג על כך.","\u0003אשכח\u0004 \u0005[מצא]\u0006 \u0003ר' יעקב בר אחא דהוה כתיב בספר אגדתא דבי\u0004 \u0005[שהיה כתוב בספר אגדה ש\u0006ה\u0005יה\u0006 \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב: בן נח נהרג\u0004 אפילו \u0003בדיין אחד, ובעד אחד שלא בהתראה,\u0004 ואולם בעדות \u0003מפי איש ולא מפי אשה,\u0004 אבל \u0003אפילו קרוב\u0004 מעיד בבני נח. שכל אלה אף שאינם ראויים לדון דין שכזה בישראל, הריהם ראויים לדון בבן נח. \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו:\u0004 בן נח נהרג \u0003אף על העוברין\u0004 שהמית.","ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שהיו כתובים באותו ספר? \u0003אמר רב יהודה:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ו \u0003אך את דמכם לנפשתיכם אדרש\u0004 מיד כל חיה אדרשנו ומיד האדם מיד איש אחיו אדרוש את נפש האדם\u0003\"\u0004 (בראשית ט, ה). וממה שנאמר \"אדרש\" בלשון יחיד, משמע \u0003אפילו בדיין אחד.\u0004","ומה שנאמר \u0003\"מיד כל חיה\"\u0004 — הרי זה בא ללמד שנידונים \u0003אפילו שלא בהתראה,\u0004 שהרי חיה ודאי אינה בת התראה. ומה שנאמר \u0003\"אדרשנו ומיד האדם\",\u0004 שנאמר בלשון יחיד, משמע: \u0003אפילו בעד אחד. \"מיד איש\"\u0004 — \u0003ולא מיד אשה.\u0004 ומ\u0003\"אחיו\"\u0004 — נדקדק: \u0003אפילו\u0004 היה \u0003קרוב\u0004 לו.","באותו ספר אגדה נאמר ש\u0003משום ר' ישמעאל אמרו\u0004 שחייב \u0003אף על העוברין.\u0004 ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' ישמעאל?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שפך דם האדם באדם דמו ישפך\"\u0004 (בראשית ט, ו), והוא מפרש: \u0003איזהו אדם שהוא באדם? הוי אומר: זה עובר שבמעי אמו,\u0004 שחייב בן נח על הריגתו.","ומעירים: \u0003ו\u0004ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאינו מקבל הסבר זה, ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה הוא,\u0004 ש\u0003אמר: כל מיתה האמורה לבני נח אינו אלא חנק, ושדי ליה האי\u0004 \u0005[וזרוק,\u0006 צרף, \u0005לו\u0006 מלה \u0005זו]\u0006 \u0003\"באדם\"\u0004 שנאמרה \u0003אסיפיה דקרא\u0004 \u0005[על סופו של הכתוב],\u0006 \u0003ודרוש ביה הכי\u0004 \u0005[בו כך]:\u0006 \u0003\"באדם דמו ישפך\", איזהו שפיכות דמים של אדם שהוא בגופו של אדם,\u0004 שאין דמו יוצא החוצה? \u0003הוי אומר זה חנק,\u0004 וחלוקה כזו של הפסוק מלמדת אותנו כי כל בן נח היוצא ליהרג — יהרג בחנק.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא: ואשה\u0004 מבני נח \u0003לא מפקדה\u0004 \u0005[אינה מצווה]\u0006 על הדינים? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 באברהם שהיה אז בגדר בן נח \u0003\"כי ידעתיו למען אשר יצוה\u0004 את בניו ואת ביתו אחריו ושמרו דרך ה' לעשות צדקה ומשפט","\u0003\"\u0004((בראשית ט, יח, יט), \"ביתו\" הן הנשים. ומשמע שאף הן בציווי של עשיית משפט! \u0003הוא מותיב לה\u0004 \u0005[מקשה אותה\u0006 קושיה\u0005]\u0006 \u0003והוא\u0004 עצמו \u0003מפרק לה\u0004 \u0005[פותר אותה]:\u0006 את \u0003בניו\u0004 ציוה אברהם \u0003ל\u0004עשות \u0003דין\u0004 (\"משפט\"), ואילו \u0003ביתו,\u0004 כלומר, את בנות ביתו ציוה \u0003ל\u0004עשות \u0003צדקה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אויא סבא\u0004 \u0005[הזקן]\u0006 \u0003לרב פפא: אימא\u0004 \u0005[אמור]\u0006 אם כן, כי \u0003בת נח שהרגה לא תיהרג,\u0004 שהרי \u0003\"מיד איש\" ולא \"מיד אשה\" כתיב\u0004 \u0005[נאמר]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה:\u0004 נאמר שם \u0003\"שפך דם האדם\"\u0004 בלא פירוט, משמע כל מי ששופכו \u0003מכל מקום\u0004 נהרג, בין איש ובין אשה.","ומקשים: לפי עקרון זה \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003בת נח שזינתה לא תיהרג, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"על כן יעזב איש\u0004 את אביו ואת אמו ודבק באשתו והיו לבשר אחד\u0003\"\u0004 ((בראשית ט, ב, כד), ואף כאן תאמר איש \u0003ולא אשה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה:\u0004 נאמר בסוף הפסוק \u0003\"והיו לבשר אחד\"\u0004 — \u0003הדר ערבינהו קרא\u0004 \u0005[חזר ועירבם הכתוב]\u0006 וגילה שדינם שווה, כי הם \"בשר אחד\".","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה\" (ויקרא יח, ו), ודי היה לומר \u0003\"איש\", מה תלמוד לומר: \"איש איש\"?\u0004 — \u0003לרבות את הגויים שמוזהרין על העריות כישראל.\u0004","ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006דבר \u0005זה מכאן,\u0006 מפסוק זה \u0005יוצא,\u0006 נלמד\u0005]?\u0006 והרי \u0003מהתם נפקא\u0004 \u0005[משם,\u0006 מפסוק אחר \u0005יוצא,\u0006 נלמד\u0005],\u0006 שכבר דרשנו: \u0003\"לאמר\" זה\u0004 רמז לאסור \u0003גילוי עריות\u0004 (ראה לעיל סנהדרין דף נו,ב).","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 אותו כתוב מדבר \u0003בעריות דידהו\u0004 \u0005[שלהם],\u0006 באותן שהם אסורים בהן, \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003בעריות דידן\u0004 \u0005[שלנו],\u0006 שאם בא הגוי על אשה ישראלית שהיא נשואה על פי דיני ישראל — נענש על כך, \u0003דקתני סיפא\u0004 \u0005[ששנינו בסוף\u0006 אותה ברייתא\u0005]:\u0006 \u0003בא\u0004 הגוי \u0003על עריות ישראל\u0004 — \u0003נידון בדיני ישראל.\u0004","ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 אמרו שנידון בדיני ישראל? \u0003אמר רב נחמן אמר\u0004 \u0003רבה בר אבוה: לא נצרכה אלא\u0004 לומר שגוי זה נידון בדיני ישראל ב\u0003עדה\u0004 (בסנהדרין), \u0003ועדים, והתראה.\u0004","ושואלים: וכי דינו \u0003מגרע גרע\u0004 \u0005[נעשה גרוע יותר],\u0006 שאם היה עובר עבירה זו בבת נח לא היו מזקיקים אותו לכל אלה, ועכשיו שפגע בישראל לא יתחייב אלא אם כן נתמלאו כל התנאים הללו?!","\u0003אלא אמר ר' יוחנן: לא נצרכה אלא ל\u0004גוי הבא על \u0003נערה המאורסה\u0004 בת ישראל, \u0003דלדידהו לית להו\u0004 \u0005[שלהם אין להם],\u0006 שבבני נח יש רק נישואין גמורים ואין מעמד ביניים של אירוסין, \u0003דדיינינן להו בדינא דידן\u0004 \u0005[שדנים אותם בדין שלנו]\u0006 במקרה כזה.","ושואלים: \u0003אבל\u0004 אם בא הגוי על \u0003אשת איש\u0004 מישראל, \u0003בדינא דידהו דיינינן להו\u0004 \u0005[בדין שלהם אנו דנים אותם]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בא\u0004 גוי \u0003על נערה המאורסה\u0004 מישראל — \u0003נידון בסקילה,\u0004 בא \u0003על אשת איש\u0004 — \u0003נידון בחנק. ואי בדינא דידהו\u0004 \u0005[ואם בדינם שלהם],\u0006 הלא ב\u0003סייף הוא\u0004 דינם!","\u0003אמר רב נחמן בר יצחק: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אשת איש\" דקתני\u0004 \u0005[ששונה]?\u0006 — כאן מדובר במקרה מיוחד: \u0003כגון שנכנסה\u0004 אותה אשה \u0003לחופה ו\u0004עדיין \u0003לא נבעלה,\u0004 שהיא נחשבת כבר כנשואה בדיני ישראל. \u0003דלדידהו לית להו\u0004 \u0005[שלהם אין להם]\u0006 מעמד כגון זה ועדיין אינה קרוייה אשתו, לכן \u0003דיינינן להו בדינא דידן\u0004 \u0005[דנים אנו אותם בדין שלנו],\u0006 והבא על אשת איש — נידון בחנק.","\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חנינא: בעולת בעל\u0004 — \u0003יש להן,\u0004 שכיון שנבעלה אשה לשם נישואין הרי היא נעשית אשת איש, אבל \u0003נכנסה לחופה ולא נבעלה\u0004 — \u0003אין להן,\u0004 שלדיניהם אינה נחשבת כאשה נשואה.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 תוספתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: כל ערוה שבית דין של ישראל ממיתין עליה\u0004 — \u0003בן נח מוזהר עליה,\u0004 וכל ערוה ש\u0003אין בית דין של ישראל ממיתין עליה\u0004 — \u0003אין בן נח מוזהר עליה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: הרבה עריות יש שאין בית דין של ישראל ממיתין עליהן, ו\u0004בכל זאת \u0003בן נח מוזהר עליהן.\u0004","ועוד: אם \u0003בא על עריות ישראל\u0004 — \u0003נידון בדיני ישראל, בא על עריות בן נח\u0004 — \u0003נידון בדיני בן נח. ואנו אין לנו\u0004 דוגמה לעריות ישראל אלה, שאם בא גוי עליהן הינו נידון בדיני ישראל, \u0003אלא נערה המאורסה בלבד,\u0004 כדברי ר' יוחנן.","ושואלים: \u0003ונחשוב נמי\u0004 \u0005[ושימנה גם כן]\u0006 דין אשה ש\u0003נכנסה לחופה ולא נבעלה!\u0004 ומשיבים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא,\u0004 \u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003מנשה הוא,\u0004 ש\u0003אמר: כל מיתה האמורה לבני נח אינו אלא חנק,\u0004 וכיון שנכנסה אותה אשה ישראלית לחופה אשת איש היא ודינה בחנק, \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003חנק הוא\u0004 ואין הבדל בין דיננו לדיניהם במקרה זה.","בברייתא זו הובאה שיטת ר' מאיר, ושואלים: \u0003ו\u0004כי \u0003סבר ר' מאיר\u0004 כי \u0003כל ערוה שבית דין של ישראל ממיתין עליה\u0004 — \u0003בן\u0004 \u0003נח מוזהר עליה? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גר\u0004"],["\u0003שהיתה הורתו\u0004 (הריונו) \u0003שלא בקדושה,\u0004 שהוריו היו עדיין גויים, \u0003ולידתו בקדושה,\u0004 שנתגיירה אמו לפני שילדתו — \u0003יש לו שאר האם,\u0004 כלומר, קרוביו מצד האם נחשבים קרובים לו \u0003ואין לו שאר האב.\u0004","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 אם \u0003נשא אחותו מן האם\u0004 שהתגיירה גם היא — \u0003יוציא,\u0004 שאסורה היא לו מדברי סופרים. וטעמו של איסור זה: כיון שאותה קרובה היתה אסורה עליו בהיותו גוי, אף על פי שלאחר שנתגייר נותקו כל קשרי המשפחה בינו ובין קרוביו הקודמים (שגר הריהו כקטן שנולד), מכל מקום אסרו עליו קרובות, שלא נראה לו שבהיותו בן ישראל הותרו לו דברים שהיה אסור בהם קודם לכן. נשא אחותו \u0003מן האב\u0004 — \u0003יקיים.\u0004 נשא \u0003אחות האב\u0004 שהיא ואביו \u0003מן האם,\u0004 כלומר, בני אם אחת — \u0003יוציא, מן האב\u0004 שהיא בת אבי אביו — \u0003יקיים.\u0004","נשא \u0003אחות האם מן האם\u0004 — \u0003יוציא. אחות האם מן האב, ר' מאיר אומר: יוציא,\u0004 שהרי יש בה צד קירבה מצד האם, \u0003וחכמים אומרים: יקיים. שהיה ר' מאיר אומר: כל ערוה שהיא משום שאר אם\u0004 — בכל מקרה \u0003יוציא, משום שאר האב\u0004 — \u0003יקיים.\u0004","\u0003ו\u0004לכל הדעות \u0003מותר\u0004 גר זה \u0003באשת אחיו, ובאשת אחי אביו. ושאר כל עריות מותרות לו לאתויי\u0004 \u0005[להביא,\u0006 להוסיף\u0005]\u0006 \u0003אשת אביו\u0004 שמותרת לו, אם נתאלמנה או נתגרשה מאביו.","\u0003נשא\u0004 גר \u0003אשה ובתה\u0004 שנתגיירו יחד, \u0003כונס אחת\u0004 מהן כאשתו \u0003ומוציא אחת, ולכתחילה לא יכנוס\u0004 אפילו אחת מהן, שהרי בישראל אסור הוא בכגון זה. \u0003מתה אשתו\u0004 — \u0003מותר\u0004 לשאת את \u0003חמותו\u0004 שנתגיירה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003אסור בחמותו.\u0004 על כל פנים נראה מדברי ר' מאיר שבן נח מוזהר על כמה עריות שאין בית דין של ישראל ממית עליהם (אחותו, אחות אמו), אלא רק אסורות באיסור כרת!","\u0003אמר רב יהודה: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא השניה כשיטת \u0003ר' מאיר אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' אליעזר, והא\u0004 \u0005[וזו]\u0006 הברייתא הראשונה כשיטת \u0003ר' מאיר אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' עקיבא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"על כן יעזב איש את אביו ואת אמו\u0004 ודבק באשתו והיו לבשר אחד\u0003\"\u0004 (בראשית ב, כד), ש\u0003ר' אליעזר אומר: \"אביו\"\u0004 — כוונתו כאן \u0003אחות אביו,\u0004 שצריך לעזבה מלשאת אותה, ולבקש אשה שאינה קרובתו. \u0003\"אמו\"\u0004 — \u0003אחות אמו.\u0004 ואילו \u0003ר' עקיבא אומר: \"אביו\"\u0004 — משמע \u0003אשת אביו, \"אמו\"\u0004 — \u0003אמו ממש.\u0004","\u0003\"ודבק\"\u0004 — \u0003ולא בזכר\u0004 שאין זה חיבור שיש בו דביקה. \u0003\"באשתו\"\u0004 — \u0003ולא באשת חבירו. \"והיו לבשר אחד\"\u0004 — \u0003מי שנעשים בשר אחד\u0004 שיכולים להוליד זה מזה, \u0003יצאו בהמה וחיה שאין נעשין בשר אחד,\u0004 וכל אלה אסורים לבני נח.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו, \u0003ר' אליעזר אומר: \"אביו\"\u0004 — משמעו \u0003אחות אביו.\u0004 ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה כאן \u0003אביו ממש,\u0004 ולהזהירו על משכב זכור עם אביו! ומשיבים: הרי \u0003היינו\u0004 \u0005[זהו]\u0006 מה שאמרו \u0003\"ודבק\"\u0004 — \u0003ולא בזכר,\u0004 והרי אביו בכלל.","ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 שהכוונה כאן ל\u0003אשת אביו!\u0004 ומשיבים: הרי \u0003היינו\u0004 \u0005[זו]\u0006 כבר אסורה עליו וכלולה \u0003ב\u0004מה שנאמר \u0003\"אשתו\" ולא באשת חבירו.\u0004 ומקשים: \u0003אימא\u0004 \u0005[אמור]\u0006 שמדובר כאן \u0003לאחר מיתה\u0004 של האב, ששוב אינה אשת איש! ודוחים: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003אמו\u0004 אמר הכתוב, \u0003מה אמו דלאו\u0004 \u0005[שאין]\u0006 בכך איסור משום שהיא \u0003אישות\u0004 (נישואין) לאביו, אלא משום קירבה לו, \u0003אף אביו\u0004 הכוונה \u0003דלאו\u0004 \u0005[שאינו]\u0006 קשר \u0003אישות\u0004 אלא קירבת דם.","ר' אליעזר אמר עוד כי \u0003\"אמו\"\u0004 פירושו \u0003אחות אמו.\u0004 ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003אמו ממש!\u0004 ודוחים: אם כן הרי \u0003היינו\u0004 \u0005[זו]\u0006 כבר אסורה עליו וכלולה \u0003ב\u0004מה שנאמר \u0003אשתו ולא באשת חבירו,\u0004 שהרי אמו היא אשת אביו! ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה שחייב על אמו גם \u0003לאחר מיתה\u0004 של אביו! ודוחים: מסתבר כי ביטוי זה \u0003דומיא\u0004 \u0005[בדומה]\u0006 למה שנאמר \u0003\"אביו\", מה \"אביו\" דלאו\u0004 \u0005[שאינו]\u0006 ערות אביו \u0003ממש\u0004 אלא קרובת אביו, \u0003אף \"אמו\" דלאו\u0004 \u0005[שאינה]\u0006 \u0003ממש\u0004 אלא קרובת אמו.","\u0003ר' עקיבא אומר: \"אביו\"\u0004 פירושו \u0003אשת אביו.\u0004 ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא \u0003אביו ממש!\u0004 ודוחים: אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 מה שנאמר \u0003\"ודבק\"\u0004 — \u0003ולא בזכר.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אשת אביו נמי היינו\u0004 \u0005[גם כן הרי זה]\u0006 כלול במה שנאמר \u0003באשתו ולא באשת חברו!\u0004 ומשיבים: מדובר כאן באשת אביו \u0003לאחר מיתה\u0004 של אביו, ואין כאן איסור אשת איש אלא איסור קירבה.","ועוד, לדברי ר' עקיבא: \u0003\"אמו\"\u0004 — \u0003אמו ממש,\u0004 ומקשים: הרי \u0003היינו\u0004 \u0005[זו]\u0006 כבר אסורה עליו וכלולה \u0003ב\u0004מה שנאמר \u0003אשתו ולא באשת חברו!\u0004 ומשיבים: מדובר כאן על \u0003אמו מאנוסתו,\u0004 שאנסה אביו ונולד זה ממנה, אבל לא היתה אשת אביו.","לעצם מחלוקתם שואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005הם נחלקו]?\u0006 ומסבירים: \u0003ר' אליעזר סבר\u0004"],["כי יש לפרש את הביטויים בדרך דומה: \u0003\"אביו\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"אמו\", ו\"אמו\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"אביו\".\u0004 ודבר זה \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה]\u0006 אפשרות לפרש את שני הביטויים בשווה \u0003אלא באחווה,\u0004 באחות אביו ואחות אמו.","\u0003ור' עקיבא\u0004 סבור: \u0003מוטב לאוקמיה\u0004 \u0005[להעמיד,\u0006 לפרש\u0005]\u0006 שמדובר \u0003באשת אביו דאיקרי\u0004 \u0005[שנקראה]\u0006 בכתוב \u0003\"ערות אביו\"\u0004 (\"ערות אביך\", ויקרא יח, ח), \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003אחות אביו\u0004 שרק \u0003\"שאר אביו\"\u0004 — \u0003איקרי\u0004 \u0005[נקראה]\u0006 בכתוב (\"שאר אביך\". ויקרא יח, יב), ואולם \u0003\"ערות אביו\"\u0004 — \u0003לא איקרי\u0004 \u0005[נקראה].\u0006 ומנסים להוכיח אמיתותן של כל אחת משיטות אלה מן המקרא.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 שנאמר \u0003\"ויקח עמרם את יוכבד דדתו\u0004 לו לאשה\u0003\"\u0004 (שמות ו, כ), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שהיתה \u0003דודתו מן האם\u0004 שהיתה אחות אביו גם מאב וגם מאם? משמע שאחות האב מותרת!","ודוחים: \u0003לא,\u0004 היא היתה \u0003דודתו\u0004 אחות אביו, אחות קהת אבי עמרם \u0003מן האב\u0004 בלבד, אבל לא היתה אחות אביו מאמו, וקירבה דרך האב בלבד אינה נחשבת.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה שאמר אברהם אבינו לאבימלך אודות שרה: \u0003\"וגם אמנה אחתי בת אבי הוא אך לא בת אמי\u0004 ותהי לי לאשה\u0003\"\u0004 (בראשית כ, יב), \u0003מכלל\u0004 הדברים למד כי אחותו \u0003בת האם אסורה\u0004 אפילו לבני נח!","ודוחים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 כי אפשר בכלל לקבל פסוק זה כפשוטו? וכי \u0003אחותו הואי\u0004 \u0005[היתה],\u0006 הלא \u0003בת אחיו הואי\u0004 \u0005[היתה]!\u0006 שלפי המסורת היתה שרה בתו של הרן (יסכה), \u0003וכיון דהכי\u0004 \u0005[שכך]\u0006 \u0003הוא, לא שנא\u0004 \u0005[אין שוני]\u0006 בין אחות ש\u0003מן האב ולא שנא\u0004 \u0005[ואין שוני]\u0006 בין אחות ש\u0003מן האם,\u0004 ובכל אופן \u0003שריא\u0004 \u0005[מותרת]\u0006 אפילו לישראל. \u0003אלא, התם הכי קאמר ליה\u0004 \u0005[שם כך אמר לו\u0006 אברהם\u0005]:\u0006 \u0003קורבא\u0004 \u0005[קירבה]\u0006 של \u0003אחות אית\u0004 \u0005[יש]\u0006 \u0003לי בהדה\u0004 \u0005[עמה],\u0006 שבת אח הריהי כאחות, \u0003מאבא ולא מאמא.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת לדבר ממה ששנינו: \u0003מפני מה לא נשא אדם\u0004 הראשון \u0003את בתו?\u0004 — \u0003כדי שישא קין את אחותו\u0004 ותהא פריה ורביה מיד, והוא \u0003שנאמר: \"כי אמרתי עולם חסד יבנה\"\u0004 (תהלים פט, ג), שיש בפסוק זה רמז שבתחילת קיומו של העולם הותר לבני אדם לשאת אחיות, שהיא עבירה שנאמר עליה \"ואיש אשר יקח את אחותו... חסד הוא\u0003\"\u0004 (ויקרא כ, יז). ונדייק: \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא\u0006 היה \u0005כך]\u0006 ולא התיר ה' את הדבר במיוחד, היתה האחות \u0003אסירא\u0004 \u0005[אסורה]\u0006 וקשה לר' עקיבא!","ודוחים: אמנם כן, היה איסור בדבר מתחילה אך \u0003כיון דאשתרי\u0004 \u0005[שהותר]\u0006 לשאת את אחותו — \u0003אשתרי\u0004 \u0005[הותרה]\u0006 לכל הדורות לבני נח, ונאסרה לישראל בלבד.","\u0003אמר רב הונא: גוי מותר בבתו,\u0004 שרשאי לשאתה ואין זו קרויה ערוה לגביו, \u0003ואם תאמר: מפני מה לא נשא אדם\u0004 הראשון \u0003את בתו?\u0004 — \u0003כדי שישא קין את אחותו, משום\u0004 שנאמר \u0003\"עולם חסד יבנה\".\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שלא כך אמר, אלא \u0003אמר רב הונא: גוי אסור בבתו. תדע\u0004 ראיה לכך: \u0003שלא נשא אדם\u0004 הראשון \u0003את בתו.\u0004 ודוחים: \u0003ולא היא,\u0004 אין זו ראיה, \u0003התם היינו טעמא\u0004 \u0005[שם זהו הטעם]:\u0006 \u0003כדי שישא קין את אחותו, משום\u0004 ש\u0003\"עולם חסד יבנה\".\u0004","\u0003אמר רב חסדא: עבד\u0004 כנעני \u0003מותר באמו ומותר בבתו.\u0004 כי \u0003יצא מכלל גוי,\u0004 שעל ידי טבילתו להיות עבד לישראל ניתק קשריו עם קרוביו הגוים כגר, ואולם \u0003לכלל ישראל לא בא\u0004 ואינו חייב במצוות כישראל, ולכן אין מחשיבים לו קשר משפחתי משום צד, ומותר אף באמו ובאחותו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' אלעזר\u0004 ש\u0003אמר\u0004 בשם \u0003ר' חנינא: בן נח שייחד שפחה לעבדו\u0004 שתהא לו בת זוג, \u0003ו\u0004אחר כך \u0003בא עליה\u0004 הוא עצמו — \u0003נהרג עליה\u0004 משום אשת איש.","ושואלים: \u0003מאימת\u0004 \u0005[מאימתי]\u0006 קרוייה היא אשתו של העבד? \u0003אמר רב נחמן: מדקראו\u0004 \u0005[מ\u0006זמן \u0005שקוראים]\u0006 \u0003לה \"רביתא דפלניא\"\u0004 \u0005[\"בחורה של פלוני\"].\u0006 ושואלים: \u0003מאימת\u0004 \u0005[מאימתי]\u0006 זמן \u0003התרתה,\u0004 מתי ניתק הקשר בין העבד והשפחה? \u0003אמר רב הונא: משפרעה\u0004 (גילתה) \u0003ראשה בשוק.\u0004 שרק אשה נשואה היתה נוהגת לכסות ראשה, שמוכיחה שאינה רוצה להיות קשורה בו עוד. שאף אשה גויה נשואה היתה נוהגת לצאת בכיסוי ראש לשוק.","\u0003אמר ר' אלעזר אמר ר' חנינא:\u0004 \u0003בן נח שבא על אשתו שלא כדרכה\u0004 — \u0003חייב\u0004 משום ערוה, \u0003שנאמר: \"ודבק\u0004 באשתו\u0003\"\u0004 (בראשית ב, כד) — \u0003ולא שלא כדרכה,\u0004 שאין זו דרך של דביקה, ונמצא שעבר על ציווי התורה.","\u0003אמר רבא: מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003ישראל לא מיחייב\u0004 \u0005[אינו חייב\u0006 בו\u0005]\u0006 \u0003וגוי מיחייב\u0004 \u0005[חייב\u0006 בו\u0005]?\u0006 והלא ביאה כזו באשתו אין מענישים עליה אדם מישראל!","\u0003אלא אמר רבא\u0004 שכך יש להבין את הפסוק: \u0003בן נח שבא על אשת חבירו שלא כדרכה\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 נאמר: \u0003\"\u0004ודבק \u0003באשתו\" ולא באשת חבירו,\u0004 משמע שבאשת חבירו אסור לו לדבוק, אבל \u0003\"ודבק\"\u0004 — \u0003ולא\u0004 בביאה \u0003שלא כדרכה.\u0004","\u0003אמר ר' חנינא: גוי שהכה את ישראל\u0004 — \u0003חייב מיתה, שנאמר\u0004 כאשר ראה משה איש מצרי מכה איש עברי: \u0003\"ויפן כה וכה וירא כי אין איש ויך את המצרי\u0004 ויטמנהו בחול","\u0003\"\u0004(שמות ב, יב), \u0003ואמר ר' חנינא: הסוטר לועו\u0004 (לחיו) \u0003של ישראל, כאילו סוטר לועו של שכינה, שנאמר \"מוקש אדם ילע קדש\"\u0004 (משלי כ, כה), המכה אדם (\"מוקש\") מישראל כביכול פוגע בלועו (\"ילע\") של הקודש.","סימן להלכות הבאות הוא: \"ה \u0003מגביה\u0004 יד, \u0003עבדו\u0004 לענין עבד ועבודה, \u0003שבת\u0004 לגוי\". \u0003אמר ריש לקיש: המגביה ידו על חבירו\u0004 להכותו, \u0003אף על פי שלא הכהו נקרא \"רשע\", שנאמר: \"\u0004והנה שני אנשים עברים נצים \u0003ויאמר לרשע למה תכה רעך\"\u0004 (שמות ב, יג), \u0003\"למה הכית\" לא נאמר, אלא \"למה תכה\"\u0004 לשון עתיד, כלומר, מתכוון להכות, משמע שהמרים יד להכות \u0003אף על פי שלא הכהו, נקרא \"רשע\".\u0004","\u0003אמר זעירי אמר ר' חנינא:\u0004 המרים יד להכות את חבירו \u0003נקרא \"חוטא\", שנאמר: \"\u0004ובא נער הכהן... ואמר לו כי עתה תתן \u0003ואם לא לקחתי בחזקה\"\u0004 (שמואל א' ב, טו–טז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 על כך: \u0003\"ותהי חטאת הנערים גדולה מאד\"\u0004 (שמואל א' ב, יז).","\u0003רב הונא אמר:\u0004 העושה כן \u0003תיקצץ ידו, שנאמר: \"וזרוע רמה תשבר\"\u0004 (איוב לח, טו), שמי שרגיל להרים זרועו מוטב שתשבר. ומסופר, ש\u0003רב הונא קץ ידא\u0004 \u0005[קצץ ידו]\u0006 של אדם שהיה נוהג להכות את חבריו.","\u0003ר' אלעזר אומר: אין לו תקנה\u0004 לאיש אלים כזה \u0003אלא קבורה, שנאמר: \"ואיש זרוע לו הארץ\"\u0004 (איוב כב, ח), ומפרשו: איש המכה בזרוע ראוי לו בשל כך להיות קבור בארץ.","\u0003ואמר ר' אלעזר\u0004 פירוש אחר לאותו פסוק: \u0003לא נתנה קרקע אלא לבעלי זרועות\u0004 היכולים להגן על עצמם מכל אויב, \u0003שנאמר: \"ואיש זרוע לו הארץ\".\u0004","\u0003ו\u0004אגב אימרה זו מביאים את מה ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עבד אדמתו ישבע לחם\"\u0004 (משלי יב, יא)? \u0003אם עושה אדם עצמו כעבד לאדמה\u0004 (\"עובד אדמתו\") ומקדיש לכך את כל מאמציו — \u0003ישבע לחם, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003לא ישבע לחם.\u0004","\u0003ואמר ריש לקיש: גוי ששבת\u0004 — \u0003חייב מיתה, שנאמר: \"\u0004עוד כל ימי הארץ זרע וקציר וקור וחום וקיץ וחורף \u0003ויום ולילה לא ישבתו\"\u0004 (בראשית ח, כג), ללמד שאסור לשבות ממלאכה, ויש לו לעבוד כל ימי חייו. \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003אזהרה שלהן זו היא מיתתן,\u0004 שלא ניתנו לבני נח עונשים אחרים, אלא עונש מיתה לכל העובר על המצוות. \u0003אמר רבינא:\u0004 גם אם עשה את יום השבתון ביום כל שהוא שאינו מיוחד לפולחן לכל דת, אלא \u0003אפילו שני בשבת.\u0004","ושואלים: \u0003וליחשבה\u0004 \u0005[ושימנה]\u0006 מצוה זו \u0003גבי שבע מצות\u0004 בני נח! ומשיבים: \u0003כי קא חשיב\u0004 \u0005[כאשר מנה]\u0006 שבע מצוות — מנה רק את אלה שהן ב\u0003\"שב ואל תעשה\",\u0004 כלומר, דברים שיש בהם איסור, ויש להמנע מהם. ואולם מצוות של \u0003\"קום עשה\"\u0004 — \u0003לא קא חשיב\u0004 \u0005[\u0006ו\u0005הוא לא מנה].\u0006"],["ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 מצות \u0003דינין\u0004 (עשיית המשפט) \u0003קום עשה הוא, ו\u0004למרות כן \u0003קא חשיב\u0004 \u0005[מונה]\u0006 אותה בשבע מצוות! ודוחים: במצוה זו יש חלק של \u0003\"קום עשה\" ו\u0004גם \u0003\"שב אל תעשה\" נינהו\u0004 \u0005[הם],\u0006 שיש בה גם ציווי למנות דיינים ולעשות דין, וגם מצות \"לא תעשה\" שלא לעשות עוול לחבירו שלא כדין.","\u0003ואמר ר' יוחנן: גוי שעוסק בתורה\u0004 — \u0003חייב מיתה, שנאמר: \"תורה צוה לנו משה מורשה\u0004 קהילת יעקב\u0003\"\u0004 (דברים לג, ד), כלומר, \u0003לנו מורשה ולא להם.\u0004","ושואלים: אם כן \u0003וליחשבה\u0004 \u0005[ושימנה אותה],\u0006 איסור זה, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שבע מצות\u0004 בני נח! ומתרצים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ומבין מכתוב זה שהתורה היא \u0003\"מורשה\"\u0004 — ירושה, אם כן הגוי העוסק בה \u0003מיגזל קא גזיל לה\u0004 \u0005[גוזל אותה]\u0006 וחייב משום גזל, וזו אכן נמנית, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שיש להבין כאן כאילו נכתב \u0003\"מאורסה\"\u0004 — אם כן \u0003דינו כ\u0004בא על \u0003נערה המאורסה,\u0004 ש\u0003בסקילה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' יוחנן, ממה ש\u0003היה ר' מאיר אומר: מניין שאפילו גוי ועוסק בתורה שהוא\u0004 חשוב \u0003ככהן גדול? שנאמר: \"\u0004ושמרתם את חוקותי ואת משפטי \u0003אשר יעשה אתם האדם וחי בהם\"\u0004 (ויקרא יח, ה), \u0003כהנים לויים וישראלים לא נאמר\u0004 בפסוק זה \u0003אלא \"האדם\", הא\u0004 \u0005[הרי]\u0006 \u0003למדת שאפילו גוי ועוסק בתורה הרי הוא ככהן גדול!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בדברי ר' מאיר הכוונה כשאותו גוי עוסק \u0003ב\u0004לימוד \u0003שבע מצות דידהו\u0004 \u0005[שלהם],\u0006 שבהלכות הנוגעות לשבע מצוות אלה מצווה הוא לעסוק, וכשעוסק בהן הריהו נחשב ביותר.","בברייתא היסודית בדיני בני נח הובא גם ש\u0003ר' חנינא בן גמליאל אומר: אף הדם מן החי\u0004 נצטוו עליו בני נח. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"אך בשר בנפשו דמו לא תאכלו\"\u0004 (בראשית ט, ד) — \u0003זה אבר מן החי,\u0004 שלא לאכול בשר בעוד נפש החיים בו. \u0003ר' חנינא בן גמליאל אומר: אף הדם מן החי\u0004 נאסר מכאן.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' חנינא בן גמליאל?\u0004 ומסבירים: \u0003קרי ביה\u0004 \u0005[קורא\u0006 הוא \u0005בו]\u0006 בפסוק זה קריאה כפולה: \u0003\"בשר בנפשו לא תאכל\"\u0004 וגם \u0003\"דמו בנפשו לא תאכל\".\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 כיצד מפרשים הם \"דמו\" האמור בכתוב זה? שהרי לדעתם יש שם רק איסור אבר מן החי אך לא דם! ומשיבים: הפסוק \u0003ההוא\u0004 \u0003למישרי\u0004 \u0005[להתיר]\u0006 אבר מן החי ב\u0003שרצים הוא דאתא\u0004 \u0005[שבא],\u0006 והזכיר גם \"דמו\" ללמד שאין האיסור אלא בבעלי חיים שדמם נפרד לגמרי מבשרם, ואילו שרצים אין דמם חלוק מבשרם, ולפיכך הותר להם.","\u0003כיוצא בדבר אתה אומר\u0004 ראיה לענין דם מן החי שלדעת ר' חנינא נאסר לישראל בסיני \u0003\"רק חזק לבלתי אכל הדם כי הדם הוא הנפש\u0004 ולא תאכל הנפש עם הבשר\u0003\"\u0004 (דברים יב, כג). וכך הוא מפרש: \u0003\"רק חזק לבלתי אכל הדם\"\u0004 — \u0003זה אבר מן החי. \"כי הדם הוא הנפש\"\u0004 — \u0003זה דם מן החי.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מוצאים איסור מיוחד בדם מן החי, כיצד מפרשים הם כתוב זה? ומשיבים: הפסוק \u0003ההוא\u0004 \u0003לדם הקזה\u0004 \u0003שהנשמה יוצאה בו הוא דאתא\u0004 \u0005[שבא],\u0006 ללמד שגם דם זה אסור, ושואלים: לשיטת ר' חנינא בן גמליאל","\u0003למה לי למיכתב\u0004 \u0005[לכתוב]\u0006 הלכה זו \u0003לבני נח, ולמה לי למשני\u0004 \u0005[לחזור\u0006 עליה\u0005]\u0006 \u0003בסיני\u0004 לישראל, והלא ישראל בכלל בני נח הם!","ומשיבים: דבר זה יש להבין \u0003כ\u0004שיטת \u0003ר' יוסי בר' חנינא.\u0004 ש\u0003אמר ר' יוסי בר' חנינא: כל מצוה שנאמרה\u0004 בראשונה \u0003לבני נח ונשנית בסיני\u0004 משמעותה ש\u0003לזה ולזה,\u0004 לבני נח ולישראל \u0003נאמרה.\u0004","ואולם אם נאמרה בתחילה \u0003לבני נח ולא נשנית בסיני\u0004 בתוך המצוות שנתנו לישראל, יש להבין כי \u0003לישראל נאמרה ולא לבני נח. ואנו אין לנו\u0004 דוגמא לכך \u0003אלא גיד הנשה, ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה,\u0004 הסבור כי הפסוק הנאמר \"על כן לא יאכלו בני ישראל את גיד הנשה אשר על כף הירך עד היום הזה\u0003\"\u0004 (בראשית לב, לב), כוונתו לבני יעקב אבינו, שאף שהיו בתורת בני נח נצטוו במצוה זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל מצוה שנאמרה לבני נח ונשנית בסיני\u0004 — \u0003לזה ולזה נאמרה.\u0004 ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003מ\u0004כיון ש\u0003נשנית בסיני\u0004 — ראיה היא ש\u0003לישראל נאמרה ולא לבני נח,\u0004 שאם מצוה זו גם לבני נח היא, לשם מה לחזור עליה בסיני?!","ומשיבים: דבר זה נלמד \u0003מדאיתני\u0004 \u0005[מ\u0006מה \u0005שנשנית]\u0006 \u0003עבודה זרה\u0004 גם \u0003בסיני, ואשכחן\u0004 \u0005[ומצאנו]\u0006 ש\u0003ענש\u0004 הקדוש ברוך הוא \u0003גוים עילווה\u0004 \u0005[עליה],\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכל מצוה שנשנית — \u0003לזה ולזה נאמרה\u0004 ולא לישראל בלבד.","עוד אמר החכם בברייתא כי מצוה שנאמרה \u0003לבני נח ולא נשנית בסיני\u0004 — ראיה היא ש\u0003לישראל נאמרה ולא לבני נח.\u0004 ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מ\u0004כיון ש\u0003לא נישנית בסיני\u0004 מסתבר כי \u0003לבני נח נאמרה ולא לישראל!\u0004 ומשיבים: \u0003ליכא מידעם\u0004 \u0005[אין דבר]\u0006 ש\u0003לישראל שרי\u0004 \u0005[מותר]\u0006 \u0003ולגוי אסור.\u0004","ומקשים: \u0003ו\u0004כי \u0003לא\u0004 מצאנו כדבר הזה? \u0003והרי יפת תואר,\u0004 כלומר, ההיתר לקחת שבויית מלחמה בעל כרחה, נאמרה רק לישראל, והיא אסורה לגויים משום גזל! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 הטעם \u0003משום דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני כיבוש נינהו\u0004 \u0005[הם]\u0006 כלומר, לא ניתנה רשות לגויים לעשות מלחמה לשם כיבוש, ודין זה ביפת תואר נאמר רק במלחמת כיבוש, ולפיכך הדבר מותר לישראל ואסור לגוי, ולא משום שישראל קדושתו פחותה מגוי.","ומקשים: \u0003והרי\u0004 גזל של \u0003פחות משוה פרוטה\u0004 שאסור לגוי ומותר לישראל! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 לא זה הטעם, אלא \u0003משום דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני מחילה נינהו\u0004 \u0005[הם],\u0006 שאין שייך בהם ענין מחילה על פחות משווה פרוטה, כי בעצם אף גזל של פחות משווה פרוטה גזל הוא, אלא שישראל מוחלים לגזלן, וגוים שאינם מוחלים גם על ערך מועט כזה הריהו להם כשאר גזל.","עוד שנינו בברייתא ש\u0003\"כל מצוה שנאמרה לבני נח ונישנית בסיני לזה ולזה נאמרה\".\u0004"],["ומקשים: \u0003והרי\u0004 מצות \u0003מילה שנאמרה לבני נח, דכתיב\u0004 \u0005[שנאמר]\u0006 לאברהם שהיה מבני נח: \u0003\"ואתה את בריתי תשמר\u0004 אתה וזרעך אחריך לדורותם\u0003\"\u0004 (בראשית יז, ט), \u0003ונשנית בסיני\u0004 לישראל, כאמור \u0003\"וביום השמיני ימול\u0004 בשר ערלתו\u0003\"\u0004 (ויקרא יב, ג), ובכל זאת \u0003לישראל\u0004 בלבד \u0003נאמרה ולא לבני נח!\u0004","ומשיבים: מקרא זה שנשנה בסיני אינו לצורך המצוה עצמה, וכוונתו: הכתוב \u0003ההוא\u0004 \u0003למישרי\u0004 \u0005[להתיר]\u0006 מילה ב\u0003שבת הוא דאתא\u0004 \u0005[שבא],\u0006 שההדגשה היא: \u0003\"ביום\u0004 השמיני \u0003\"\u0004— \u0003ואפילו\u0004 חל \u0003בשבת\u0004, ועל כן אין זה בגדר של נשנית בסיני.","ומקשים עוד: \u0003והרי\u0004 מצות \u0003פריה ורביה שנאמרה לבני נח, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואתם פרו ורבו\u0004 שרצו בארץ ורבו בה\u0003\"\u0004 (בראשית ט, ז), \u0003ונשנית בסיני,\u0004 כאמור: \u0003\"לך אמר להם שובו לכם לאהליכם\"\u0004 (דברים ה, כז), שנאמר לישראל לחזור לנשיהם אחר שנצטוו לפרוש מהן לקראת מתן התורה, ובכל זאת מצות פריה ורביה \u0003לישראל נאמרה ולא לבני נח!\u0004","ומשיבים: הציווי \u0003ההוא\u0004 \"שובו לכם לאהליכם\", לא לעצם מצות פריה ורביה נאמר, אלא כדי ללמדנו \u0003לכל דבר שבמנין\u0004 שנמנה בית דין עליו ואסרו — \u0003צריך מנין אחר להתירו\u0004 במפורש, ואינו בטל גם אם נגמר זמן תוקפה של התקנה, וכתוב זה לשם כך \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 ודין כללי הוא זה, שאין איסור בטל מעצמו ויש צורך בהוראה מיוחדת להתירו, והיה איפוא צורך להתיר מה שנאמר להם קודם לכן \"היו נכונים לשלושת ימים אל תגשו אל אשה\" (שמות יט, טו).","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003כל חדא וחדא נמי נימא\u0004 \u0005[אחת ואחת גם כן נאמר]\u0006 כי \u0003משום מילתא איתני\u0004 \u0005[דבר נשנתה],\u0006 שאפשר לומר גם ששבע מצוות בני נח שנשנו בסיני מפני טעם מיוחד נשנו, ויהיו בני נח פטורים מכולן!","ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך אמר\u0006 התנא\u0005]:\u0006 \u0003אזהרה מיהדר ומיתנא בה\u0004 \u0005[לחזור ולשנות אותה]\u0006 \u0003למה לי?\u0004 שנאמר הדבר בסיני בלשון ציווי בלבד כגון \"לא תרצח... לא תנאף\", וניכר הדבר שבאו הדברים כציווי ולא לשום צורך אחר.","עוד שנינו בברייתא: \u0003ו\u0004אנו \u0003אין לנו אלא גיד הנשה בלבד, ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהודה.\u0004 ומקשים: \u0003הני נמי\u0004 \u0005[אלה גם כן]\u0006 \u0003לא איתני\u0004 \u0005[נשנו],\u0006 שהרי כפי שהסברנו מצוות אלה, פריה ורביה ומילה, לא נשנו בסיני, אלא נזכרו לצרכים אחרים, ואם כן יש יותר ממצוה אחת שנאמרה לבני נח אך למעשה לישראל בלבד נאמרה.","ומשיבים: \u0003הני איתני לשום מילתא בעלמא\u0004 \u0005[אלה הוזכרו לאיזה דבר בכלל],\u0006 שמכל מקום הוזכרה המצוה שנית, פריה ורביה ומילה, \u0003הא\u0004 \u0005[זו]\u0006 איסור אכילת גיד הנשה \u0003לא איתני\u0004 \u0005[נשנתה]\u0006 \u0003כלל,\u0004 ולא נזכרה אלא בספר בראשית.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 מצות \u0003מילה מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לאברהם הוא דקא מזהר ליה רחמנא\u0004 \u0005[שהזהיר אותו ה'],\u0006 שאמר לו: \u0003\"ואתה את בריתי תשמר אתה וזרעך אחריך לדרתם\"\u0004 (בראשית יז, ט), \u0003אתה וזרעך\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003איניש אחרינא\u0004 \u0005[אדם אחר]\u0006 — \u0003לא,\u0004 שמצוה זו מתחילתה לא נתייחדה אלא לזרע אברהם, ולא לכל בני נח.","ומקשים: \u0003אלא מעתה בני ישמעאל לחייבו\u0004 \u0005[שיהיו חייבים]\u0006 במילה בהיותם אף הם מזרע אברהם! ומשיבים, נאמר: \u0003\"כי ביצחק יקרא לך זרע\"\u0004 (בראשית כא, יב), כלומר, בני ישמעאל אינם קרויים זרע אברהם.","ומקשים: אם אמנם זרע ישמעאל אינם נחשבים כזרע אברהם, לפחות \u0003בני עשו\u0004 שהוא בן יצחק \u0003לחייבו\u0004 \u0005[שיהיו חייבים]\u0006 במילה! ומשיבים: נאמר \u0003\"ביצחק\"\u0004 — ללמד: חלק מתוך ביתו \u0003ולא כל\u0004 זרע \u0003יצחק,\u0004 למעט את זרע עשיו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אושעיא: אלא מעתה בני קטורה לא לחייבו\u0004 \u0005[יהיו חייבים]\u0006 במילה? ומשיבים: \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003ר' יוסי בר אבין, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003ר' יוסי בר חנינא:\u0004 מה שנאמר \u0003\"\u0004וערל זכר אשר לא ימול את בשר ערלתו ונכרתה הנפש ההיא מעמיה \u0003את בריתי הפר\"\u0004 (בראשית יז, יד) — כוונתו \u0003לרבות\u0004 את \u0003בני קטורה\u0004 שחייבים במילה, מפני שיש להם ריבוי מיוחד בכתוב.","\u0003אמר רב יהודה אמר רב: אדם הראשון לא הותר לו בשר לאכילה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"ויאמר אלהים הנה נתתי לכם את כל עשב זורע זרע אשר על פני כל הארץ ואת כל העץ אשר בו פרי עץ זורע זרע \u0003לכם יהיה לאכלה. ולכל חית הארץ\u0004 ולכל עוף השמים ולכל רומש על הארץ אשר בו נפש חיה את כל ירק עשב לאכלה ויהי כן\" (בראשית א, כט–ל), ומשמעו — רק הצמחים יהיו לכם, אבל \u0003לא חית הארץ לכם.\u0004","\u0003וכשבאו בני נח, התיר להם\u0004 לאכול בשר, \u0003שנאמר: \"\u0004כל רמש אשר הוא חי לכם יהיה לאכלה \u0003כירק עשב נתתי לכם את כל\"\u0004 (בראשית ט, ג). \u0003יכול\u0004 הותר הכל ו\u0003לא יהא\u0004 איסור \u0003אבר מן החי נוהג בו\u0004 בבשר זה? — \u0003תלמוד לומר: \"אך בשר בנפשו דמו לא תאכלו\"\u0004 (בראשית ט, ד). \u0003יכול\u0004 יהא אסור אבר מן החי \u0003אף לשרצים?\u0004 — \u0003תלמוד לומר: \"אך\"\u0004 לשון מיעוט וחלוקה, שאינם בכלל זה.","ושואלים: \u0003ומאי\u0004 \u0005[ומהו]\u0006 \u0003תלמודא\u0004 \u0005[הלימוד],\u0006 מה הראיה שהשרצים הם אלה המוצאים מן הכלל, ולא דבר אחר? \u0003אמר רב הונא:\u0004 נאמר \u0003\"דמו\",\u0004 וכוונתו: \u0003מי שדמו חלוק מבשרו\u0004 ויש דין מיוחד לדמו ודין מיוחד לבשרו, \u0003יצאו שרצים שאין דמם חלוק מבשרם\u0004 ואין מחלקים ביניהם בהלכה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה שנאמר באדם הראשון \u0003\"ורדו בדגת הים\u0004 ובעוף השמים ובכל חיה הרומשת על הארץ\u0003\"\u0004 (בראשית א, כח), \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003לאכילה,\u0004 שירדו בהם — שיוכלו לאכלם? ודוחים: \u0003לא,\u0004 הכוונה ברדייה זו היא \u0003ל\u0004עשיית \u0003מלאכה\u0004 על ידם.","ומקשים: \u0003ו\u0004כי \u0003דגים בני מלאכה נינהו\u0004 \u0005[הם],\u0006 האם אפשר לעשות מלאכה בדגים? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 אפשר, ו\u0003כ\u0004דברי החכם \u0003רחבה, דבעי\u0004 \u0005[ששאל]\u0006 \u0003רחבה\u0004 שאלה זו: מי ש\u0003הנהיג\u0004 עגלה שרתומים בה \u0003עיזא\u0004 \u0005[עז]\u0006 \u0003ושיבוטא\u0004 (מין דג) יחד, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 האם עובר הוא משום נוהג בכלאים או לא? ולענייננו משמע שיש דרך, רחוקה אמנם, של שימוש בדגי הים למלאכה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 נאמר שם \u0003\"\u0004ורדו בדגת הים \u0003ובעוף השמים\", מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003לאכילה?\u0004 ודוחים: \u0003לא, למלאכה.\u0004","ותוהים: \u0003ו\u0004כי \u0003עופות בני מלאכה נינהו\u0004 \u0005[הם],\u0006 האם יכולים לעשות בהם מלאכה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כדבעי\u0004 \u0005[כפי ששאל]\u0006 \u0003רבה בר רב הונא\u0004 שאלה זו: \u0003דש\u0004 את גורנו \u0003באווזין ותרנגולין, ל\u0004שיטת \u0003ר' יוסי בר' יהודה\u0004 הסבור שאיסור \"לא תחסם שור בדישו\" הוא דווקא בשור, וצריך דווקא לעשות עבודה ברגליו ובידיו יחד, וכן הדין גם בפועל, והיתה השאלה: \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם אווזים ותרנגולים שיש להם רק רגלים, נכללים בציווי של \"לא תחסם שור בדישו\"? ובכל אופן מאותו דיון למדנו שאפשר לעשות מלאכה גם בעופות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה שנאמר: \"ורדו... \u0003ובכל חיה הרמשת על הארץ\",\u0004 ואלה ודאי שאין עושים מלאכה ולאכילה נועדו! ומשיבים: הקטע \u0003ההוא\u0004 בפסוק \u0003לאתויי\u0004 \u0005[להביא]\u0006 את ה\u0003נחש הוא דאתא\u0004 \u0005[שבא],\u0006 שהיה ראוי מתחילת בריאתו למלאכה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן מנסיא אומר: חבל על שמש גדול שאבד מן העולם, שאלמלא לא נתקלל נחש\u0004 שילך על גחונו, \u0003כל אחד ואחד מישראל היו מזדמנין לו שני נחשים טובים\u0004 שהיו נמצאים בביתו, \u0003אחד\u0004 היה \u0003משגרו\u0004 (שולחו) \u0003לצפון ואחד משגרו לדרום, להביא לו סנדלבונים\u0004 (מין אבן טובה) \u0003ואבנים טובות ומרגליות. ולא עוד אלא שמפשילין רצועה תחת זנבו\u0004 כרתמה לבהמה, \u0003ומוציא בה עפר לגנתו ולחורבתו\u0004 כשם שמשתמש בשאר בהמות. הרי ראוי היה נחש להשתמש בו, ועליו נאמר \"ורדו\", ולא נמצאה כל ראיה שלרדות כולל אכילה.","על הדעה שאדם הראשון לא הותר בבשר \u0003מיתיבי\u0004 \u0005[מקשים],\u0006 \u0003היה ר' יהודה בן תימא אומר: אדם הראשון מיסב בגן עדן היה, והיו מלאכי השרת צולין לו בשר ומסננין לו יין. הציץ בו נחש וראה בכבודו, ונתקנא בו,\u0004 ומשום כך הסיתו וגרם לגירושו. ומכאן נראה שהיה אוכל בשר! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בבשר היורד מן השמים\u0004 שנברא דרך נס, ואינו בשר בעלי חיים כלל.","ומקשים: \u0003מי איכא\u0004 \u0005[האם יש]\u0006 \u0003בשר היורד מן השמים?!\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]:\u0006 ש\u0003ר' שמעון בן חלפתא הוה קאזיל באורחא\u0004 \u0005[היה הולך בדרך],\u0006 \u0003פגעו בו הנך אריותא דהוו קא נהמי לאפיה\u0004 \u0005[פגשו בו אותם אריות שהיו נוהמים כנגדו]\u0006 לאוכלו, \u0003אמר: \"הכפירים שאגים לטרף\u0004 ולבקש מאל אכלם\u0003\"\u0004 (תהלים קד, כא) וראויים הם לקבל אוכל. \u0003נחיתו ליה תרתי אטמתא\u0004 \u0005[ירדו לו\u0006 משמים \u0005שתי ירכיים]\u0006 של בהמה, \u0003חדא\u0004 \u0005[אחת]\u0006 מירכיים אלה \u0003אכלוה\u0004 האריות \u0003וחדא שבקוה\u0004 \u0005[ואחת השאירו].\u0006 \u0003איתיה ואתא לבי מדרשא\u0004 \u0005[הביאה,\u0006 את הירך הזו, \u0005ובא לבית המדרש],\u0006 \u0003בעי עלה\u0004 \u0005[שאל עליה]:\u0006 \u0003דבר טמא הוא זה, או דבר טהור? אמרו ליה\u0004 \u0005[לו]:\u0006 ודאי טהור הוא, כי \u0003אין דבר טמא יורד מן השמים.\u0004","אגב מעשה זה מסופר כי \u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' זירא מר' אבהו:\u0004 ואם \u0003ירדה לו דמות חמור, מהו?\u0004 האם יהא מותר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יארוד נאלא\u0004 \u0005[עוף שוטה]!\u0006 \u0003הא אמרי ליה\u0004 \u0005[הרי אמרו לו]\u0006 כבר: \u0003אין דבר טמא יורד מן השמים,\u0004 ושואל אתה על דבר שלא יתכן שיהיה.","בברייתא היסודית בדיני בני נח נאמר ש\u0003ר' שמעון אומר\u0004 ש\u0003אף על הכישוף\u0004 נצטוו בני נח. ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון? דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"מכשפה לא תחיה\"\u0004 (שמות כב, יז), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בסמוך לו: \u0003\"כל שכב עם בהמה מות יומת\"\u0004 (שמות כב, יח), ללמדנו: \u0003כל שישנו בכלל\u0004 איסור \u0003\"כל שכב עם בהמה\"\u0004 וגוים אף הם בכלל זה — \u0003ישנו בכלל \"מכשפה לא תחיה\".\u0004","שנינו בברייתא ש\u0003ר' אלעזר אומר\u0004 שחייבים בני נח \u0003אף על הכלאים.\u0004 ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006 \u0003אמר שמואל,\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"את חקתי תשמרו\u0004 בהמתך לא תרביע כלאים שדך לא תזרע כלאים\u0003\"\u0004 (ויקרא יט, יט). \"את חקתי\" — בא ללמד \u0003חוקים שחקקתי לך כבר,\u0004 כלומר, מצוות שניתנו בשעתן לבני נח, ומה הן? — \u0003\"בהמתך לא תרביע כלאים שדך לא תזרע כלאים\".\u0004","ובפירוט הדברים: \u0003מה בהמתך\u0004 הכוונה לאיסור כלאים \u0003בהרבעה\u0004 ולא בחרישה יחד, \u0003אף שדך\u0004 נאסר \u0003בהרכבה\u0004 של צמח על שאינו מינו, שהיא מעין הרבעה, אך לא נאסר לגויים לזרוע מינים שונים יחד. ועוד: \u0003מה\u0004 איסור הרבעת \u0003בהמתך\u0004 חל \u0003בין בארץ בין בחוצה לארץ,\u0004 שאין האיסור קשור למקום מסויים, \u0003אף\u0004 איסור \u0003שדך\u0004 חל \u0003בין בארץ בין בחוצה לארץ.\u0004","ומקשים: \u0003אלא מעתה\u0004 הלא גם בדינים אחרים נאמר \u0003\"ושמרתם את חקתי ואת משפטי\"\u0004 (ויקרא יח, ה), ומדוע לא נאמר גם בהם \u0003חקים שחקקתי לך כבר,\u0004 ויהיו בני נח חייבים בכל התורה כולה!","ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 נאמר \u0003\"ושמרתם את חקתי\",\u0004 משמעו \u0003דהשתא\u0004 \u0005[של עכשיו],\u0006 שאני נותן לכם עכשיו, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בדין כלאים נאמר \u0003\"את חקתי תשמרו\",\u0004 כלומר, \u0003חקים דמעיקרא\u0004 \u0005[שהיו מתחילה]\u0006 \u0003תשמרו\u0004 בעתיד.","לאחר בירור דברים בדיני בני נח שבים אל ההלכות האמורות במשנתנו בענין דיני מברך ה'. ששנינו במשנה ש\u0003אמר ר' יהושע בן קרחה:\u0004 בכל יום שעוסקים בדין זה שואלים ומתדיינים עם העדים בכינוי כדי שלא תישמע קללת השם אלא בכינוי דברים, וכגון בלשון \"יכה יוסי את יוסי\", שיוסי יש בו ארבע אותיות כמו שם ה'.","\u0003אמר רב אחא בר יעקב: אינו חייב עד שיברך\u0004 (יקלל) \u0003שם בן ארבע אותיות\u0004 (ה־ו־י־ה), \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 אם קלל שם \u0003בן שתי אותיות\u0004 (י־ה) \u0003דלא\u0004 \u0005[שאינו]\u0006 חייב מיתה עליו.","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 הלא בלשון \u0003\"יכה יוסי את יוסי\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 ומשמעו: שם בן ארבע אותיות, כעין \"יוסי\"! ודוחים: משם אין ראיה גמורה, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מילתא בעלמא\u0004 \u0005[דבר סתם]\u0006 \u0003הוא דנקט\u0004 \u0005[שתפס]\u0006 כדוגמה, ואינו דווקא שם בן ארבע אותיות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שרק על שם בן ארבע אותיות חייב.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי כך \u0003אמר רב אחא בר יעקב: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003שם בן ארבע אותיות נמי\u0004 \u0005[גם כן]\u0006 \u0003שם הוא\u0004 וחייבים עליו, ואין צריך שישמיע את השם המפורש שיש בו ארבעים ושתים אותיות.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 והלא \u0003\"יכה יוסי את יוסי\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 ודוחים: משם אין ראיה גמורה, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 אינו חייב \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003שם רבה\u0004 \u0005[גדול,\u0006 השם המפורש\u0005]\u0006 שהוא מקלל, \u0003ומילתא בעלמא\u0004 \u0005[ודבר סתם]\u0006 \u0003הוא דנקט\u0004 \u0005[שתפס]\u0006 כדוגמה, ואין להביא ממנה ראיה למעשה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שמדוייקת היא המשנה.","שנינו במשנה: \u0003נגמר הדין\u0004 והיו צריכים לשמוע מפי העד את ברכת השם, היו כולם עומדים.","ושואלים: דין זה שיהיו \u0003עומדין מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר ר' יצחק בר אמי:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ואהוד בא אליו והוא ישב בעלית המקרה אשר לו לבדו ויאמר אהוד דבר אלהים לי אליך ויקם מעל הכסא\"\u0004 (שופטים ג, כ). \u0003והלא דברים קל וחומר: ומה עגלון מלך מואב, שהוא גוי ולא ידע\u0004 את השם המפורש \u0003אלא בכינוי\u0004 — \u0003עמד\u0004 מפני הכבוד, \u0003ישראל\u0004 השומע את ה\u0003שם המפורש\u0004 — \u0003על אחת כמה וכמה.\u0004 עוד שנינו במשנה שהשומעים קורעים בגדיהם.","ושואלים: \u0003דין זה שיהיו\u0004 \u0003קורעין מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבא אליקים בן חלקיה\u0004 אשר על הבית \u0003ושבנא הספר ויואח בן אסף המזכיר אל חזקיהו קרועי בגדים ויגידו לו את דברי רבשקה\"\u0004 (מלכים ב' יח, לז), למדנו מכאן שכיון ששמעו דברי גידוף מפי רבשקה היו חייבים לקרוע בגדיהם.","שנינו במשנה שקורעים ו\u0003לא מאחין.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 הלכה זו?","\u0003אמר ר' אבהו: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"קריעה\" \"קריעה\". כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בשומעי הקללה \u0003\"קרועי בגדים\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"ואלישע ראה והוא מצעק אבי אבי רכב ישראל ופרשיו ולא ראהו עוד ויחזק בבגדיו ויקרעם לשנים קרעים\"\u0004 (מלכים ב' ב, יב), \u0003ממשמע שנאמר \"ויקרעם לשנים\" איני יודע שהן קרעים? ומה תלמוד לומר: \"קרעים\"?\u0004 — \u0003מלמד שהן קרועים לעולם,\u0004 ואין מאחים אותם איחוי גמור אלא רק תופרים אותם תפירה מועטת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד השומע\u0004 את הקללה בעצמו \u0003ואחד שומע מפי שומע\u0004 — \u0003חייב לקרוע\u0004 בגדיו. \u0003והעדים אין חייבין לקרוע,\u0004 לפי \u0003שכבר קרעו בשעה ששמעו\u0004 מפי המקלל עצמו.","ושואלים: \u0003וכי\u0004 \u0005[ואם]\u0006 \u0003קרעו בשעה ששמעו מאי הוי\u0004 \u0005[מה יש]?\u0006 \u0003הא קא שמעי השתא\u0004 \u0005[הרי שומעים הם\u0006 גם \u0005עכשיו]\u0006 את הקללה! ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר שחייבים הם לקרוע שנית, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויהי כשמע המלך חזקיהו את דברי רבשקה ויקרע את בגדיו\"\u0004 (מלכים ב' יט, א) — \u0003המלך חזקיהו קרע\u0004 בגדיו, \u0003והם\u0004 ששמעו כבר פעם אחת \u0003לא קרעו\u0004 שנית.","\u0003אמר רב יהודה אמר שמואל: השומע אזכרה\u0004 של השם בדרך גידוף \u0003מפי הגוי אינו חייב לקרוע, ואם תאמר:\u0004 הלא כששמעו מפי \u0003רבשקה\u0004 קרעו על הזכרת השם מפיו? משמע לכאורה שקורעים בשמיעה מפי גוי! אלא רבשקה \u0003ישראל משומד היה,\u0004 ולכן קרעו.","\u0003ואמר רב יהודה אמר שמואל: אין קורעין אלא\u0004 \u0003על\u0004 שמיעה של קללת \u0003שם המיוחד בלבד, לאפוקי\u0004 \u0005[להוציא]\u0006 שמיעה של קללת \u0003כינוי\u0004 מן הכינויים של ה', ש\u0003לא\u0004 קורעים על הזכרתם.","\u0003ופליגי\u0004 \u0005[וחלוקים]\u0006 דברים אלה על \u0003ר' חייא בתרוייהו\u0004 \u0005[בשניהם],\u0006 כלומר, בשני הנושאים, ש\u0003אמר ר' חייא: השומע אזכרה בזמן הזה אינו חייב לקרוע, שאם אי\u0004 (אין) \u0003אתה אומר כן נתמלא כל הבגד קרעים.\u0004","ומעתה נברר: \u0003ממאן\u0004 \u0005[ממי]\u0006 שומע הוא אזכרות אלה שעליהן אמר ר' חייא ש\"נתמלא כל הבגד קרעים'\"? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא שומע \u0003מישראל, מי פקירי כולי האי\u0004 \u0005[וכי מופקרים\u0006 הם \u0005כל כך]\u0006 לבזות את השם? \u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שמדובר כאן בשמיעה מ\u0003גוי.\u0004 ועוד נברר: \u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שמקללים ב\u0003שם המיוחד, מי גמירי\u0004 \u0005[האם למדו\u0006 אותו\u0005]?\u0006 והלא אינם יודעים שם זה כלל! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שמקללים \u0003בכינוי,\u0004","\u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי אמנם \u0003בזמן הזה הוא\u0004 ש\u0003לא\u0004 חייב בקריעה, \u0003הא מעיקרא\u0004 \u0005[הרי מתחילה\u0006 מעיקר הדין\u0005]\u0006 \u0003חייב\u0004 בקריעה, הרי שלדעת ר' חייא קורעים על אזכרה מפי גוי, ועל אזכרה בכינוי. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","שנינו במשנה שהעד \u0003השני\u0004 אינו חוזר על הקללה ששמע אלא \u0003אומר \"אף אני כמוהו\u0004 שמעתי \u0003\".\u0004 \u0003אמר ריש לקיש: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי האומר \u0003\"אף אני כמוהו\"\u0004 בלבד, מן התורה די בכך ו\u0003כשר\u0004 בעדות, הן \u0003בדיני ממונות ו\u0004הן \u0003בדיני נפשות, ומעלה הוא דעביד רבנן\u0004 \u0005[שעשו חכמים]\u0006 שתיקנו תקנה שיצטרך כל עד לספר את דברי עדותו לחוד, ובפירוט. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003כיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות כן, שאין ראוי לחזור על דברי גנאי פעמים אחדות, \u0003אוקמוה רבנן אדאורייתא\u0004 \u0005[העמידו חכמים\u0006 את הדבר \u0005על\u0006 דין \u0005תורה]\u0006 ואין צורך לחזור בצורה מפורטת על הדבר.","\u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שדבר עדות של \"אף אני כמוהו\" \u0003פסול\u0004 מן התורה, וכי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003משום דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 לעשות אחרת \u0003קטלינן לגברא\u0004 \u0005[הורגים אנו את האיש]\u0006 בלא עדות גמורה זו? אלא הרי זו הוכחה שעדות כזו מספיקה מדין תורה.","עוד שנינו במשנה ש\u0003השלישי אומר \"אף אני כמוהו\".\u0004 ומעירים: \u0003סתמא\u0004 \u0005[סתם]\u0006 זה ששנה במשנה את דבריו אלו, \u0003כר' עקיבא\u0004 שנה, \u0003דמקיש\u0004 \u0005[שמשווה]\u0006 לכל עדות \u0003שלשה\u0004 עדים \u0003לשנים,\u0004 ולכן מדגיש גם כאן את המקרה של שלושה עדים שצריכים להעיד אותה עדות ממש."],["\u0003העובד עבודה זרה\u0004 — נידון בסקילה, \u0003אחד העובד ואחד המזבח\u0004 (שוחט לה קרבנות), \u0003ואחד המקטר\u0004 קטורת לפניה, \u0003ואחד המנסך\u0004 לפניה יין וכדומה, \u0003ואחד המשתחוה\u0004 לה, \u0003ואחד ה\u0004אומר לו שהוא \u0003מקבלו עליו לאלוה, והאומר לו: \"אלי אתה\".\u0004","\u0003אבל המגפף\u0004 (מחבק) \u0003והמנשק, והמכבד\u0004 (מנקה), \u0003והמרבץ\u0004 מים לפניו, \u0003והמרחץ\u0004 את הפסל, \u0003והסך\u0004 אותו, \u0003והמלביש, והמנעיל\u0004 אותו — \u0003עובר ב\"לא תעשה\"\u0004 בלבד. \u0003הנודר בשמו\u0004 או \u0003המקיים\u0004 (מאמת דבריו בשבועה) \u0003בשמו\u0004 — \u0003עובר ב\"לא תעשה\".\u0004","\u0003הפוער עצמו\u0004 (עושה צרכיו) \u0003ל\u0004פני \u0003בעל פעור\u0004 — \u0003זו היא עבודתה\u0004 וחייב על כך, \u0003הזורק אבן למרקוליס\u0004 — \u0003זו היא עבודתה\u0004 וחייב עליה, אף על פי שהוא כדרך בזיון.","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד העובד\"?\u0004 והלא הכל בכלל זה, ומה הוסיפה לנו המשנה בהגדרה זו?","\u0003אמר ר' ירמיה, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אחד העובד כדרכה\u0004 באופן בו עבודה זרה זו נעבדת, \u0003ואחד המזבח, ואחד המקטר, ואחד המנסך ואחד המשתחוה\u0004 — \u0003ואפילו\u0004 היתה עבודה זו \u0003שלא כדרכה,\u0004 שאין דרך לעבוד עבודה זרה זו בכך, הרי זה קרוי עבודה זרה משום שהוא מהאופנים שבהם עובדים את ה' במקדש.","ומקשים: \u0003וליחשוב נמי\u0004 \u0005[ושנחשוב גם כן]\u0006 \u0003זורק\u0004 דם לפניו, שאף היא מעבודות המקדש! \u0003אמר אביי: זורק היינו\u0004 \u0005[זהו]\u0006 \u0003מנסך\u0004 השנוי במשנה, שבמהותם הם עבודה אחת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בל אסיך נסכיהם מדם\"\u0004 (תהלים טז, ד), הרי שזריקת דם אף היא קרויה \"נסך\".","לעצם ההלכה שואלים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שחייבים על עבודות אלה גם כשהן שלא כדרכה?","\u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הפסוק \"זובח לאלהים יחרם בלתי לה' לבדו\" (שמות כב, יט): \u0003אילו נאמר \"זבח יחרם\", הייתי אומר\u0004 כי \u0003בזובח קדשים בחוץ הכתוב מדבר,\u0004 שהכתוב מזהיר על עבירה חמורה שיש בהקרבה, שכבר הזהיר הכתוב על כך. על כן \u0003תלמוד לומר: \"לאלהים\",\u0004 כלומר, לאלהים אחרים, ומשמע: \u0003בזובח לעבודה זרה הכתוב מדבר.\u0004","\u0003אין לי אלא בזובח\u0004 בלבד, \u0003מקטר ומנסך\u0004 לעבודה זרה \u0003מניין\u0004 שאף הוא חייב? — \u0003תלמוד לומר: \"בלתי לה' לבדו\",\u0004 ללמד: \u0003ריקן,\u0004 כלומר, ייחד את \u0003העבודות כולן לשם המיוחד.\u0004","\u0003לפי שיצאה זביחה\u0004 מכלל כל העבודות ופורשה בפסוק זה, ובכך היא באה ללמד \u0003לידון בעבודות פנים,\u0004 אותן עבודות שעושים בפנים בתוך בית המקדש, שנלמדות כולן מן הזביחה ורק הן הן שאסור לעבוד כדוגמתן לעבודה זרה. \u0003מניין לרבות השתחואה,\u0004 שאינה מעבודות הקודש המיוחדות, שהמשתחוה לעבודה זרה חייב מיתה?","— \u0003תלמוד לומר: \"וילך ויעבד אלהים אחרים וישתחו להם\"\u0004 (דברים יז, ג), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \u0003\"והוצאת את האיש ההוא\u0004 או את האשה ההיא אשר עשו את הדבר הרע הזה אל שעריך את האיש או את האשה וסקלתם באבנים ומתו","\u0003\"\u0004(דברים יז, ה). \u0003עונש\u0004 להשתחויה לאל זר \u0003שמענו, אזהרה\u0004 לאסור את הדבר \u0003מניין?\u0004 היכן נאמר שדבר זה אסור? — \u0003תלמוד לומר: \"כי לא תשתחוה לאל אחר\"\u0004 (שמות לד, יד),","\u0003יכול שאני מרבה\u0004 בכלל החייבים מיתה גם את \u0003המגפף והמנשק והמנעיל?\u0004 — \u0003תלמוד לומר: \"זבח\u0004 לאלהים יחרם","\u0003\",\u0004 שהרי \u0003זביחה בכלל\u0004 כל עבודות \u0003היתה, ולמה יצאה\u0004 והזכירה הכתוב במיוחד? לא יצאה אלא \u0003להקיש\u0004 \u0005[להשוות]\u0006 \u0003אליה ולומר לך: מה זביחה מיוחדת שהיא עבודת פנים\u0004 שעושים כמוה בתוך המקדש \u0003וחייבין עליה מיתה, אף כל שהיא עבודת פנים וחייבין עליה מיתה,\u0004","\u0003יצאה השתחואה לידון בעצמה\u0004 שיש לה דין מיוחד, שהרי אינה עבודת פנים, ובכל זאת חייבים עליה כאשר עשאוה לעבודה זרה. ו\u0003יצאה זביחה לידון על הכלל כולו,\u0004 שכל דבר שאינו נעשה בפנים המקדש אינו קרוי עבודה אף לגבי עבודה זרה.","ומעתה מבררים את פרטי הדברים במדרש הלכה זה, \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: \u0003הייתי אומר\u0004 כי \u0003בזובח קדשים בחוץ הכתוב מדבר.\u0004 ותוהים: \u0003זובח קדשים בחוץ\u0004 הלא חייב \u0003כרת הוא\u0004 (כאמור: \"איש איש... אשר יעלה עולה או זבח. ואל פתח אהל מועד לא יביאנו לעשות אותו לה' ונכרת האיש ההוא מעמיו\". ויקרא יז, ח–ט) ולא מיתה (\"יחרם\")!","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003כי אתרו ביה\u0004 \u0005[כאשר התרו בו]\u0006 שלא לזבוח בחוץ — חייב \u0003קטלא\u0004 \u0005[מיתה],\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אתרו ביה\u0004 \u0005[התרו בו]\u0006 — חייב רק \u0003כרת,\u0004 ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במדרש זה שהמקריב קדשים בחוץ אינו נענש בידי אדם גם אם התרו בו. בברייתא היתה הנחה כי איסור זביחה שנתפרש בא ללמד על כל העבודות, ואיסור השתחואה הוא יוצא דופן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי: אימא\u0004 \u0005[אמור,\u0006 הבן\u0005]\u0006 כך את המקראות: \u0003יצאה השתחואה ללמד על הכלל כולו,\u0004 שכל עבודה שיש בה דבר כבוד תהא מחייבת מיתה, ולא דווקא העבודות הנעשות בתוך המקדש.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003זובח\u0004 שנתפרש במקרא \u0003למה לי?\u0004 אפשר לומר כי בא ללמד דבר \u0003לגופיה\u0004 \u0005[לגופו],\u0006 ולאיזה ענין? — ש\u0003מחשבין מעבודה לעבודה,\u0004 כגון השוחט בהמה על מנת להקריבה לעבודה זרה, לחייבו על שחיטה זו.","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בכך אמוראים: \u0003השוחט בהמה\u0004 על מנת \u0003לזרוק דמה לעבודה זרה\u0004 או \u0003להקטיר חלבה לעבודה זרה,\u0004 \u0003ר' יוחנן אמר:\u0004"],["\u0003אסורה\u0004 משום שמחשבים מעבודה לעבודה, וכיון שבשעת שחיטה התכוון להשתמש בבהמה אחר כך לצורך עבודה זרה, הרי זה אוסר אף את השחיטה, כפי שהדבר בעבודות המקדש בכיוצא בזה — פוסל. \u0003וריש לקיש אמר: מותרת.\u0004","ומעירים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן\u0004 שלומד את ההלכה שמחשבים מעבודה לעבודה ממקור אחר, ולכן הפסוק ב\"זובח\" מיותר, ולכן יש ללמוד ממנו לכלל העבודות, האסורות להיעשות לעבודה זרה, כפי שנאמר בברייתא. \u0003אלא לריש לקיש בעי קרא\u0004 \u0005[צריך\u0006 את \u0005הכתוב]\u0006 לענין זה שמחשבים מעבודה לעבודה, ויש איפוא דרך להבין את הפסוקים בצורה הפוכה ממדרש ההלכה שבברייתא.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ו\u0004כי \u0003לר' יוחנן לא בעי קרא\u0004 \u0005[אין צריך כתוב]\u0006 לזה? והלא \u0003עד כאן לא\u0004 שמענו כי \u0003קא אסר\u0004 \u0005[אסר]\u0006 \u0003ר' יוחנן אלא\u0004 רק את ה\u0003בהמה,\u0004 שלדעתו בהמה זו נידונה בשל המחשבה כקרבן לעבודה זרה ונאסרת בהנאה. \u0003אבל גברא\u0004 \u0005[האיש]\u0006 שעשה כן \u0003לא בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא. ו\u0004אם כן אף לדעת ר' יוחנן \u0003אתא קרא לחיובי גברא לקטלא\u0004 \u0005[בא הכתוב\u0006 ב\"זובח\" \u0005לחייב\u0006 את \u0005האיש במיתה].\u0006 ופסוק זה אינו מיותר, שמלמד לענין \"מחשבין\".","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על קושיית רבא בר רב חנן \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: ו\u0004אפילו \u0003ל\u0004דעת \u0003ריש לקיש מי בעי קרא\u0004 \u0005[האם צריך כתוב]\u0006 לחייב אדם על שחיטה זו? שהרי \u0003עד כאן לא\u0004 שמענו כי \u0003קא שרי\u0004 \u0005[התיר]\u0006 \u0003ריש לקיש אלא בהמה,\u0004 שלדעתו הבהמה אינה נאסרת בכך. \u0003אבל גברא בר קטלא\u0004 \u0005[האיש\u0006 ודאי \u0005בן מוות]\u0006 \u0003הוא, מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 בדין של מי ש\u0003משתחוה להר,\u0004 שה\u0003הר מותר\u0004 ואינו נאסר משום השתחואה זו, נענא \u0003ו\u0004בכל זאת ה\u0003עובד\u0004 את ההר חייב מיתה \u0003בסייף!\u0004 אלא ודאי שמן הפסוק \"זובח\" אין צורך שנלמד לעניינו — שמחשבין מעבודה לעבודה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: למאי דקאמר ליה\u0004 \u0005[לפי מה שאמר לו]\u0006 \u0003רבא בר רב חנן לאביי,\u0004 שהציע \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003יצאה השתחואה\u0004 בכתוב \u0003כדי\u0004 \u0003ללמד על הכלל כולו,\u0004 אם כן מה שנאמר: \"השמר לך פן תנקש אחריהם... לאמר \u0003איכה יעבדו\u0004 הגויים האלה את אלהיהם ואעשה כן גם אני\" (דברים יב, ל), ומשמע שחייבים על פולחן עבודה זרה כדרך שרגילים הגויים לעבדה, \u0003למעוטי מאי\u0004 \u0005[למעט,\u0006 להוציא את \u0005מה]\u0006 בא כתוב זה?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003למעוטי\u0004 \u0005[למעט]\u0006 את \u0003הפוער עצמו לזובחים,\u0004 כלומר, אם עושה צרכיו בפני עבודה זרה שעבודתה בזביחה, ואולם דבר זה אינו צריך ללמוד מכאן, שהרי \u0003מהשתחואה נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדבר בדרך זו: \u0003מה השתחואה דרך כיבוד\u0004 היא וחייבים עליה — \u0003אף כל דרך כיבוד\u0004 ולא דבר שיש בו בזיון, שהרי לפי דעת רבא בר רב חנן אפשר ללמוד גם דין זה מהשתחוואה.","\u0003אלא\u0004 בא כתוב זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את \u0003הפוער עצמו למרקוליס,\u0004 שהיא עבודה שלא כדרכה, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ו\u0004אף \u0003עבודתו\u0004 של מרקוליס בדרך \u0003בזיון הוא\u0004 (השלכת אבנים), \u0003אף כל בזיון\u0004 שעושים לפניו ייחשב כעבודתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 בכתוב זה שאין עבודה זרה אלא כדרכה.","ושואלים: \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אליעזר: מניין לזובח בהמה למרקוליס שהוא חייב? שנאמר \"ולא יזבחו עוד את זבחיהם\u0004 \u0003לשעירם\"\u0004 (ויקרא יז, ז),","\u0003אם אינו ענין לכדרכה\u0004 לזובח לעבודה זרה שעבודתה בזביחה, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר\u0006 כבר\u0005]\u0006 \u0003\"איכה יעבדו\", תניהו ענין ל\u0004זובח \u0003שלא כדרכה.\u0004","ומקשים: והרי \u0003שלא כדרכה מהשתחואה נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 שכשם שחייבים על ההשתחואה כך חייבים על כל עבודה שבדרך כבוד!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003בזובח להכעיס\u0004 שלא קיבלו עליו כאלוה, ועושה זאת רק כדי לעבור על דברי תורה, ולמדנו שהעושה כן, עובר על מצות \"לא תעשה\".","מסופר: \u0003רב המנונא אירכסו ליה תורי\u0004 \u0005[אבדו לו שוורים]\u0006 והלך לחפשם. \u0003פגע ביה\u0004 \u0005[פגש בו,\u0006 אותו\u0005]\u0006 \u0003רבה, רמא ליה מתניתין אהדדי\u0004 \u0005[השליך לו,\u0006 הראה לו סתירה, \u0005במשניות מזו על זו]:\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003העובד עבודה זרה\u0004 חייב. ונדייק: \u0003עובד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 ואולם אם רק \u0003אומר\u0004 שיעבוד — \u0003לא\u0004 מתחייב, עד שיעשה מעשה. \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנה אחרת: \u0003האומר \"אעבוד\",\u0004 או \u0003\"אלך ואעבוד\",\u0004 או \u0003\"נלך ונעבוד\"\u0004 חייב כעובד עבודה זרה. והרי שדי בכוונה בלבד כדי לחייב!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 במשנתנו מדובר \u0003באומר \"איני מקבלו עלי\u0004 לאלוה \u0003אלא בעבודה\u0004 כשאעבוד לו","\u0003\",\u0004 ולא קודם לכן, ולכן אינו חייב אלא על המעשה. אך אם התכוון לקבלו — הרי קודם עבודתו מתחייב. \u0003רב יוסף אמר:\u0004 אין צורך בתירוץ זה, וכי \u0003תנאי שקלת מעלמא\u0004 \u0005[\u0006את \u0005התנאים\u0006 ומחלוקותיהם \u0005אתה תקח,\u0006 תוציא \u0005מן העולם]?\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר \"\u0004אלוה אני \u0003בואו ועבדוני\", ר' מאיר מחייב\u0004 את האיש כמסית, \u0003ור' יהודה פוטר.\u0004","ומסייגים: \u0003היכא דפלחו כולי עלמא\u0004 \u0005[כאשר עבדו\u0006 אותו \u0005הכל]\u0006 — \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 שחייבים על כך, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תעשה לך פסל\"\u0004 (שמות כ, ד), ואנו מבינים זאת \"לך\" — לעצמך, כלומר, שאדם אסור לו לעשות את עצמו עבודה זרה. \u0003כי פליגי בדיבורא בעלמא\u0004 \u0005[כאשר חלוקים\u0006 הם הרי זה כשתובע מהם \u0005בדיבור בלבד].\u0006 \u0003ר' מאיר סבר: דיבורא מילתא היא\u0004 \u0005[דיבור דבר הוא],\u0006 ובאמירה בלבד הרי הוא כמסית. \u0003ור' יהודה סבר: דיבורא לאו מילתא היא\u0004 \u0005[דיבור אין הוא דבר],\u0006 ואם כן אותה סתירה במשניות ניתנת להתפרש על פי מחלוקת זו.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 \u0003רב יוסף\u0004 לאחר שהרהר בענין: \u0003לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 של ממש מה \u0005שאמרתי],\u0006 ש\u0003אפילו לר' יהודה בדיבורא נמי חיובי מחייב\u0004 \u0005[בדיבור גם כן מתחייב].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: לעולם אינו חייב עד שיאמר \"אעבוד\",\u0004 או \u0003\"אלך ואעבוד\",\u0004 או \u0003\"נלך ונעבוד\",\u0004 הרי שר' יהודה עצמו מחייב כבר בדיבור, ולאו דווקא במעשה.","ואם כך הדבר, \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005חלוקים הם\u0006 ר' מאיר ור' יהודה\u0005]?\u0006 — \u0003ב\u0004מקרה של אדם, ה\u0003מסית לעצמו\u0004 שיעבדוהו. \u0003ואמרי ליה\u0004 \u0005[ואמרו לו]\u0006 השומעים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003קמיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' מאיר\u0005]\u0006 \u0003סבר: מסית לעצמו שמעי ליה\u0004 \u0005[שומעים לו],\u0006 \u0003ו\"אין\" דקאמרי ליה קושטא\u0004 \u0005[ו\"כן\" שאמרו לו אמת]\u0006 \u0003הוא\u0004 וקיבלוהו עליהם. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה\u0005]\u0006 \u0003סבר: מסית לעצמו לא שמעי ליה\u0004 \u0005[אין שומעין לו],\u0006 שכן \u0003מימר אמרי\u0004 \u0005[אומרים\u0006 הם\u0005]\u0006 בליבם:"],["\u0003מאי שנא איהו מינן דידן\u0004 \u0005[במה שונה הוא מאתנו עצמנו]?\u0006 ודבר שטות הוא שאמר. \u0003ו\"אין\" דקאמרי אחוכי עליה\u0004 \u0005[ו\"כן\" שאמרו לו\u0006 משום ש\u0005צחקו לו],\u0006","\u0003ומתניתין\u0004 \u0005[ומשניותנו]\u0006 שיש בהן סתירה לגבי תוקפה של אמירה בלבד יש להסבירן כך: \u0003כאן\u0004 — \u0003ביחיד הניסת, כאן\u0004 — \u0003ברבים הניסתים. יחיד\u0004 — \u0003לא מימלך וטעי בתריה\u0004 \u0005[אינו נמלך,\u0006 אינו מתייעץ עם אחרים \u0005ו\u0006הוא \u0005טועה אחריו]\u0006 לעבוד עבודה זרה, וכיון שאמר \"כן\" קיבלו על עצמו קבלה גמורה כאלוה וחייב על כך. ואילו \u0003רבים מימלכי\u0004 \u0005[נמלכים\u0006 בדעתם\u0005]\u0006 אחר כך \u0003ולא טעו בתריה\u0004 \u0005[טועים אחריו].\u0006","\u0003אמר רב יוסף: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את החלוקה הזו? — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לגבי מסית לעבודה זרה: \u0003\"לא תאבה לו ולא תשמע אליו\"\u0004 (דברים יג, ט), משמע: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אבה ושמע\u0004 — \u0003חייב\u0004 בעצם ההסכמה לדברים, אף בלא עבודה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי: מי שאני\u0004 \u0005[האם שונה]\u0006 הדין \u0003בין ניסת\u0004 של \u0003רבים,\u0004 כאשר רבים ניסתים \u0003לניסת יחיד? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 על הכתוב \u0003\"כי יסיתך אחיך בן אמך\u0004 או בנך או בתך או אשת חיקך או רעך אשר כנפשך בסתר לאמר נלכה ונעבדה אלהים אחרים\u0003\"\u0004 (דברים יז, ז), אמרו: \u0003אחד יחיד הניסת ואחד רבים הניסתים\u0004 בכלל כתוב זה, \u0003והוציא הכתוב יחיד מכלל\u0004 דינם של \u0003רבים,\u0004 שאין דינו כמותם, \u0003ורבים מכלל יחיד\u0004 שאין דינם כמותו. כיצד?","— הוציא \u0003יחיד מכלל רבים\u0004 — \u0003להחמיר על גופו\u0004 שיהא נדון בסקילה החמורה ולא בסייף, \u0003ולהקל על ממונו\u0004 שאין מחרימים ומשחיתים את ממונו, וכן הוציא","\u0003רבים מכלל יחיד\u0004 — \u0003להקל על גופם\u0004 שהם נידונים במיתת סייף הקלה, \u0003ולהחמיר על ממונם\u0004 ששורפים את העיר ואת כל רכושם.","ועל ידי דיוק בברייתא זו נלמד: \u0003בהא מילתא\u0004 \u0005[בדבר זה]\u0006 בלבד \u0003הוא דשאני\u0004 \u0005[ששונה]\u0006 דין יחיד מרבים, \u0003אבל בכל\u0004 שאר \u0003מילי\u0004 \u0005[הדברים]\u0006 \u0003כי הדדי נינהו\u0004 \u0005[זה כמו זה הם,\u0006 שווים הם זה לזה\u0005]!\u0006","\u0003אלא אמר אביי,\u0004 כך יש להסביר את הסתירה שבמשנה: \u0003כאן\u0004 שנענש רק על עשייה, מדובר \u0003בניסת מפי עצמו,\u0004 כלומר, שלא הסיתו אדם אלא הוא מעצמו נפתה. \u0003כאן בניסת מפי אחרים.\u0004 וטעם ההבדל: אם \u0003מפי עצמו\u0004 ניסת — הריהו יכול להיות \u0003מימלך\u0004 \u0005[נמלך בדעתו,\u0006 מתחרט\u0005],\u0006 אם \u0003מפי אחרים\u0004 — \u0003גריר בתרייהו\u0004 \u0005[נגרר אחריהם]\u0006 ושוב אינו מתחרט. ובמקרה זה כיון שהסכים בדברים — הריהו מתחייב.","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 סברה? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תאבה לו ולא תשמע אליו\"\u0004 (דברים יז, ט), משמע שמדובר כאן בניסת מאדם אחר, ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003אבה ושמע\u0004 — \u0003חייב\u0004 על ההסכמה בלבד.","\u0003רבא אמר: אידי ואידי\u0004 \u0005[זה וזה]\u0006 מדובר \u0003בניסת מפי אחרים,\u0004 ויש לחלק כך: \u0003הא\u0004 \u0005[זה]\u0006 שמתחייב בהסכמה בלבד, מדובר באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המסית את שבחיה של אותה עבודה זרה, שהיא \u0003\"כך אוכלת, כך שותה, כך מטיבה\u0004 לעובדיה, \u0003כך מריעה\u0004 לשאינם עובדיה \u0003\",\u0004 ועל ידי כך נתפס בדבר. \u0003הא\u0004 \u0005[זה]\u0006 שאינו מתחייב באמירה בלבד, מדובר באופן ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"כך אוכלת, כך שותה\"\u0004","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה],\u0006 מוצא לה סמך לדעתי? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004נלכה ונעבדה אלהים אחרים... \u0003מאלהי העמים אשר סביבתיכם הקרבים אליך\u0004 או הרחוקים ממך\u0003\"\u0004 (דברים יג, ז–ח), ויש לשאול: \u0003מה לי קרובים ומה לי רחוקים\u0004 לענין איסור? אלא ודאי \u0003הכי קאמר\u0004 \u0005[כך אומר]\u0006 \u0003לך\u0004 הכתוב על מנת להוציא מלבו של השומע: \u0003מטיבותן\u0004 (מטיבם) \u0003של\u0004 אלילים \u0003קרובים\u0004 שאתה יודע שאין בהם ממש, \u0003אתה למד מה טיבותן של רחוקים,\u0004 שלא תאמין, ואם יספרו לך שיש במקום אחר עבודה זרה שהיא אמיתית, דע כי שקר בדבר.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מוכיח הדבר ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 המסית דברים אלה בשבח עבודה זרה \u0003\"כך אוכלת, כך שותה, כך מטיבה, כך מריעה\".\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הסבר הענין.","\u0003רב אשי אמר\u0004 הסבר אחר לאותה סתירה במשנה: \u0003סיפא\u0004 \u0005[הסוף]\u0006 של המשנה שמחייבים על אמירה בלבד, מדבר \u0003בישראל משומד,\u0004 שכיון שהוא כבר מומר ודאי שבאמירה בלבד קיבל עליו עבודה זרה, ולפיכך מתחייב.","\u0003רבינא אמר: לא זו אף זו קתני\u0004 \u0005[שנה],\u0006 מעיקרו של דבר אין כאן סתירה, אלא ענין של סגנון הוא. כי כך סגנון המשנה, המשמיעה קודם את הדין הפשוט יותר, ולאחר מכן דין שיש בו יתר חידוש, כלומר, לא רק כאשר ממש עובד עבודה זרה, אלא אף כשאומר שילך ויעבוד — מיד מתחייב.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003העובד עבודה זרה מאהבה\u0004 או \u0003מיראה\u0004 של אדם, ולא מתוך אמונה באותה עבודה זרה, מה דינו? \u0003אביי אמר: חייב\u0004 על עבודה זו. \u0003רבא אמר: פטור.\u0004","ומבארים את טעמיהם: \u0003אביי אמר: חייב, דהא פלחה\u0004 \u0005[שהרי עבד אותה].\u0006 \u0003רבא אמר: פטור,\u0004 כי לענין עבודה זרה השיקול העיקרי הוא \u0003אי קבליה עליה\u0004 \u0005[אם קיבלו עליו\u0006 באמת \u0003באלוה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 קיבלו עליו — \u0003לא\u0004 חייב.","אביי הביא הוכחות שונות ונתנו בהן \u0003סימן \"עבד ישתחוה למשיח\".\u0004","\u0003ואמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה],\u0006 את דעתי זו? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003העובד עבודה זרה, אחד העובד\u0004 ואחד המזבח, ואחד המקטר, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 כך יש להבין את כפילות הדברים במשנה: \u0003אחד העובד מאהבה\u0004 של אדם או \u0003מיראה\u0004 של אדם, ואחד העושה מעשה מתוך אמונה בעבודה זרה. משמע שאף מאהבה ומיראה קרויה עבודה זרה!","\u0003ורבא אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כי \u0003לא\u0004 כך יש להבין, אלא \u0003כ\u0004דרך \u0003ש\u0004\u0003מתרץ\u0004 \u0003ר' ירמיה,\u0004 שהכוונה בכפילות הדברים במשנה היא זו: אחד העובד עבודה זרה באופן שרגילים לעבוד בו עבודה זרה זו, ואחד המזבח והמקטר אף שאינו דרך עבודתה של אותה עבודה זרה.","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 ראיה לדברי? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"לא תשתחוה להם\u0004 ולא תעבדם\u0003\"\u0004 (שמות כ, ה), ומן ההדגשה \"להם\" למדים: \u0003להם,\u0004 לאלילים, \u0003אי\u0004 (אין) \u0003אתה משתחוה, אבל אתה משתחוה לאדם כמותך,\u0004 ואין בכך איסור, שכן אין בכך עבודה זרה אלא קבלת מרות בלבד. \u0003יכול\u0004 מותר להשתחוות \u0003אפילו\u0004 אם אדם זה \u0003נעבד,\u0004 שהוא נחשב בעצמו כעבודה זרה \u0003כ\u0004דרך שהיה נעבד \u0003המן?\u0004 — \u0003תלמוד לומר: \"ולא תעבדם\",\u0004 שכל שהוא עבודה זרה — אסור לעבדו. ומדייק אביי מכאן: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003המן מיראה הוה\u0004 \u0005[היה]\u0006 \u0003נעבד,\u0004 ולא משום שקיבלו אותו כאלוה, משמע שהעובד עבודה זרה מיראה חייב!","\u0003ורבא\u0004 מפרש את הברייתא הזו כך: \u0003כהמן\u0004 לענין אחד \u0003ולא כהמן\u0004 לכל דבר. \u0003כהמן\u0004 הכוונה \u0003דאיהו גופיה\u0004 \u0005[שהוא עצמו]\u0006 \u0003עבודה זרה\u0004 שהוא טוען שהוא אלוה, והעובדו משום שמאמין באלוהותו — חייב. \u0003ולא כהמן,\u0004 ש\u0003אילו המן מיראה\u0004 השתחוו לו, ואותו אדם שהשתחווה לו מיראה לא התחייב. \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מיראה\u0004 אלא שמקבל אותו עליו כאלוה באמת.","\u0003ו\u0004עוד \u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את שיטתי? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כהן משיח\u0004 (כהן גדול) לענין הבאת קרבן מיוחד על שגגת \u0003עבודה זרה,\u0004 באיזה מקרה הוא מביא קרבן זה? \u0003רבי אומר:\u0004 מביא הוא \u0003בשגגת מעשה,\u0004 כלומר, אם טעה ובלא יודעים עבד עבודה זרה. \u0003וחכמים אומרים:\u0004 אינו חייב אלא \u0003בהעלם דבר,\u0004 כלומר, כאשר טעה בדבר הלכה, וחשב שהדבר מותר,","\u0003ושוין\u0004 רבי וחכמים \u0003ש\u0004הכהן מביא על שגגת עבודה זרה \u0003שעירה\u0004 כמו \u0003יחיד\u0004 אחר ששגג בכך, ולא כמו בשגגת מצוות אחרות שהכהן מביא פר. \u0003ושוין שאין\u0004 הכהן הגדול \u0003מביא\u0004 כלל \u0003אשם תלוי,\u0004 שאשם תלוי מביאים כאשר יש ספק עובדתי אם נעשתה עבירה, ומן הכתובים למדו שכהן גדול, שדיני שגגתו שונים, אינו מביאו כלל.","ומעתה נברר \u0003האי\u0004 \u0005[זו]\u0006 \u0003שגגת\u0004 ה\u0003מעשה\u0004 שב\u0003עבודה זרה, היכי דמי\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבר]\u0006 הכהן לגבי בית מסויים ש\u0003בית הכנסת הוא והשתחוה לו,\u0004 ונמצא שהוא בית עבודה זרה — \u0003הרי לבו לשמים,\u0004 ולכל הדעות אין כאן אפילו שגגה, שהרי לא היה בלבו כל דבר לעבודה זרה, \u0003אלא\u0004 פירושו \u0003דחזא אנדרטא\u0004 \u0005[שראה פסל של אדם]\u0006 \u0003והשתחוה לו,\u0004 ואף כאן יש לברר:","\u0003אי קבליה עליה\u0004 \u0005[אם\u0006 תאמר \u0005שקיבלו עליו]\u0006 אותו אדם \u0003באלוה\u0004 — הרי \u0003מזיד הוא\u0004 בעבודה זרה, וחייב מיתה ממש, ולא קרבן."]]};
